// ══════════════════════════════════════════════════════════
// PROGRESS PERSISTENCE
// ══════════════════════════════════════════════════════════
// Klasöre yazma için debounce timer (sık çağrılmalarda kasma önler)
let _folderSaveTimer = null;

function saveProgress(){
  try{
    const _progData = JSON.stringify({learnedWords:[...learnedSet],wordStatus,score,streak,correctCount,idx});
    localStorage.setItem(fileKey, _progData);
    localStorage.setItem(fileKey+"_words", JSON.stringify(allWords));
    localStorage.setItem("wm_lastKey", fileKey);
    // IDB mirror (async, fire-and-forget)
    WMStore.set(fileKey, _progData).catch(()=>{});
    WMStore.set("wm_lastKey", fileKey).catch(()=>{});
    WMStore.saveAllWords(allWords).catch(()=>{});
    saveTimingData();

    // Analitik: Bugün öğrenilen kelime sayısını kaydet
    const today = new Date().toISOString().slice(0,10);
    const dayData = JSON.parse(localStorage.getItem('analytics_day_' + today) || '{"count":0,"hours":{}}');
    const hour = new Date().getHours();
    dayData.hours[hour] = (dayData.hours[hour] || 0) + 1;
    localStorage.setItem('analytics_day_' + today, JSON.stringify(dayData));

    // Klasör yedeklemesi — 10 sn debounce (her kayıtta tetiklenir ama sık yazma engellenir)
    if (backupFolderHandle) {
      clearTimeout(_folderSaveTimer);
      _folderSaveTimer = setTimeout(() => saveBackupToFolder(true), 10000);
    }
  }catch(e){
    console.error('❌ Progress save error:', e);
    if (e.name === 'QuotaExceededError') {
      alert('⚠️ Depolama alanı doldu! Eski verileri temizlemek için Ayarlar > Verileri Sil seçeneğini kullanın.');
    }
  }
}
async function loadProgress(){
  try{
    const raw=localStorage.getItem(fileKey) || await WMStore.get(fileKey).catch(()=>null);
    if(!raw) return false;
    const d=JSON.parse(raw);
    learnedSet=new Set(d.learnedWords||[]);
    wordStatus=d.wordStatus||{};
    score=d.score??100;streak=d.streak??0;correctCount=d.correctCount??0;idx=d.idx??0;
    
    // allWords yükle
    const wordsRaw=localStorage.getItem(fileKey+"_words");
    if(wordsRaw){
      try{
        allWords=JSON.parse(wordsRaw);
      }catch(e){console.error('allWords yükleme hatası:',e);}
    }
    
    // SRS verilerini yükle
    const srsRaw = localStorage.getItem("spacedRepetition");
    if(srsRaw){
      try{
        spacedRepetition = JSON.parse(srsRaw);
      }catch(e){ spacedRepetition = {}; }
    }
    
    return learnedSet.size>0;
  }catch(e){return false;}
}
function clearProgress(){
  try{
    localStorage.removeItem(fileKey);
    localStorage.removeItem(fileKey+"_words");
  }catch(e){
    console.error('❌ Clear progress error:', e);
  }
  learnedSet=new Set();
  wordStatus={};
}

function tryAutoRestore(){
  try{
    const lastKey=localStorage.getItem("wm_lastKey");
    if(!lastKey) return false;
    const saved=localStorage.getItem(lastKey+"_words");
    if(!saved) return false;
    const parsed=JSON.parse(saved);
    if(!parsed||parsed.length<2) return false;
    allWords=parsed;fileKey=lastKey;
    loadProgress();
    words=allWords.filter(w=>!learnedSet.has(w.word));
    if(words.length===0) words=[...allWords];
    
    // Direkt başlat (banner gösterme)
    startSession();
    return true;
  }catch(e){return false;}
}
function showResumeBanner(){
  const b=document.getElementById("resumeBanner");
  b.style.display="block";
  b.innerHTML=`<div style="font-weight:800;color:var(--text);margin-bottom:6px">📖 Kaldığın yerden devam et</div>
    <div style="font-size:12px;color:var(--muted);margin-bottom:10px">✅ Öğrenilen: <b style="color:var(--green)">${learnedSet.size}</b> &nbsp;·&nbsp; 📚 Kalan: <b style="color:var(--blue)">${words.length}</b></div>
    <div style="display:flex;gap:8px">
      <button onclick="resumeSession()" style="flex:1;padding:10px;background:var(--green);color:#052e16;border:none;border-radius:10px;font-family:'Nunito',sans-serif;font-size:13px;font-weight:800;cursor:pointer">▶ Devam Et</button>
      <button onclick="hideBanner()" style="flex:1;padding:10px;background:var(--bg3);color:var(--muted);border:none;border-radius:10px;font-family:'Nunito',sans-serif;font-size:13px;font-weight:700;cursor:pointer">📂 Yeni Dosya</button>
    </div>`;
}
function resumeSession(){document.getElementById("resumeBanner").style.display="none";if(idx>=words.length)idx=0;startSession();}
function hideBanner(){document.getElementById("resumeBanner").style.display="none";}

// ══════════════════════════════════════════════════════════
// SESSION
// ══════════════════════════════════════════════════════════
function startSession(){
  
  showScreen("sc-word");
  smWords=[...words];smIdx=0;
  lmWords=[...words];lmIdx=0;
  fcWords=[...words];fcIdx=0;
  sessionStart=Date.now();
  renderLearn();
  renderStats();
}
function restartQuiz(){clearProgress();words=[...allWords];smWords=[...words];lmWords=[...words];fcWords=[...words];idx=0;smIdx=0;lmIdx=0;fcIdx=0;score=100;streak=0;correctCount=0;showScreen("sc-word");renderLearn();}
function goUpload(){stopSpeech();showScreen("sc-upload");document.getElementById("bottomNav").style.display="none";}
function continueOrDone(){
  const rem=allWords.filter(w=>!learnedSet.has(w.word));
  if(rem.length===0){if(confirm("🎉 Tüm kelimeler öğrenildi!\nBaştan başlamak ister misin?"))restartQuiz();}
  else{words=rem;smWords=[...rem];lmWords=[...rem];fcWords=[...rem];idx=0;smIdx=0;lmIdx=0;fcIdx=0;score=100;streak=0;correctCount=0;showScreen("sc-word");renderLearn();}
}

// ══════════════════════════════════════════════════════════
// SCORE BAR
// ══════════════════════════════════════════════════════════
function getActiveListName(){
  try{
    if (typeof activeListId !== 'undefined' && activeListId && Array.isArray(multiLists)) {
      const activeList = multiLists.find(l => String(l.id) === String(activeListId));
      if (activeList && activeList.name) return activeList.name;
    }
    const storedName = localStorage.getItem('activeListName') || localStorage.getItem('wm.activeListName') || localStorage.getItem('currentListName');
    if (storedName && storedName.trim()) return storedName.trim();
  }catch(e){}
  return 'Ana Liste';
}

function setActiveListTitle(name){
  const listName = (name && String(name).trim()) ? String(name).trim() : getActiveListName();
  try{
    localStorage.setItem('activeListName', listName);
    localStorage.setItem('wm.activeListName', listName);
    localStorage.setItem('currentListName', listName);
  }catch(e){}
  const title = document.getElementById('currentListName');
  if (title && title.textContent.trim() !== listName) title.textContent = listName;
  const wcLabel = document.querySelector('#wordCard .wc-label');
  if (wcLabel) {
    const item = (typeof words !== 'undefined' && Array.isArray(words)) ? words[idx] : null;
    wcLabel.innerHTML = listName + (item && item.rowNum ? `<span style="opacity:0.5;font-size:10px;margin-left:8px">#${item.rowNum}</span>` : '');
  }
  return listName;
}

function saveCurrentListProgress(){
  try{
    if (typeof activeListId !== 'undefined' && activeListId) {
      const currentProgress = { wordStatus, learnedSet: [...learnedSet], spacedRepetition, idx, score, streak, correctCount };
      localStorage.setItem('listProgress_' + activeListId, JSON.stringify(currentProgress));
    }
  }catch(e){ console.warn('Aktif liste ilerlemesi kaydedilemedi:', e); }
}

function updateScoreBar(){
  const scoreNum = document.getElementById("scoreNum");
  const fill = document.getElementById("scoreFill");
  const scoreLbl = document.getElementById("scoreLbl");
  if(!scoreNum || !fill || !scoreLbl) return;
  scoreNum.textContent=score;
  const col=score>=85?"#22c55e":score>=70?"#3b82f6":score>=50?"#f97316":"#ef4444";
  fill.style.width=score+"%";fill.style.background=col;
  scoreNum.style.color=col;
  const scoreText = score>=85?"Mükemmel":score>=70?"İyi":score>=50?"Orta":"Düşük";
  scoreLbl.textContent = scoreText;
  setActiveListTitle(getActiveListName());
}

// ══════════════════════════════════════════════════════════
// RENDER LEARN
// ══════════════════════════════════════════════════════════
function mkSentColored(sentence,highlights,colors){
  if(!sentence) return "";
  
  // Önce **kelime** formatını işle
  sentence = sentence.replace(/\*\*([^*]+?)\*\*/g, '<b>$1</b>');
  
  return sentence.split(/(\s+)/).map(p=>{
    const c=p.replace(/[^a-zA-Z]/g,"").toLowerCase();
    const col=colors&&c&&colors[c];
    
    // Renkli kelime - tıklanabilir yap
    if(col) {
      const cleanWord = p.replace(/[^a-zA-Z]/g,'');
      return `<span style="color:${col};font-weight:800;cursor:pointer;transition:all 0.2s" onclick="explainWord('${cleanWord}','wordCard')" onmouseenter="this.style.transform='scale(1.05)'" onmouseleave="this.style.transform='scale(1)'">${p}</span>`;
    }
    
    // Vurgulu kelime (yeşil) - tıklanabilir yap
    if(highlights&&highlights.some(h=>h&&h.toLowerCase()===c)) {
      const cleanWord = p.replace(/[^a-zA-Z]/g,'');
      return `<span class="hl" style="cursor:pointer;transition:all 0.2s" onclick="explainWord('${cleanWord}','wordCard')" onmouseenter="this.style.transform='scale(1.05)'" onmouseleave="this.style.transform='scale(1)'">${p}</span>`;
    }
    
    // DİĞER KELİMELER - Eğer 2+ harf içeriyorsa onları da tıklanabilir yap
    if(c && c.length >= 2) {
      return `<span class="word-clickable" style="cursor:pointer" onclick="explainWord('${c}','wordCard')">${p}</span>`;
    }
    
    return p;
  }).join("");
}

async function renderLearn(){
  phase="learn";stopSpeech();
  const item=words[idx];
  if(!item || !item.word) return;
  
  updateScoreBar();
  document.getElementById("progFill").style.width=(idx/words.length*100)+"%";
  const sb=document.getElementById("streakBadge");
  if(streak>=2){sb.style.display="";sb.textContent="🔥 "+streak;}else sb.style.display="none";
  const ph=item.phonetic?`<div class="wc-phonetic">${item.phonetic}</div>`:"";
  let sentHTML="";
  if(item.sentence){
    sentHTML=`<div class="wc-sent">${mkSentColored(item.sentence,item.highlights,item.colors)}</div>`;
    if(item.sentenceTr) sentHTML+=`<div class="wc-sent-tr">${item.sentenceTr}</div>`;
  }
  // SRS rozeti - DÜZELTME: Hiç çalışılmamış ve çalışılmış kelimeleri ayır
  const srsData = spacedRepetition[item.word];
  const isStudied = srsData !== undefined; // Kelime daha önce çalışılmış mı?
  const srsLevel = srsData ? srsData.level : 0;
  const srsLabels = ['🌱 Yeni','📘 Başlangıç','📗 Orta','📙 İyi','⭐ Güçlü','🌟 Çok Güçlü','🏆 Uzman'];
  const srsColors = ['#6366f1','#3b82f6','#10b981','#f59e0b','#f97316','#ec4899','#8b5cf6'];
  const srsNextDate = srsData ? new Date(srsData.nextReview) : null;
  const srsNextStr = srsNextDate
    ? (srsData.nextReview <= Date.now() ? '⏰ Tekrar zamanı!' : '📅 ' + srsNextDate.toLocaleDateString('tr-TR'))
    : '';
  
  // Rozet HTML'i - Hiç çalışılmamış kelimeler için özel durum
  let srsBadge;
  if (!isStudied) {
    // Hiç çalışılmamış kelime - sadece "Henüz çalışılmadı" göster
    srsBadge = `<div style="display:flex;align-items:center;gap:6px;margin-bottom:8px;flex-wrap:wrap">
      <span style="background:#64748b;color:#e2e8f0;padding:2px 8px;border-radius:20px;font-size:11px;font-weight:800">❌ Henüz çalışılmadı</span>
    </div>`;
  } else {
    // Çalışılmış kelime - seviye rozetini göster
    srsBadge = `<div style="display:flex;align-items:center;gap:6px;margin-bottom:8px;flex-wrap:wrap">
      <span style="background:${srsColors[srsLevel]};color:#fff;padding:2px 8px;border-radius:20px;font-size:11px;font-weight:800">${srsLabels[srsLevel]||'🏆 Uzman'}</span>
      <span style="font-size:11px;color:var(--muted)">${srsNextStr}</span>
    </div>`;
  }
  const activeListDisplayName = getActiveListName();
  document.getElementById("wordCard").innerHTML=`
    <div class="wc-label">${activeListDisplayName}${item.rowNum?`<span style="opacity:0.5;font-size:10px;margin-left:8px">#${item.rowNum}</span>`:''}</div>
    ${srsBadge}
    <div class="wc-word" style="cursor:pointer;transition:all 0.2s" onclick="explainWord('${item.word.replace(/'/g,"\\'")}','wordCard')" onmouseenter="this.style.transform='scale(1.05)'" onmouseleave="this.style.transform='scale(1)'">${item.word}</div>
    ${ph}
    <div class="wc-tr">${item.tr}</div>
    ${sentHTML}
    <div class="sent-img-wrap" id="sentImgWrap" style="margin-top:12px">
      <img class="sent-img" id="sentImg" alt="">
      <div class="img-credit" id="imgCredit"></div>
    </div>
    <!-- Resmin altı: İleri/Geri + Kelime/Cümle (eski wordQuickBar buraya taşındı) -->
    <div style="display:grid;grid-template-columns:auto 1fr auto;gap:8px;align-items:center;margin-top:12px;padding:10px;background:var(--bg3);border:1.5px solid var(--border);border-radius:14px">
      <button onclick="prevWord()" title="Önceki kelime (←)" aria-label="Önceki kelime" style="padding:10px 14px;background:linear-gradient(135deg,#3b82f6,#2563eb);border:none;border-radius:10px;color:#fff;font-size:16px;font-weight:800;cursor:pointer;min-width:48px">◀</button>
      <div style="display:grid;grid-template-columns:1fr 1fr;gap:6px">
        <button onclick="speakWord()" title="Kelimeyi seslendir" style="padding:10px 8px;background:linear-gradient(135deg,#22c55e,#16a34a);border:none;border-radius:10px;color:#fff;font-size:12px;font-weight:800;cursor:pointer;font-family:'Nunito',sans-serif">🔊 Kelime</button>
        <button onclick="speakSentence()" title="Cümleyi seslendir" style="padding:10px 8px;background:linear-gradient(135deg,#8b5cf6,#7c3aed);border:none;border-radius:10px;color:#fff;font-size:12px;font-weight:800;cursor:pointer;font-family:'Nunito',sans-serif">🔊 Cümle</button>
      </div>
      <button onclick="navNextWord()" title="Sonraki kelime (→)" aria-label="Sonraki kelime" style="padding:10px 14px;background:linear-gradient(135deg,#3b82f6,#2563eb);border:none;border-radius:10px;color:#fff;font-size:16px;font-weight:800;cursor:pointer;min-width:48px">▶</button>
    </div>`;
  const bl=document.getElementById("btnLearned");
  if(learnedSet.has(item.word)){bl.textContent="✓ Öğrenildi";bl.classList.add("done");}
  else{bl.textContent="✅ Öğrendim";bl.classList.remove("done");}
  document.getElementById("btnSpkSent").style.display=item.sentence?"":"none";
  document.getElementById("btnSpkTr").style.display=(item.sentenceTr||item.tr)?"":"none";
  document.getElementById("pronunTarget").innerHTML=item.sentence?mkSentColored(item.sentence,item.highlights,item.colors):`<strong>${item.word}</strong>`;
  document.getElementById("pronunPanel").style.display="none";
  resetPronun();
  const quizArea = document.getElementById("quizArea");
  if(quizArea) quizArea.style.display="none";
  const aiFeedback = document.getElementById("aiFeedback");
  if(aiFeedback) aiFeedback.style.display="none";
  const btnQuiz = document.getElementById("btnQuiz");
  if(btnQuiz) btnQuiz.style.display="";
  const btnNext = document.getElementById("btnNext");
  if(btnNext) btnNext.style.display="none";
  const wc=document.getElementById("wordCounter");
  if(wc) wc.textContent=(idx+1)+" / "+words.length+" kelime";
  loadSentenceImage(item.sentence||"",item.word);
  animCard("fadeIn");
  
  // Tekrar edilecek kelime sayısını güncelle
  updateReviewCount();
  
  // 9. Otomatik ses çalma - SADECE KELIME DEĞİŞTİĞİNDE VE NAVIGASYON BUTONU İLE
  // Her renderLearn çağrısında ses çalmaması için flag sistemi
  if(!window.lastRenderedWord) window.lastRenderedWord = '';
  if(!window.lastRenderedIndex) window.lastRenderedIndex = -1;
  
  const shouldPlayAudio = autoPlayAudio && 
                         (window.lastRenderedWord !== item.word || window.lastRenderedIndex !== idx);
  
  window.lastRenderedWord = item.word;
  window.lastRenderedIndex = idx;
  
  if(shouldPlayAudio){
    setTimeout(()=>{
      if(item.sentence) speakSentence();
      else speakWord();
    },300);
  }
}

// ══════════════════════════════════════════════════════════
// NAVIGATION
// ══════════════════════════════════════════════════════════
function prevWord(){if(idx>0){idx--;phase="learn";renderLearn();updateWordCounter();}}
function navNextWord(){if(idx+1<words.length){idx++;phase="learn";renderLearn();}}
function nextWord(){
  idx++;
  while(idx<words.length&&learnedSet.has(words[idx]?.word))idx++;
  if(idx>=words.length)showDone();
  else{phase="learn";renderLearn();}
  updateWordCounter();
}

// Klavye okları: yalnızca kelime ekranı açıkken ve bir input/textarea odakta değilken çalışır
document.addEventListener('keydown', function(e){
  if (e.key !== 'ArrowLeft' && e.key !== 'ArrowRight') return;
  const sc = document.getElementById('sc-word');
  if (!sc || !sc.classList.contains('active')) return;
  const t = e.target;
  if (t && (t.tagName === 'INPUT' || t.tagName === 'TEXTAREA' || t.isContentEditable)) return;
  // Modal/overlay açıksa devre dışı
  if (document.querySelector('.modal-overlay')) return;
  if (e.key === 'ArrowLeft')  { e.preventDefault(); prevWord(); }
  if (e.key === 'ArrowRight') { e.preventDefault(); navNextWord(); }
});
function showList(){
  // Hangi ekrandan geldiğini kaydet
  const currentScreen = document.querySelector('.screen.active')?.id || 'sc-word';
  localStorage.setItem('listReturnScreen', currentScreen);
  
  showScreen("sc-list");
  const total=allWords.length,learned=learnedSet.size;
  const failed=Object.values(wordStatus).filter(s=>s.attempts>0&&s.correct===0).length;
  const unseen=total-Object.keys(wordStatus).length;
  document.getElementById("listStats").innerHTML=`
    <div class="list-stat"><div class="sn" style="color:var(--green)">${learned}</div><div class="sl">✅ Öğrenildi</div></div>
    <div class="list-stat"><div class="sn" style="color:var(--orange)">${failed}</div><div class="sl">❌ Yanlış</div></div>
    <div class="list-stat"><div class="sn" style="color:var(--muted)">${unseen}</div><div class="sl">⬜ Görülmedi</div></div>`;
  renderWordList();
}

// Virtual Scrolling Değişkenleri
const ITEM_HEIGHT = 85; // Her kelime item yüksekliği (px)
const BUFFER_SIZE = 5; // Ekstra yüklenecek item sayısı
let virtualScrollData = {
  scrollTop: 0,
  containerHeight: 600,
  visibleStart: 0,
  visibleEnd: 50
};

function renderWordList(){
  const listEl=document.getElementById("wordListEl");
  if(!listEl) return;
  
  // Filtrelenmiş kelimeleri al
  let filteredWords = getFilteredWords();
  
  // Arama query varsa ek filtre uygula
  if (currentSearchQuery) {
    filteredWords = filteredWords.filter(w => {
      const sentence = w.sentence || '';
      return sentence.toLowerCase().includes(currentSearchQuery);
    });
  }
  
  // Virtual scroll container setup
  const totalHeight = filteredWords.length * ITEM_HEIGHT;
  listEl.style.position = "relative";
  listEl.style.height = `${Math.min(totalHeight, 600)}px`;
  listEl.style.overflowY = "auto";
  
  // Virtual content wrapper
  let contentWrapper = listEl.querySelector('.virtual-content');
  if(!contentWrapper){
    contentWrapper = document.createElement('div');
    contentWrapper.className = 'virtual-content';
    contentWrapper.style.position = 'relative';
    contentWrapper.style.height = `${totalHeight}px`;
    listEl.innerHTML = '';
    listEl.appendChild(contentWrapper);
    
    // Scroll event
    listEl.addEventListener('scroll', ()=>{
      virtualScrollData.scrollTop = listEl.scrollTop;
      updateVisibleItems();
    });
  }else{
    // Wrapper yüksekliğini güncelle
    contentWrapper.style.height = `${totalHeight}px`;
  }
  
  // Filtrelenmiş kelimeleri kaydet (updateVisibleItems için)
  virtualScrollData.filteredWords = filteredWords;
  
  updateVisibleItems();
}

function updateVisibleItems(){
  const listEl = document.getElementById("wordListEl");
  const contentWrapper = listEl?.querySelector('.virtual-content');
  if(!contentWrapper) return;
  
  // Filtrelenmiş kelime listesini kullan
  const wordList = virtualScrollData.filteredWords || allWords;
  
  // Hangi itemler görünecek hesapla
  const scrollTop = virtualScrollData.scrollTop;
  const containerHeight = listEl.clientHeight;
  
  const start = Math.floor(scrollTop / ITEM_HEIGHT);
  const end = Math.ceil((scrollTop + containerHeight) / ITEM_HEIGHT) + BUFFER_SIZE;
  
  const visibleStart = Math.max(0, start - BUFFER_SIZE);
  const visibleEnd = Math.min(wordList.length, end);
  
  // Aynı range'deyse tekrar render etme
  if(visibleStart === virtualScrollData.visibleStart && visibleEnd === virtualScrollData.visibleEnd){
    return;
  }
  
  virtualScrollData.visibleStart = visibleStart;
  virtualScrollData.visibleEnd = visibleEnd;
  
  // Sadece görünen itemleri render et
  const fragment = document.createDocumentFragment();
  
  for(let i = visibleStart; i < visibleEnd; i++){
    const w = wordList[i];
    if(!w || !w.word) continue;
    
    const st = wordStatus[w.word];
    const isL = learnedSet.has(w.word);
    const isF = st && st.attempts > 0 && st.correct === 0;
    const cls = isL ? "learned" : isF ? "failed" : "unseen";
    const ico = isL ? "✅" : isF ? "❌" : "⬜";
    
    // SRS seviyesini öğrenildi rozetine ekle
    let mb;
    if (isL) {
      const srsData = spacedRepetition[w.word];
      const srsLevel = srsData ? srsData.level : 0;
      const srsLabels = ['🌱 Başlangıç','📗 Orta','📙 İyi','⭐ Güçlü','🌟 Çok Güçlü','🏆 Uzman'];
      const srsLabel = srsLabels[srsLevel] || '🏆 Uzman';
      mb = `<span class="badge bl">${srsLabel}</span>`;
    } else if (isF) {
      mb = `<span class="badge bf">${st.attempts} deneme</span>`;
    } else {
      mb = `<span class="badge bu">Görülmedi</span>`;
    }
    
    const pb = st && st.pronScore != null ? `<span class="badge bp">🎤${st.pronScore}</span>` : "";
    const rowBadge = w.rowNum ? `<span style="opacity:0.5;font-size:11px;margin-left:4px">#${w.rowNum}</span>` : "";
    
    // ✅ GÖREV #6: Pronunciation ekle
    const pronHTML = w.pronunciation ? `<div style="font-size:11px;color:var(--purple);margin-top:2px">🔊 /${w.pronunciation}/</div>` : "";
    
    // Cümle formatı: İngilizce (bold) üstte, Türkçe altta
    const sentenceHTML = w.sentence ? `<div style="font-size:14px;font-weight:700;color:var(--text);margin-top:4px;line-height:1.4">${w.sentence.length > 80 ? w.sentence.substring(0, 80) + '...' : w.sentence}</div>` : "";
    const sentenceTrHTML = w.sentenceTr ? `<div style="font-size:13px;color:var(--muted);margin-top:2px;line-height:1.4">${w.sentenceTr.length > 80 ? w.sentenceTr.substring(0, 80) + '...' : w.sentenceTr}</div>` : "";
    
    const itemDiv = document.createElement("div");
    itemDiv.className = `wi ${cls}`;
    itemDiv.style.position = "absolute";
    itemDiv.style.top = `${i * ITEM_HEIGHT}px`;
    itemDiv.style.width = "100%";
    itemDiv.style.height = `${ITEM_HEIGHT}px`;
    itemDiv.innerHTML = `
      <div class="wi-ico">${ico}</div>
      <div class="wi-body" onclick="goToWord(${i}, virtualScrollData.filteredWords || allWords)" style="flex:1;cursor:pointer">
        <div class="wi-word">${w.word}${rowBadge}</div>
        ${pronHTML}
        ${sentenceHTML}
        ${sentenceTrHTML}
      </div>
      <div class="wi-badges">${mb}${pb}</div>
      <button onclick="deleteWord('${w.word.replace(/'/g,"\\'")}', event)" style="background:var(--red);color:#fff;border:none;border-radius:8px;padding:8px 12px;font-size:18px;cursor:pointer;margin-left:8px">🗑️</button>`;
    fragment.appendChild(itemDiv);
  }
  
  contentWrapper.innerHTML = "";
  contentWrapper.appendChild(fragment);
}
// Kelime sil
function deleteWord(word, event){
  if(event) event.stopPropagation(); // Kelimeye tıklama olayını engelle
  
  if(!confirm(`"${word}" kelimesini silmek istediğine emin misin?`)) return;
  
  const currentListId = localStorage.getItem('currentListId') || 'default';
  
  if(currentListId === 'default'){
    // Ana listeden sil
    allWords = allWords.filter(w => w.word !== word);
    localStorage.setItem('learnedWords', JSON.stringify(allWords));
  }else{
    // Özel listeden sil
    const lists = JSON.parse(localStorage.getItem('wordLists') || '[]');
    const list = lists.find(l => l.id === currentListId);
    if(list){
      list.words = list.words.filter(w => w.word !== word);
      allWords = list.words;
      localStorage.setItem('wordLists', JSON.stringify(lists));
    }
  }
  
  // SRS ve wordStatus'tan da sil
  delete spacedRepetition[word];
  delete wordStatus[word];
  learnedSet.delete(word);
  
  // words array'ini de güncelle
  words = allWords;
  
  // localStorage'ı güncelle
  if(currentListId === 'default'){
    const fileKey = localStorage.getItem('currentFileKey') || 'default';
    localStorage.setItem(fileKey, JSON.stringify({
      learnedWords: [...learnedSet],
      wordStatus,
      score,
      streak,
      correctCount,
      idx
    }));
  }
  
  showToast('🗑️ Silindi', word);
  
  // Liste istatistiklerini güncelle
  showList();
}

