function switchTab(tab){
  // Telaffuz ekranından çıkıldığında mikrofonu zorla kapat (mikrofonun açık kalmasını önler)
  if (typeof spForceCleanup === 'function' && currentTab === 'pronstandalone' && tab !== 'pronstandalone') {
    spForceCleanup();
  }

  if(tab==="realnew"){
    currentTab = tab;
    document.querySelectorAll(".bnav-btn").forEach(b=>b.classList.remove("active"));
    document.getElementById("bn-realnew")?.classList.add("active");
    showScreen("sc-realnew");
    return;
  }

  // Ana menüyü gizle
  document.getElementById("sc-menu").classList.remove("active");
  document.getElementById("sc-menu").style.display = "none";
  
  currentTab=tab;
  document.querySelectorAll(".bnav-btn").forEach(b=>b.classList.remove("active"));
  document.getElementById("bn-"+tab)?.classList.add("active");
  if(tab==="word"){showScreen("sc-word");if(words.length) renderLearn();}
  else if(tab==="flashcard"){showScreen("sc-flashcard");if(!fcWords.length)initFlashcards();else renderFlashcard();}
  else if(tab==="sent"){showScreen("sc-sent");renderSentMode();}
  else if(tab==="letter"){showScreen("sc-letter");renderLetterMode();}
  else if(tab==="daily"){showScreen("sc-daily");initDailyDashboard();}
  else if(tab==="pronstandalone"){showScreen("sc-pronstandalone");if(typeof initStandalonePron==='function')initStandalonePron();}
  else if(tab==="stats"){showScreen("sc-stats");renderStats();}
  else if(tab==="games"){showScreen("sc-games");openGamesMenu();}
  else if(tab==="ai"){showScreen("sc-ai");if(!chatHistory.length)initAIChat();}
  else if(tab==="askai"){showScreen("sc-askai");if(typeof initAskAIPage==='function')initAskAIPage();}
  else if(tab==="dictbuilder"){showScreen("sc-dictbuilder");if(typeof initDictBuilder==='function')initDictBuilder();}
  else if(tab==="cameraCoach"){showScreen("sc-camera-coach");if(typeof initCameraCoach==='function')initCameraCoach();}
  else if(tab==="learned"){showScreen("sc-learned");renderLearnedWordsScreen();}
  else if(tab==="settings"){showScreen("sc-settings");loadAITokenSettings();updateLastSaveTime();if(typeof renderPromptsUI==='function')renderPromptsUI();}
}

// Liste seçici göster
function showListSelector(){
  // ✅ Doğru kaynak: multiLists (eskiden yanlışlıkla 'wordLists' okunuyordu)
  const lists = (typeof multiLists !== 'undefined' && multiLists) ? multiLists : [];
  const currentId = (typeof activeListId !== 'undefined') ? activeListId : null;

  let html = '<div style="position:fixed;top:0;left:0;width:100%;height:100%;background:rgba(0,0,0,0.8);z-index:10000;display:flex;align-items:center;justify-content:center;padding:16px" onclick="this.remove()">';
  html += '<div style="background:var(--bg);padding:20px;border-radius:16px;max-width:420px;width:100%;max-height:80vh;overflow-y:auto;border:1px solid var(--border)" onclick="event.stopPropagation()">';
  html += '<h3 style="margin:0 0 16px 0;font-family:\'Nunito\',sans-serif;color:var(--text)">📚 Listelerim</h3>';

  // "Ana Liste" — aktif liste yoksa burada
  const isMainActive = !currentId;
  html += `<div onclick="_pickMainList()" style="padding:12px;background:${isMainActive?'var(--blue)':'var(--bg2)'};color:${isMainActive?'#fff':'var(--text)'};border-radius:10px;margin-bottom:8px;cursor:pointer;font-weight:${isMainActive?'700':'500'};font-family:'Nunito',sans-serif">📖 Ana Liste ${isMainActive?'✓':''}</div>`;

  // Kullanıcının kendi listeleri (multiLists)
  if (lists.length === 0) {
    html += '<div style="padding:12px;color:var(--muted);font-size:12px;text-align:center;font-family:\'Nunito\',sans-serif">Henüz başka liste yok.</div>';
  } else {
    lists.forEach(l => {
      const isActive = l.id === currentId;
      const pct = l.wordCount > 0 ? '' : '';
      html += `<div onclick="_pickMultiList('${l.id.replace(/'/g,"\\'")}')" style="padding:12px;background:${isActive?'var(--blue)':'var(--bg2)'};color:${isActive?'#fff':'var(--text)'};border-radius:10px;margin-bottom:8px;cursor:pointer;font-weight:${isActive?'700':'500'};font-family:'Nunito',sans-serif;display:flex;align-items:center;justify-content:space-between;gap:8px">
        <span>${l.emoji||'📝'} ${l.name}</span>
        <span style="font-size:11px;opacity:.7">${l.wordCount||0} kelime${isActive?' ✓':''}</span>
      </div>`;
    });
  }

  html += '<button onclick="this.parentElement.parentElement.remove()" style="width:100%;padding:12px;background:var(--bg2);color:var(--text);border:1px solid var(--border);border-radius:10px;margin-top:12px;cursor:pointer;font-weight:700;font-family:\'Nunito\',sans-serif">Kapat</button>';
  html += '</div></div>';

  document.body.insertAdjacentHTML('beforeend', html);
}

// Modal'dan ana liste seçimi
function _pickMainList() {
  // Modal'ı kapat
  document.querySelectorAll('div[style*="position:fixed"][style*="z-index:10000"]').forEach(el => el.remove());
  // Zaten ana listedeyse bir şey yapma
  if (!activeListId) return;
  // multiList'ten ana listeye dönüş: aktif liste id'sini temizle ve eski ana liste verisini yükle
  // En basiti: kullanıcıyı kelime listesi ekranına yönlendir, böylece "Ana Liste" yolunu seçebilir
  try {
    // İlerlemeyi kaydet
    if (activeListId && typeof wordStatus !== 'undefined') {
      const currentProgress = { wordStatus, learnedSet: [...learnedSet], spacedRepetition };
      localStorage.setItem('listProgress_' + activeListId, JSON.stringify(currentProgress));
    }
    activeListId = null;
    localStorage.removeItem('activeListId');
    localStorage.setItem('activeListName','Ana Liste');
    localStorage.setItem('wm.activeListName','Ana Liste');
    localStorage.setItem('currentListName','Ana Liste');
    if (typeof setActiveListTitle === 'function') setActiveListTitle('Ana Liste');
    // Ana listeye dön — multi-list listeleme ekranına git, kullanıcı oradan yönetir
    if (typeof showList === 'function') showList();
    else if (typeof showScreen === 'function') showScreen('sc-multilist');
  } catch(e) { console.warn('Ana liste seçimi hatası:', e); }
  showToast('📖 Ana Liste', 'Aktif liste sıfırlandı');
}

// Modal'dan multiList seçimi
function _pickMultiList(id) {
  document.querySelectorAll('div[style*="position:fixed"][style*="z-index:10000"]').forEach(el => el.remove());
  if (typeof switchToList === 'function') switchToList(id);
}

// Liste değiştir
function switchList(listId){
  localStorage.setItem('currentListId',listId);
  
  // Liste ismini güncelle
  const lists = JSON.parse(localStorage.getItem('wordLists')||'[]');
  const list = lists.find(l=>l.id===listId);
  const listName = list ? list.name : 'Ana Liste';
  document.getElementById('currentListName').textContent = listName;
  
  // Kelimeleri yükle
  loadWordsFromList(listId);
  
  // Popup'ı kapat
  document.querySelector('[style*="position:fixed"]')?.remove();
  
  showToast('✅ '+listName,'Aktif liste');
}

// Listeden kelimeleri yükle
function loadWordsFromList(listId){
  if(listId==='default'){
    // Ana liste - learnedWords
    allWords = JSON.parse(localStorage.getItem('learnedWords')||'[]');
  }else{
    // Özel liste
    const lists = JSON.parse(localStorage.getItem('wordLists')||'[]');
    const list = lists.find(l=>l.id===listId);
    allWords = list ? list.words : [];
  }
  
  words = allWords;
  idx = 0;
  
  // Kelime sayısını güncelle
  updateWordCounter();
}

// Yeni liste oluştur
function createNewList(){
  const name = prompt('Liste adı:');
  if(!name) return;
  
  const emoji = prompt('Emoji (opsiyonel):') || '📝';
  
  const lists = JSON.parse(localStorage.getItem('wordLists')||'[]');
  const newList = {
    id: 'list_'+Date.now(),
    name: name,
    emoji: emoji,
    words: [],
    createdAt: Date.now()
  };
  
  lists.push(newList);
  localStorage.setItem('wordLists',JSON.stringify(lists));
  
  showToast('✅ Liste oluşturuldu',name);
  
  // Popup'ı kapat ve yeniden aç
  document.querySelector('[style*="position:fixed"]')?.remove();
  showListSelector();
}

function goHome() {
  document.querySelectorAll(".screen").forEach(s => {
    s.classList.remove("active");
    s.style.display = "none";
  });
  document.getElementById("sc-menu").classList.add("active");
  document.getElementById("sc-menu").style.display = "block";
  document.getElementById("bottomNav").style.display = "none";
}

// ══════════════════════════════════════════════════════════
// SENTENCE MODE
// ══════════════════════════════════════════════════════════
let smSelected=null;

function renderSentMode(){
  if(!smWords.length){document.querySelector("#sc-sent .card").innerHTML="<p style='color:var(--muted);text-align:center;padding:20px'>Kelime yükle ve Word Mode'dan başla.</p>";return;}
  if(smIdx>=smWords.length) smIdx=0;
  const item=smWords[smIdx];
  document.getElementById("smCounter").textContent=(smIdx+1)+" / "+smWords.length;
  const sent=item.sentence||item.word;
  const tokenWords=sent.split(/(\s+)/).filter(t=>t.trim());
  const shuffled=[...tokenWords].sort(()=>Math.random()-.5);
  smSelected=null;
  document.getElementById("smAnswer").innerHTML="";
  document.getElementById("smBank").innerHTML=shuffled.map((w,i)=>{
    const clean=w.replace(/[^a-zA-Z]/g,"").toLowerCase();
    const found=allWords.find(x=>x.word.toLowerCase()===clean);
    const wTr=found?found.tr:(clean===item.word.toLowerCase()?item.tr:"");
    return `<div class="sm-word" id="smw${i}" data-word="${w}" data-idx="${i}" data-tr="${(wTr||'').replace(/"/g,'&quot;')}"
      onclick="smWordClick(${i})"
      onpointerdown="smLongPressStart(${i})"
      onpointerup="smLongPressEnd()"
      onpointercancel="smLongPressEnd()">
      ${w}
      <div class="word-tooltip" id="tip${i}"></div>
    </div>`;
  }).join("");
  document.getElementById("smFeedback").style.display="none";
  document.getElementById("smNext").style.display="none";
  document.getElementById("smPronunResult").style.display="none";
  const spb=document.getElementById("smBtnPrev");
  const snb=document.getElementById("smBtnNext");
  if(spb)spb.disabled=(smIdx===0);
  if(snb)snb.disabled=(smIdx>=smWords.length-1);
  resetSMSpeech();
}

let lpTimer=null;
const tipCache={};

let smLongPressed=false;
function smLongPressStart(i){
  smLongPressed=false;
  lpTimer=setTimeout(()=>{
    smLongPressed=true;
    const el=document.getElementById("smw"+i);
    if(!el) return;
    const rawWord=el.dataset.word||"";
    const clean=rawWord.replace(/[^a-zA-Z]/g,"").toLowerCase();
    if(!clean) return;
    navigator.vibrate&&navigator.vibrate(50);
    _explainWordImpl(clean,'chatMessages');
  },600);
}
function smLongPressEnd(){clearTimeout(lpTimer);}

function smWordClick(i){
  if(smLongPressed){smLongPressed=false;return;}
  const el=document.getElementById("smw"+i);
  if(!el||el.dataset.placed==="1") return;
  // move to answer
  el.dataset.placed="1";
  el.style.opacity="0.3";
  const w=el.dataset.word;
  const ansEl=document.getElementById("smAnswer");
  const slot=document.createElement("div");
  slot.className="sm-word";slot.textContent=w;slot.dataset.srcIdx=i;
  slot.onclick=()=>{
    // return to bank
    el.style.opacity="1";el.dataset.placed="0";
    slot.remove();
  };
  ansEl.appendChild(slot);
}

function checkSentence(){
  const item=smWords[smIdx];
  const sent=item.sentence||item.word;
  const correct=sent.split(/(\s+)/).filter(t=>t.trim());
  const answer=[...document.getElementById("smAnswer").querySelectorAll(".sm-word")].map(el=>el.textContent.trim());
  if(answer.length===0){alert("Önce kelimeleri sırala!");return;}
  const isCorrect=answer.join(" ")===correct.join(" ");
  const fb=document.getElementById("smFeedback");
  fb.style.display="block";
  if(isCorrect){
    fb.style.background="#052e16";fb.style.color="#4ade80";fb.style.border="1.5px solid #166534";
    fb.textContent="✅ Harika! Doğru sıraladın!";
    document.getElementById("smNext").style.display="";
    // color words green
    document.getElementById("smAnswer").querySelectorAll(".sm-word").forEach(el=>el.classList.add("correct"));
  }else{
    fb.style.background="#1c0a00";fb.style.color="#fb923c";fb.style.border="1.5px solid #7c2d12";
    fb.textContent="❌ Yanlış. Doğru: "+correct.join(" ");
    document.getElementById("smAnswer").querySelectorAll(".sm-word").forEach((el,i)=>{
      el.classList.add(el.textContent.trim()===correct[i]?"correct":"wrong");
    });
    document.getElementById("smNext").style.display="";
  }
}
function resetSentMode(){smSelected=null;renderSentMode();}
function smPrev(){if(smIdx>0){smIdx--;renderSentMode();}}
function smNavNext(){if(smIdx<smWords.length-1){smIdx++;renderSentMode();}}
function nextSentMode(){smIdx++;renderSentMode();}

function startSentenceModeWithWord(targetWord) {
  // smWords listesini tüm kelimelerle yükle
  if (smWords.length === 0) {
    smWords = [...words];
  }
  
  // Belirtilen kelimeyi bul
  const wordIndex = smWords.findIndex(w => w.word.toLowerCase() === targetWord.toLowerCase());
  
  if (wordIndex !== -1) {
    smIdx = wordIndex;
  } else {
    // Kelime yoksa, allWords'den bul ve ekle
    const found = allWords.find(w => w.word.toLowerCase() === targetWord.toLowerCase());
    if (found) {
      smWords.push(found);
      smIdx = smWords.length - 1;
    }
  }
  
  // Cümle modunu aç
  showScreen('sc-sent');
  renderSentMode();
}

function startContextWithWord(targetWord) {
  // Bağlam Analizi ekranına git
  showScreen('sc-context');
  
  // Input'a kelimeyi yaz ve otomatik analiz başlat
  setTimeout(() => {
    const contextInput = document.getElementById("contextInput");
    if (contextInput) {
      contextInput.value = targetWord;
      // Enter event simüle et
      const event = new KeyboardEvent('keydown', { key: 'Enter', code: 'Enter', keyCode: 13 });
      contextInput.dispatchEvent(event);
    }
  }, 100);
}

// SM Pronunciation
let smRec=null,smIsListening=false;
function toggleSMSpeech(){if(smIsListening)stopSMSpeech();else startSMSpeech();}
function startSMSpeech(){
  try{ wmStopOpenMicStreams(); }catch(e){}

  const SR=window.SpeechRecognition||window.webkitSpeechRecognition;
  if(!SR){alert("Chrome gerekli.");return;}
  smRec=new SR();smRec.lang="en-US";smRec.continuous=false;smRec.interimResults=true;smRec.maxAlternatives=3;
  const lt=document.getElementById("smLiveTx");
  smRec.onstart=()=>{smIsListening=true;setMicState("rec","smMicBtn",null);lt.textContent="Dinleniyor…";};
  smRec.onresult=e=>{
    let interim="",final="";
    for(let i=e.resultIndex;i<e.results.length;i++){const t=e.results[i][0].transcript;if(e.results[i].isFinal)final+=t;else interim+=t;}
    lt.textContent=final||interim;
    if(final){
      smIsListening=false;setMicState("idle","smMicBtn",null);
      const alts=[];for(let i=0;i<e.results[e.results.length-1].length;i++) alts.push(e.results[e.results.length-1][i].transcript.trim().toLowerCase());
      scoreSMPronun(final.trim(),alts);
    }
  };
  smRec.onerror=()=>{smIsListening=false;setMicState("idle","smMicBtn",null);};
  smRec.onend=()=>{smIsListening=false;};
  smRec.start();
}
function stopSMSpeech(){if(smRec){try{smRec.stop();}catch(e){}}smIsListening=false;
  try{ wmStopOpenMicStreams(); wmResetMicButtons(); }catch(e){}
}

function scoreSMPronun(heard,alts){
  const item=smWords[smIdx];
  const target=item.sentence||item.word;
  const norm=s=>s.toLowerCase().replace(/[^a-z\s]/g,"").trim();
  const tNorm=norm(target);
  let bestScore=0,bestHeard=norm(heard);
  for(const alt of[norm(heard),...alts.map(norm)]){const s=calcPronScore(tNorm,alt);if(s>bestScore){bestScore=s;bestHeard=alt;}}
  const sc=Math.round(bestScore);
  const col=sc>=85?"#4ade80":sc>=70?"#60a5fa":sc>=50?"#fb923c":"#f87171";
  // Color sentence words based on pronunciation match
  const tWords=tNorm.split(/\s+/),hWords=bestHeard.split(/\s+/);
  document.getElementById("smAnswer").querySelectorAll(".sm-word").forEach(el=>{
    const w=el.textContent.trim().toLowerCase().replace(/[^a-z]/g,"");
    if(hWords.find(h=>h===w||levDist(h,w)<=1)) el.style.borderColor="#22c55e";
    else el.style.borderColor="#ef4444";
  });
  const res=document.getElementById("smPronunResult");
  res.style.display="block";
  res.innerHTML=`<div style="display:flex;align-items:center;gap:10px;padding:10px;background:var(--bg2);border-radius:10px">
    <div style="width:50px;height:50px;border-radius:50%;background:${col.replace("#","") >= "80" ? "#052e16":"#1c0a00"};
      display:flex;align-items:center;justify-content:center;font-size:18px;font-weight:900;color:${col}">${sc}</div>
    <div><div style="font-weight:800;color:${col}">${sc>=85?"Mükemmel 🌟":sc>=70?"İyi 👍":sc>=50?"Gelişiyor 💪":"Tekrar dene 🔄"}</div>
    <div style="font-size:12px;color:var(--muted)">Duyulan: "${bestHeard}"</div></div></div>`;
}

// ══════════════════════════════════════════════════════════
// LETTER MODE
// ══════════════════════════════════════════════════════════
function renderLetterMode(){
  if(!lmWords.length){document.querySelector("#sc-letter .card").innerHTML="<p style='color:var(--muted);text-align:center;padding:20px'>Kelime yükle ve Word Mode'dan başla.</p>";return;}
  if(lmIdx>=lmWords.length) lmIdx=0;
  const item=lmWords[lmIdx];
  document.getElementById("lmCounter").textContent=(lmIdx+1)+" / "+lmWords.length;
  // Cümleyi göster, kelimeyi boşlukla gizle
  const sent=item.sentence||"";
  const blank="_".repeat(item.word.length);
  let blanked=sent;
  if(sent){
    // Kelimeyi case-insensitive bul ve blank ile değiştir
    const idx2=sent.toLowerCase().indexOf(item.word.toLowerCase());
    if(idx2>=0) blanked=sent.slice(0,idx2)+blank+sent.slice(idx2+item.word.length);
  }
  const lmS=document.getElementById("lmSentence");
  const lmT=document.getElementById("lmTr");
  if(lmS) lmS.textContent=blanked||item.tr+" → ?";
  if(lmT) lmT.textContent=item.sentenceTr||item.tr;
  lmAnswer=[];lmSelectedIdxs=[];
  const letters=item.word.split("").sort(()=>Math.random()-.5);
  document.getElementById("lmLetters").innerHTML=letters.map((l,i)=>
    `<div class="lm-letter" id="ll${i}" data-letter="${l}" onclick="lmPickLetter(${i},'${l}')">${l}</div>`).join("");
  renderLMAnswer(item.word.length);
  document.getElementById("lmFeedback").style.display="none";
  document.getElementById("lmNext").style.display="none";
  const pb=document.getElementById("lmBtnPrev");
  const nb=document.getElementById("lmBtnNext");
  if(pb)pb.disabled=(lmIdx===0);
  if(nb)nb.disabled=(lmIdx>=lmWords.length-1);
}
function lmPrev(){if(lmIdx>0){lmIdx--;renderLetterMode();}}
function lmNavNext(){if(lmIdx<lmWords.length-1){lmIdx++;renderLetterMode();}}
function lmShowHint(){
  const item=lmWords[lmIdx];
  const nextPos=lmAnswer.length;
  if(nextPos>=item.word.length) return;
  const correctLetter=item.word[nextPos];
  const els=document.getElementById("lmLetters").querySelectorAll(".lm-letter");
  for(const el of els){
    if(!el.classList.contains("used")&&el.dataset.letter.toLowerCase()===correctLetter.toLowerCase()){
      lmPickLetter(parseInt(el.id.replace("ll","")),el.dataset.letter);
      break;
    }
  }
}
function renderLMAnswer(total){
  document.getElementById("lmAnswer").innerHTML=lmAnswer.map((l,i)=>
    `<div class="lm-slot" onclick="lmRemoveLetter(${i})">${l}</div>`).join("")+
    Array(total-lmAnswer.length).fill('<div class="lm-slot" style="opacity:.2">_</div>').join("");
  // update display
  document.getElementById("lmDisplay").innerHTML=lmAnswer.map(l=>`<span>${l}</span>`).join("")+
    Array(lmWords[lmIdx].word.length-lmAnswer.length).fill('<span style="opacity:.2">_</span>').join("");
}
function lmPickLetter(i,l){
  const el=document.getElementById("ll"+i);
  if(!el||el.classList.contains("used")) return;
  el.classList.add("used");lmSelectedIdxs.push(i);lmAnswer.push(l);
  renderLMAnswer(lmWords[lmIdx].word.length);
}
function lmRemoveLetter(pos){
  const srcIdx=lmSelectedIdxs[pos];
  document.getElementById("ll"+srcIdx)?.classList.remove("used");
  lmAnswer.splice(pos,1);lmSelectedIdxs.splice(pos,1);
  renderLMAnswer(lmWords[lmIdx].word.length);
}
function clearLMAnswer(){
  lmSelectedIdxs.forEach(i=>document.getElementById("ll"+i)?.classList.remove("used"));
  lmAnswer=[];lmSelectedIdxs=[];renderLMAnswer(lmWords[lmIdx].word.length);
}
function checkLetters(){
  const item=lmWords[lmIdx];
  const answer=lmAnswer.join("").toLowerCase();
  const correct=item.word.toLowerCase();
  const fb=document.getElementById("lmFeedback");
  fb.style.display="block";
  document.getElementById("lmAnswer").querySelectorAll(".lm-slot").forEach((el,i)=>{
    el.classList.remove("correct","wrong");
    if(i<lmAnswer.length) el.classList.add(lmAnswer[i].toLowerCase()===correct[i]?"correct":"wrong");
  });
  if(answer===correct){
    fb.style.background="#052e16";fb.style.color="#4ade80";fb.style.border="1.5px solid #166534";
    fb.textContent="✅ Doğru! "+item.word+" = "+item.tr;
    document.getElementById("lmNext").style.display="";
  }else{
    fb.style.background="#1c0a00";fb.style.color="#fb923c";fb.style.border="1.5px solid #7c2d12";
    fb.textContent="❌ Doğrusu: "+item.word;
    document.getElementById("lmNext").style.display="";
  }
}
function nextLetterMode(){lmIdx++;renderLetterMode();}

// ══════════════════════════════════════════════════════════
// STATS & DAILY TRACKING
// ══════════════════════════════════════════════════════════
function saveTimingData(){
  try{
    const today=new Date().toISOString().slice(0,10);
    const mins=Math.round((Date.now()-sessionStart)/60000);
    const key="wm_timing";
    const data=JSON.parse(localStorage.getItem(key)||"{}");
    data[today]=(data[today]||0)+mins;
    localStorage.setItem(key,JSON.stringify(data));
    // update streak
    const skey="wm_streak";
    const sdata=JSON.parse(localStorage.getItem(skey)||'{"streak":0,"lastDay":""}');
    const yesterday=new Date(Date.now()-86400000).toISOString().slice(0,10);
    if(sdata.lastDay===yesterday) sdata.streak++;
    else if(sdata.lastDay!==today) sdata.streak=1;
    sdata.lastDay=today;
    localStorage.setItem(skey,JSON.stringify(sdata));
  }catch(e){}
}
function renderStats(){
  // streak
  let dayStreak=0;
  try{const s=JSON.parse(localStorage.getItem("wm_streak")||'{"streak":0}');dayStreak=s.streak||0;}catch(e){}
  document.getElementById("statStreakNum").textContent=dayStreak;
  
  // 14. Kelime İstatistikleri
  const correctCount=learnedSet.size;
  const wrongCount=Object.values(wordStatus).filter(s=>s.attempts>0&&s.correct===0).length;
  const unseenCount=allWords.length-Object.keys(wordStatus).length;
  if(document.getElementById("correctWordsCount"))document.getElementById("correctWordsCount").textContent=correctCount;
  if(document.getElementById("wrongWordsCount"))document.getElementById("wrongWordsCount").textContent=wrongCount;
  if(document.getElementById("unseenWordsCount"))document.getElementById("unseenWordsCount").textContent=unseenCount;
  
  // week grid
  const days=["Paz","Pzt","Sal","Çar","Per","Cum","Cts"];
  const today=new Date();
  let weekHTML="";
  for(let i=6;i>=0;i--){
    const d=new Date(today);d.setDate(today.getDate()-i);
    const ds=d.toISOString().slice(0,10);
    let timingData={};try{timingData=JSON.parse(localStorage.getItem("wm_timing")||"{}");}catch(e){}
    const done=timingData[ds]>0;
    const isToday=i===0;
    weekHTML+=`<div class="week-day">
      <div class="day-circle${done?" done":""}${isToday?" today":""}">${done?"✓":d.getDate()}</div>
      <div class="day-name">${days[d.getDay()]}</div></div>`;
  }
  document.getElementById("weekGrid").innerHTML=weekHTML;
  // bar chart (last 7 days)
  let timingData={};try{timingData=JSON.parse(localStorage.getItem("wm_timing")||"{}");}catch(e){}
  const dayNames=["Paz","Pzt","Sal","Çar","Per","Cum","Cts"];
  let barHTML="",maxMins=0;
  const dayArr=[];
  for(let i=6;i>=0;i--){const d=new Date(today);d.setDate(today.getDate()-i);const ds=d.toISOString().slice(0,10);const m=timingData[ds]||0;dayArr.push({name:dayNames[d.getDay()],mins:m});maxMins=Math.max(maxMins,m);}
  dayArr.forEach(({name,mins})=>{
    const pct=maxMins>0?Math.round((mins/maxMins)*100):0;
    barHTML+=`<div class="bar-row">
      <div class="bar-day">${name}</div>
      <div class="bar-track"><div class="bar-fill" style="width:${pct}%">${mins>0?mins+"dk":""}</div></div>
    </div>`;
  });
  document.getElementById("barChart").innerHTML=barHTML;
  
  // Zayıf Noktalar Analizi
  renderWeakPoints();
  
  // Skor çubuğunu güncelle (aktif liste adı için)
  updateScoreBar();
  
  // stats cards
  const totalMins=Object.values(timingData).reduce((a,b)=>a+b,0);
  document.getElementById("statsCards").innerHTML=`
    <div class="stats-card"><div class="sc-val" style="color:var(--green)">${learnedSet.size}</div><div class="sc-key">✅ Öğrenilen Kelime</div></div>
    <div class="stats-card"><div class="sc-val" style="color:var(--blue)">${allWords.length}</div><div class="sc-key">📚 Toplam Kelime</div></div>
    <div class="stats-card"><div class="sc-val" style="color:var(--orange)">${totalMins}</div><div class="sc-key">⏱ Toplam Dakika</div></div>
    <div class="stats-card"><div class="sc-val" style="color:var(--purple)">${dayStreak}</div><div class="sc-key">🔥 Günlük Seri</div></div>`;
}

// ══════════════════════════════════════════════════════════
// AI CHAT LEVEL SETTER
// ══════════════════════════════════════════════════════════
function setUserLevel(level){
  aiUserLevel=level;
  if(level==="beginner") currentLevel=1;
  else if(level==="intermediate") currentLevel=2;
  else currentLevel=3;
  
  document.querySelectorAll(".level-chip").forEach(chip=>{
    chip.classList.remove("active");
    if(chip.dataset.level===level) chip.classList.add("active");
  });
}

