// DARK MODE
// ══════════════════════════════════════════════════════════

let isDarkMode = localStorage.getItem('darkMode') !== 'false'; // varsayılan dark

function toggleDarkMode() {
  isDarkMode = !isDarkMode;
  applyDarkMode();
  localStorage.setItem('darkMode', isDarkMode);
  
  // Toast
  showToast(isDarkMode ? '🌙 Dark Mode' : '☀️ Light Mode', 'Tema değiştirildi');
}

function applyDarkMode() {
  if (isDarkMode) {
    document.body.classList.remove('light-mode');
    document.getElementById('darkModeBtn').textContent = '🌙';
  } else {
    document.body.classList.add('light-mode');
    document.getElementById('darkModeBtn').textContent = '☀️';
  }
}

// Otomatik dark mode (saat bazlı) - isteğe bağlı
function autoDetectDarkMode() {
  const hour = new Date().getHours();
  const shouldBeDark = hour < 6 || hour >= 20; // 20:00-06:00 arası dark
  
  // Sadece kullanıcı hiç ayar yapmamışsa otomatik belirle
  if (localStorage.getItem('darkMode') === null) {
    isDarkMode = shouldBeDark;
    applyDarkMode();
  }
}

// ══════════════════════════════════════════════════════════
// CHALLENGE MODE
// ══════════════════════════════════════════════════════════

let challengeLevel = 'easy';
let challengeTimer = null;
let challengeTime = 60;
let challengeQuestions = [];
let challengeIdx = 0;
let challengeScore = 0;
let challengeCorrect = 0;

function setChallengeLevel(level) {
  challengeLevel = level;
  document.querySelectorAll('#challengeStart .level-chip').forEach(b => b.classList.remove('active'));
  document.getElementById('ch-' + level).classList.add('active');
}

function startChallenge() {
  document.getElementById('gamesMenu').style.display = 'none';
  document.getElementById('challengeMode').style.display = 'block';
  document.getElementById('challengeStart').style.display = 'block';
  document.getElementById('challengeGame').style.display = 'none';
  document.getElementById('challengeResult').style.display = 'none';
  
  // En iyi skoru göster
  const bestScore = localStorage.getItem('challengeBest_' + challengeLevel) || 0;
  document.getElementById('chBestScore').textContent = bestScore;
}

function startChallengeGame() {
  const learned = Array.from(learnedSet);
  if (learned.length < 10) {
    showToast('⚠️ Yetersiz Kelime', 'En az 10 kelime öğrenmelisin!');
    return;
  }
  
  // Zorluk seviyesine göre soru sayısı
  const questionCount = challengeLevel === 'easy' ? 10 : challengeLevel === 'medium' ? 15 : 20;
  
  // Rastgele kelimeler seç
  const shuffled = learned.sort(() => Math.random() - 0.5);
  challengeQuestions = shuffled.slice(0, questionCount).map(word => {
    const item = allWords.find(w => w.word === word);
    return item || { word, translation: '' };
  });
  
  challengeIdx = 0;
  challengeScore = 0;
  challengeCorrect = 0;
  challengeTime = 60;
  
  // Ekranları değiştir
  document.getElementById('challengeStart').style.display = 'none';
  document.getElementById('challengeGame').style.display = 'block';
  document.getElementById('chTotal').textContent = questionCount;
  
  // Timer başlat
  challengeTimer = setInterval(() => {
    challengeTime--;
    document.getElementById('chTimer').textContent = challengeTime;
    
    if (challengeTime <= 0) {
      endChallenge();
    }
  }, 1000);
  
  renderChallengeQuestion();
}

function renderChallengeQuestion() {
  if (challengeIdx >= challengeQuestions.length) {
    endChallenge();
    return;
  }
  
  const item = challengeQuestions[challengeIdx];
  document.getElementById('chQuestion').textContent = challengeIdx + 1;
  document.getElementById('chWord').textContent = item.word;
  
  // Progress bar
  const progress = ((challengeIdx + 1) / challengeQuestions.length) * 100;
  document.getElementById('chProgress').style.width = progress + '%';
  
  // 4 seçenek oluştur (1 doğru + 3 yanlış)
  const options = [item.translation];
  const allTranslations = allWords.map(w => w.translation).filter(t => t !== item.translation);
  
  while (options.length < 4 && allTranslations.length > 0) {
    const randomIdx = Math.floor(Math.random() * allTranslations.length);
    const randomTrans = allTranslations[randomIdx];
    if (!options.includes(randomTrans)) {
      options.push(randomTrans);
    }
    allTranslations.splice(randomIdx, 1);
  }
  
  // Karıştır
  options.sort(() => Math.random() - 0.5);
  
  // Seçenekleri render et
  const container = document.getElementById('chOptions');
  container.innerHTML = options.map((opt, idx) => `
    <button onclick="answerChallenge('${opt.replace(/'/g, "\\'")}', '${item.translation.replace(/'/g, "\\'")}')" 
      class="btn" 
      style="padding:16px;font-size:15px;font-weight:700;background:var(--bg2);color:var(--text);border:2px solid var(--border);text-align:left">
      ${String.fromCharCode(65 + idx)}. ${opt}
    </button>
  `).join('');
  
  document.getElementById('chFeedback').textContent = '';
}

function answerChallenge(selected, correct) {
  const isCorrect = selected === correct;
  
  if (isCorrect) {
    challengeScore += 10;
    challengeCorrect++;
    document.getElementById('chFeedback').innerHTML = '<span style="color:var(--green)">✅ Doğru! +10</span>';
  } else {
    document.getElementById('chFeedback').innerHTML = `<span style="color:var(--red)">❌ Yanlış! Doğrusu: ${correct}</span>`;
  }
  
  setTimeout(() => {
    challengeIdx++;
    renderChallengeQuestion();
  }, 1000);
}

function endChallenge() {
  if (challengeTimer) {
    clearInterval(challengeTimer);
    challengeTimer = null;
  }
  
  document.getElementById('challengeGame').style.display = 'none';
  document.getElementById('challengeResult').style.display = 'block';
  
  // Skor hesapla
  const timeBonus = challengeTime > 0 ? Math.floor(challengeTime / 2) : 0;
  const totalScore = challengeScore + timeBonus;
  const accuracy = Math.round((challengeCorrect / challengeQuestions.length) * 100);
  
  document.getElementById('chFinalScore').textContent = totalScore;
  document.getElementById('chAccuracy').textContent = accuracy + '%';
  
  // Emoji ve mesaj
  let emoji = '🎉';
  let title = 'Tebrikler!';
  let text = `${challengeCorrect}/${challengeQuestions.length} doğru cevap!`;
  
  if (accuracy >= 90) {
    emoji = '🏆';
    title = 'Mükemmel!';
    text = 'Harika bir performans!';
  } else if (accuracy >= 70) {
    emoji = '⭐';
    title = 'Çok İyi!';
    text = 'Başarılı bir sonuç!';
  } else if (accuracy >= 50) {
    emoji = '👍';
    title = 'İyi!';
    text = 'Pratikle daha da iyi olacaksın!';
  } else {
    emoji = '💪';
    title = 'Devam Et!';
    text = 'Her deneme seni ileriye taşıyor!';
  }
  
  document.getElementById('chResultEmoji').textContent = emoji;
  document.getElementById('chResultTitle').textContent = title;
  document.getElementById('chResultText').textContent = text;
  
  // En iyi skoru güncelle
  const bestKey = 'challengeBest_' + challengeLevel;
  const currentBest = parseInt(localStorage.getItem(bestKey) || '0');
  if (totalScore > currentBest) {
    localStorage.setItem(bestKey, totalScore);
    showToast('🏆 Yeni Rekor!', `${totalScore} puan`);
  }
  
  // XP ekle
  addXP(totalScore);
}

// ══════════════════════════════════════════════════════════
// MOTİVASYON SİSTEMİ
// ══════════════════════════════════════════════════════════

function checkDailyGoal() {
  const today = new Date().toDateString();
  const savedDate = localStorage.getItem('lastGoalCheck');
  
  // Yeni gün başladıysa sıfırla
  if (savedDate !== today) {
    todayLearned = 0;
    localStorage.setItem('lastGoalCheck', today);
  } else {
    todayLearned = parseInt(localStorage.getItem('todayLearned')) || 0;
  }
}

function incrementTodayLearned() {
  todayLearned++;
  localStorage.setItem('todayLearned', todayLearned);
  
  // Hedef kontrolü
  if (todayLearned === dailyGoal) {
    showToast('🎉 Tebrikler!', `Günlük hedefe ulaştın! ${dailyGoal} kelime`);
  }
  
  // Rozet kontrolü
  checkBadges();
  addXP(10); // Her kelime 10 XP
}

function updateStreak() {
  const today = new Date().toDateString();
  
  if (lastActiveDate !== today) {
    const yesterday = new Date(Date.now() - 86400000).toDateString();
    
    if (lastActiveDate === yesterday) {
      // Streak devam ediyor
      currentStreak++;
    } else {
      // Streak kırıldı
      currentStreak = 1;
    }
    
    lastActiveDate = today;
    localStorage.setItem('lastActiveDate', today);
    localStorage.setItem('currentStreak', currentStreak);
    
    // En uzun streak
    if (currentStreak > longestStreak) {
      longestStreak = currentStreak;
      localStorage.setItem('longestStreak', longestStreak);
    }
    
    // Streak rozetleri
    checkStreakBadges();
    checkSpecialBadges();
    recordStudyDay();
  }
}

function checkBadges() {
  const totalLearned = learnedSet.size;
  
  // Kelime rozetleri
  const wordBadges = ['first_word', 'ten_words', 'fifty_words', 'hundred_words'];
  wordBadges.forEach(badgeId => {
    const badge = BADGES[badgeId];
    if (totalLearned >= badge.requirement && !badges.includes(badgeId)) {
      unlockBadge(badgeId);
    }
  });
  
  // Mükemmel skor rozeti
  if (score === 100 && !badges.includes('perfect_score')) {
    unlockBadge('perfect_score');
  }
}

function checkStreakBadges() {
  const streakBadges = ['streak_3', 'streak_7', 'streak_30'];
  streakBadges.forEach(badgeId => {
    const badge = BADGES[badgeId];
    if (currentStreak >= badge.requirement && !badges.includes(badgeId)) {
      unlockBadge(badgeId);
    }
  });
}

function unlockBadge(badgeId) {
  if (!badges.includes(badgeId)) {
    badges.push(badgeId);
    localStorage.setItem('badges', JSON.stringify(badges));
    
    const badge = BADGES[badgeId];
    showToast(`${badge.icon} Rozet Kazanıldı!`, badge.name);
    addXP(50); // Rozet başına 50 XP
  }
}

function addXP(amount) {
  totalXP += amount;
  localStorage.setItem('totalXP', totalXP);
  
  // Seviye kontrolü (her 100 XP = 1 seviye)
  const newLevel = Math.floor(totalXP / 100) + 1;
  if (newLevel > userLevel) {
    userLevel = newLevel;
    localStorage.setItem('userLevel', userLevel);
    showToast('⬆️ Seviye Atladın!', `Seviye ${userLevel}`);
  }
}

function renderMotivationWidget() {
  const container = document.getElementById('motivationWidget');
  if (!container) return;
  
  checkDailyGoal();
  
  const goalProgress = Math.min(100, (todayLearned / dailyGoal) * 100);
  const nextLevel = userLevel + 1;
  const xpForNext = nextLevel * 100;
  const xpProgress = ((totalXP % 100) / 100) * 100;
  
  container.innerHTML = `
    <!-- Günlük Hedef -->
    <div class="card" style="background:linear-gradient(135deg,#667eea 0%,#764ba2 100%);color:white">
      <div style="font-size:14px;font-weight:800;margin-bottom:10px">🎯 Günlük Hedef</div>
      <div style="font-size:28px;font-weight:900;margin-bottom:8px">${todayLearned}/${dailyGoal}</div>
      <div style="height:8px;background:rgba(255,255,255,0.3);border-radius:4px;overflow:hidden">
        <div style="height:100%;background:white;width:${goalProgress}%;transition:width 0.5s"></div>
      </div>
      <div style="font-size:11px;opacity:0.9;margin-top:6px">
        ${dailyGoal - todayLearned > 0 ? `${dailyGoal - todayLearned} kelime kaldı` : 'Hedef tamamlandı! 🎉'}
      </div>
    </div>
    
    <!-- Streak -->
    <div class="card" style="background:linear-gradient(135deg,#f093fb 0%,#f5576c 100%);color:white">
      <div style="font-size:14px;font-weight:800;margin-bottom:10px">🔥 Streak</div>
      <div style="font-size:28px;font-weight:900;margin-bottom:4px">${currentStreak} Gün</div>
      <div style="font-size:11px;opacity:0.9">En uzun: ${longestStreak} gün</div>
    </div>
    
    <!-- Seviye -->
    <div class="card">
      <div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:8px">
        <div style="font-size:14px;font-weight:800;color:var(--text)">⚡ Seviye ${userLevel}</div>
        <div style="font-size:11px;color:var(--muted)">${totalXP} XP</div>
      </div>
      <div style="height:6px;background:var(--bg3);border-radius:3px;overflow:hidden">
        <div style="height:100%;background:var(--blue);width:${xpProgress}%;transition:width 0.3s"></div>
      </div>
      <div style="font-size:10px;color:var(--muted);margin-top:4px">
        Sonraki seviye: ${xpForNext} XP
      </div>
    </div>
    
    <!-- Rozetler -->
    <div class="card">
      <div style="font-size:14px;font-weight:800;color:var(--text);margin-bottom:10px">🏆 Rozetler (${badges.length}/${Object.keys(BADGES).length})</div>
      <div style="display:flex;flex-wrap:wrap;gap:8px">
        ${Object.values(BADGES).map(badge => {
          const unlocked = badges.includes(badge.id);
          return `
            <div style="
              width:60px;
              padding:8px;
              background:${unlocked ? 'var(--bg2)' : 'var(--bg3)'};
              border:2px solid ${unlocked ? 'var(--green)' : 'var(--border)'};
              border-radius:12px;
              text-align:center;
              opacity:${unlocked ? '1' : '0.4'}; ">
              <div style="font-size:24px;margin-bottom:4px">${badge.icon}</div>
              <div style="font-size:9px;color:var(--text);font-weight:700">${badge.name.split(' ')[0]}</div>
            </div>
          `;
        }).join('')}
      </div>
    </div>
  `;
}

// ══════════════════════════════════════════════════════════
// KÜTÜPHANE SİSTEMİ - GEÇİCİ OLARAK DEVRE DIŞI
// ══════════════════════════════════════════════════════════
/*
Kütüphane özelliği syntax sorunları nedeniyle geçici olarak devre dışı.
Gelecek sürümlerde eklenecek.
*/

window.addEventListener("DOMContentLoaded",()=>{
  // Otomatik yedekten geri yükleme (localStorage limiti için)
  autoRestoreFromFolder();
  
  // Dark mode başlat
  applyDarkMode();
  
  // URL'den kelime kontrolü (Bookmarklet için)
  const urlParams = new URLSearchParams(window.location.search);
  const wordFromURL = urlParams.get('word');
  if (wordFromURL && wordFromURL.length > 2) {
    console.log('📖 URL\'den kelime alındı:', wordFromURL);
    setTimeout(() => {
      _explainWordImpl(wordFromURL, 'chatMessages');
      showToast('📖 Web\'den Kelime', `"${wordFromURL}" açılıyor...`);
    }, 1000);
  }
  
  if(window.speechSynthesis){speechSynthesis.onvoiceschanged=()=>speechSynthesis.getVoices();speechSynthesis.getVoices();}
  
  // ══════════════════════════════════════════════════════════
  // SWIPE GESTURE (Parmakla kaydırma)
  // ══════════════════════════════════════════════════════════
  let touchStartX = 0;
  let touchEndX = 0;
  let touchStartY = 0;
  let touchEndY = 0;
  const SWIPE_THRESHOLD = 50; // Minimum kaydırma mesafesi (px)
  const VERTICAL_THRESHOLD = 30; // Dikey kaydırma toleransı
  
  const mainCard = document.getElementById("mainCard");
  if(mainCard){
    let isDragging = false;
    
    mainCard.addEventListener('touchstart', (e) => {
      touchStartX = e.changedTouches[0].screenX;
      touchStartY = e.changedTouches[0].screenY;
      isDragging = true;
      mainCard.style.transition = 'none';
    }, {passive: true});
    
    mainCard.addEventListener('touchmove', (e) => {
      if(!isDragging) return;
      const currentX = e.changedTouches[0].screenX;
      const currentY = e.changedTouches[0].screenY;
      const diffX = currentX - touchStartX;
      const diffY = Math.abs(currentY - touchStartY);
      
      // Yatay kaydırma, dikey değil
      if(diffY < VERTICAL_THRESHOLD && Math.abs(diffX) > 10){
        mainCard.style.transform = `translateX(${diffX * 0.3}px)`;
        mainCard.style.opacity = 1 - Math.abs(diffX) / 1000;
      }
    }, {passive: true});
    
    mainCard.addEventListener('touchend', (e) => {
      if(!isDragging) return;
      isDragging = false;
      
      touchEndX = e.changedTouches[0].screenX;
      touchEndY = e.changedTouches[0].screenY;
      
      const horizontalDiff = touchEndX - touchStartX;
      const verticalDiff = Math.abs(touchEndY - touchStartY);
      
      // Animasyon ile geri getir
      mainCard.style.transition = 'all 0.3s ease';
      mainCard.style.transform = 'translateX(0)';
      mainCard.style.opacity = '1';
      
      // Dikey kaydırma değilse (scroll değil)
      if(verticalDiff < VERTICAL_THRESHOLD){
        // Sağa kaydır → Önceki kelime
        if(horizontalDiff > SWIPE_THRESHOLD){
          setTimeout(() => prevWord(), 150);
        }
        // Sola kaydır → Sonraki kelime
        else if(horizontalDiff < -SWIPE_THRESHOLD){
          setTimeout(() => navNextWord(), 150);
        }
      }
    }, {passive: true});
  }
  
  // ══════════════════════════════════════════════════════════
  
  // Otomatik ses ayarını yükle
  const savedAudio=localStorage.getItem("autoPlayAudio");
  if(savedAudio!==null) autoPlayAudio=savedAudio==="1";
  if(document.getElementById("toggleAutoAudio")){
    document.getElementById("toggleAutoAudio").checked=autoPlayAudio;
    toggleAutoAudio();
  }
  
  // AI metin boyutunu yükle
  const savedSize=localStorage.getItem("aiTextSize");
  if(savedSize){
    aiTextSize=parseInt(savedSize);
    document.documentElement.style.setProperty('--ai-text-size',aiTextSize+'px');
    if(document.getElementById("aiTextSizeSlider")){
      document.getElementById("aiTextSizeSlider").value=aiTextSize;
      document.getElementById("aiSizeValue").textContent=aiTextSize+"px";
    }
  }
  
  // GROQ API Key'i input'a yükle
  if(document.getElementById("groqApiKeyInput")){
    const savedKey=localStorage.getItem("groq_api_key");
    if(savedKey){
      document.getElementById("groqApiKeyInput").value=savedKey;
    }
  }
  
  // Highlight ayarlarını yükle
  loadHighlightSettings();
  loadTTSRateSettings();
  
  // Kelime resimleri ayarını yükle
  loadWordImagesSetting();
  loadWordClickSetting();
  loadAutoReadSetting();
  
  // Mobil için kelime seçimi listener'ı ekle
  if (enableWordClick) {
    document.addEventListener('selectionchange', handleWordSelection);
  }
  
  // Çoklu liste sistemi: Aktif listeyi otomatik yükle
  const savedActiveListId = localStorage.getItem('activeListId');
  if (savedActiveListId && multiLists && multiLists.length > 0) {
    const activeList = multiLists.find(l => l.id === savedActiveListId);
    if (activeList) {
      console.log('🔄 Aktif liste otomatik yükleniyor:', activeList.name);
      switchToList(savedActiveListId);
      return; // tryAutoRestore'u atla
    }
  }
  
  tryAutoRestore();
  
  // Yeni özellikleri initialize et
  setTimeout(() => {
    if (document.getElementById("sc-grammar")) initGrammar();
    if (document.getElementById("sc-videos")) loadVideos("beginner");
  }, 500);
  // session timer — save every 60s
  setInterval(()=>{if(allWords.length>0) saveTimingData();},60000);
  // Hatırlatma sistemi başlat
  setTimeout(initReminder, 1000);
  // Model UI güncelle
  setTimeout(updateModelUI, 300);
  // PDF kitap listesini yükle
  setTimeout(renderPDFBookList, 500);
});


// ══════════════════════════════════════════════════════════
// 🏆 STREAK & ROZETLER
// ══════════════════════════════════════════════════════════
let badgeCatFilter = 'all';

const LEVEL_EMOJIS = ['🌱','📗','📘','⭐','🏅','🥇','💎','🦁','👑','🌟'];
const LEVEL_NAMES  = ['Başlangıç','Acemi','Öğrenci','Orta','İleri','Uzman','Usta','Efsane','Şampiyon','Efsanevi'];

function openStreakScreen(){
  showScreen('sc-streak');
  renderStreakScreen();
}

function renderStreakScreen(){
  // Streak
  document.getElementById('streakBigNum').textContent = currentStreak;
  document.getElementById('streakRecord').textContent = 'En uzun: ' + longestStreak + ' gün';
  document.getElementById('streakFireEmoji').textContent = currentStreak >= 30 ? '🦁' : currentStreak >= 14 ? '💎' : currentStreak >= 7 ? '⚡' : currentStreak >= 3 ? '🔥' : '💤';

  // Haftalık takvim
  renderWeekCalendar();

  // XP & Seviye
  const lvlIdx = Math.min(userLevel-1, LEVEL_EMOJIS.length-1);
  const xpForNext = userLevel * 100;
  const xpPct = Math.round((totalXP % 100));
  document.getElementById('levelDisplay').textContent = 'Seviye ' + userLevel + ' — ' + (LEVEL_NAMES[lvlIdx]||'Efsanevi');
  document.getElementById('levelEmoji').textContent = LEVEL_EMOJIS[lvlIdx]||'👑';
  document.getElementById('xpDisplay').textContent = totalXP + ' toplam XP';
  document.getElementById('xpBar').style.width = xpPct + '%';
  document.getElementById('xpCurrent').textContent = (totalXP % 100) + ' XP';
  document.getElementById('xpNext').textContent = (100 - (totalXP%100)) + " XP'e sonraki seviye";

  // Rozetler
  renderBadgesGrid();
}

function renderWeekCalendar(){
  const el = document.getElementById('weekCalendar');
  if(!el) return;
  const today = new Date();
  const days = ['Paz','Pzt','Sal','Çar','Per','Cum','Cmt'];
  const studyDays = JSON.parse(localStorage.getItem('studyDays')||'[]');
  el.innerHTML = Array.from({length:7}, (_,i)=>{
    const d = new Date(today);
    d.setDate(today.getDate() - (6-i));
    const dateStr = d.toDateString();
    const isToday = i === 6;
    const studied = studyDays.includes(dateStr);
    const dayName = days[d.getDay()];
    return '<div style="text-align:center">' +
      '<div style="font-size:9px;color:#fb923c;margin-bottom:4px">' + dayName + '</div>' +
      '<div style="width:32px;height:32px;border-radius:50%;display:flex;align-items:center;justify-content:center;font-size:16px;border:2px solid ' + (isToday?'#f97316':'transparent') + ';background:' + (studied?'#f97316':'rgba(255,255,255,0.1)') + '">' +
      (studied ? '🔥' : '○') +
      '</div></div>';
  }).join('');
}

function setBadgeCat(cat){
  badgeCatFilter = cat;
  document.querySelectorAll('[id^="bc-"]').forEach(b=>b.classList.remove('active'));
  document.getElementById('bc-'+cat)?.classList.add('active');
  renderBadgesGrid();
}

function renderBadgesGrid(){
  const el = document.getElementById('badgesGrid');
  if(!el) return;
  const allBadges = Object.values(BADGES);
  const filtered = badgeCatFilter === 'all' ? allBadges : allBadges.filter(b=>(b.cat||'ozel')===badgeCatFilter);
  const earned = badges.length;
  document.getElementById('badgeCountLabel').textContent = earned + '/' + allBadges.length;

  el.innerHTML = filtered.map(b=>{
    const has = badges.includes(b.id);
    return '<div style="text-align:center;padding:12px 6px;background:' + (has?'rgba(99,102,241,.15)':'var(--bg2)') + ';border-radius:14px;border:1.5px solid ' + (has?'var(--purple)':'var(--border)') + ';opacity:' + (has?'1':'0.45') + '">' +
      '<div style="font-size:28px;margin-bottom:6px">' + b.icon + '</div>' +
      '<div style="font-size:11px;font-weight:800;color:' + (has?'var(--text)':'var(--muted)') + ';line-height:1.3;margin-bottom:4px">' + b.name + '</div>' +
      '<div style="font-size:9px;color:var(--muted);line-height:1.3">' + b.desc + '</div>' +
      (has ? '<div style="font-size:9px;color:var(--purple);font-weight:700;margin-top:4px">✅ Kazanıldı</div>' : '') +
      '</div>';
  }).join('');
}

// Özel rozet kontrolleri
function checkSpecialBadges(){
  const h = new Date().getHours();
  if(h < 7) unlockBadge('early_bird');
  if(h >= 23) unlockBadge('night_owl');

  // Kitap kurdu
  const bookOpened = localStorage.getItem('bookOpenedCount');
  if(parseInt(bookOpened||0) >= 1) unlockBadge('first_book');

  // SRS ustası — 10 kelime uzman seviye
  const expertCount = allWords.filter(w=>{ const s=spacedRepetition[w.word]; return s&&s.level>=6; }).length;
  if(expertCount >= 10) unlockBadge('srs_master');

  // Kelime rozetleri
  const learnedCount = allWords.filter(w=>learnedSet.has(w.word)).length;
  if(learnedCount>=500) unlockBadge('five_hundred');
  if(learnedCount>=1000) unlockBadge('thousand');

  // Streak rozetleri
  if(currentStreak>=14) unlockBadge('streak_14');
  if(currentStreak>=100) unlockBadge('streak_100');
}

// Çalışma günü kaydet
function recordStudyDay(){
  const today = new Date().toDateString();
  const studyDays = JSON.parse(localStorage.getItem('studyDays')||'[]');
  if(!studyDays.includes(today)){
    studyDays.push(today);
    // Son 60 günü tut
    if(studyDays.length > 60) studyDays.shift();
    localStorage.setItem('studyDays', JSON.stringify(studyDays));
  }
}

// ══════════════════════════════════════════════════════════
// 🔊 DİNLEME TESTİ
// ══════════════════════════════════════════════════════════
let ltWords = [], ltIdx = 0, ltCorrect = 0, ltWrong = 0;
let ltCurrentWord = null, ltAutoPlay = null, ltAnswered = false;
const LT_TOTAL = 10;

function startListeningTest(){
  // Cümlesi olan kelimeleri filtrele
  const pool = allWords.filter(w => w.word && w.tr && w.sentence && w.sentence.trim().length > 5);
  if(pool.length < 4){ showToast('⚠️ Yetersiz kelime','En az 4 cümleli kelime gerekli'); return; }

  ltWords = [...pool].sort(()=>Math.random()-.5).slice(0, Math.min(LT_TOTAL, pool.length));
  ltIdx = 0; ltCorrect = 0; ltWrong = 0; ltAnswered = false;

  document.getElementById('gamesMenu').style.display = 'none';
  document.getElementById('listeningResult').style.display = 'none';
  document.getElementById('listeningTest').style.display = '';
  renderListeningQuestion();
}

function renderListeningQuestion(){
  if(ltIdx >= ltWords.length){ finishListeningTest(); return; }

  ltCurrentWord = ltWords[ltIdx];
  ltAnswered = false;

  // İlerleme
  const pct = Math.round(ltIdx / ltWords.length * 100);
  document.getElementById('ltBar').style.width = pct + '%';
  document.getElementById('ltScore').textContent = ltCorrect + '/' + ltWords.length;
  document.getElementById('ltQuestionNum').textContent = (ltIdx+1) + ' / ' + ltWords.length + ' soru';
  document.getElementById('ltFeedback').textContent = '';
  document.getElementById('ltPlayHint').textContent = 'Cümleyi dinle, hangi kelime?';

  // Cümledeki hedef kelimeyi gizle (*** ile)
  const hiddenSent = ltCurrentWord.sentence.replace(
    new RegExp('\\b' + ltCurrentWord.word + '\\b', 'gi'), '***'
  );
  document.getElementById('ltPlayHint').textContent = '"' + hiddenSent + '"';

  // 4 seçenek — İngilizce kelimeler
  const pool = allWords.filter(w => w.word && w.word !== ltCurrentWord.word);
  const wrong = [...pool].sort(()=>Math.random()-.5).slice(0,3);
  const options = [...wrong, ltCurrentWord].sort(()=>Math.random()-.5);

  document.getElementById('ltOptions').innerHTML = options.map(w => `
    <button onclick="checkListeningAnswer('${w.word.replace(/'/g,"\\'")}', this)"
      style="padding:14px 8px;background:var(--bg2);border:2px solid var(--border);border-radius:14px;font-size:13px;font-weight:700;cursor:pointer;color:var(--text);font-family:'Nunito',sans-serif;transition:all .2s;text-align:center;line-height:1.3">
      ${w.word}<br><span style="font-size:11px;color:var(--muted);font-weight:400">${w.tr}</span>
    </button>`).join('');

  // Otomatik seslendir
  clearTimeout(ltAutoPlay);
  ltAutoPlay = setTimeout(()=> playListeningWord(), 500);
}

function playListeningWord(){
  if(!ltCurrentWord || !ltCurrentWord.sentence) return;
  stopSpeech();
  setTimeout(()=> speak(ltCurrentWord.sentence, 'en-US'), 100);
}

function checkListeningAnswer(selectedWord, btn){
  if(ltAnswered) return;
  ltAnswered = true;

  const isCorrect = selectedWord === ltCurrentWord.word;
  const feedback = document.getElementById('ltFeedback');

  // Tüm butonları renklendir
  document.querySelectorAll('#ltOptions button').forEach(b => {
    const bWord = b.getAttribute('onclick').match(/'([^']+)'/)?.[1];
    if(bWord === ltCurrentWord.word){
      b.style.background = '#10b981';
      b.style.borderColor = '#10b981';
      b.style.color = '#fff';
    } else if(b === btn && !isCorrect){
      b.style.background = '#ef4444';
      b.style.borderColor = '#ef4444';
      b.style.color = '#fff';
    }
    b.disabled = true;
  });

  if(isCorrect){
    ltCorrect++;
    feedback.innerHTML = '<span style="color:var(--green)">✅ Doğru! — ' + ltCurrentWord.word + '</span>';
    // SRS güncelle
    updateSRS(ltCurrentWord.word, true);
  } else {
    ltWrong++;
    feedback.innerHTML = '<span style="color:var(--red)">❌ Yanlış! — ' + ltCurrentWord.word + ' → ' + ltCurrentWord.tr + '</span>';
    updateSRS(ltCurrentWord.word, false);
    // Cümleyi tekrar seslendir
    setTimeout(()=> speak(ltCurrentWord.sentence, 'en-US'), 600);
  }

  document.getElementById('ltScore').textContent = ltCorrect + '/' + ltWords.length;

  // Sonraki soruya geç
  ltIdx++;
  setTimeout(()=> renderListeningQuestion(), isCorrect ? 1200 : 2000);
}

function finishListeningTest(){
  clearTimeout(ltAutoPlay);
  stopSpeech();
  document.getElementById('listeningTest').style.display = 'none';
  document.getElementById('listeningResult').style.display = '';

  const total = ltCorrect + ltWrong;
  const pct = total > 0 ? Math.round(ltCorrect/total*100) : 0;
  const emoji = pct >= 80 ? '🏆' : pct >= 60 ? '🎯' : pct >= 40 ? '📚' : '💪';

  document.getElementById('ltFinalStats').innerHTML =
    emoji + ' Başarı: <b style="color:var(--purple);font-size:18px">' + pct + '%</b><br>' +
    '✅ Doğru: <b style="color:var(--green)">' + ltCorrect + '</b> &nbsp; ' +
    '❌ Yanlış: <b style="color:var(--red)">' + ltWrong + '</b><br>' +
    '🔊 Toplam: <b>' + total + '</b> soru';

  // Skoru kaydet
  if(!gameScores.listening || pct > gameScores.listening){
    gameScores.listening = pct;
    localStorage.setItem('gameScores', JSON.stringify(gameScores));
  }
  saveProgress();
}

// ══════════════════════════════════════════════════════════
// 🎯 ZAYIF NOKTA ANALİZİ
// ══════════════════════════════════════════════════════════
let weaknessFilter = 'all';

function openWeaknessScreen(){
  showScreen('sc-weakness');
  renderWeaknessScreen();
}

function setWeaknessFilter(f){
  weaknessFilter = f;
  document.querySelectorAll('[id^="wf-"]').forEach(b=>b.classList.remove('active'));
  document.getElementById('wf-'+f)?.classList.add('active');
  renderWeaknessScreen();
}

function getWeakWords(){
  return allWords.filter(w => {
    const st = wordStatus[w.word];
    if(!st || st.attempts === 0) return false;
    const pct = st.attempts > 0 ? (st.correct||0)/st.attempts : 0;
    switch(weaknessFilter){
      case 'never': return (st.correct||0) === 0;
      case 'low': return pct < 0.5 && st.attempts >= 2;
      case 'forgotten': {
        // Öğrenilmiş ama SRS'de düşük seviye
        const srs = spacedRepetition[w.word];
        return srs && srs.level > 0 && srs.level < 3 && (st.correct||0) > 0;
      }
      default: return pct < 0.6 && st.attempts >= 1;
    }
  }).sort((a,b)=>{
    const stA = wordStatus[a.word], stB = wordStatus[b.word];
    const pA = stA.attempts ? (stA.correct||0)/stA.attempts : 0;
    const pB = stB.attempts ? (stB.correct||0)/stB.attempts : 0;
    return pA - pB; // En kötü önce
  });
}

function renderWeaknessScreen(){
  const weak = getWeakWords();
  const all = allWords.filter(w=>{ const st=wordStatus[w.word]; return st&&st.attempts>0; });
  const improved = allWords.filter(w=>{ const srs=spacedRepetition[w.word]; return srs&&srs.level>=3; }).length;
  const avgAttempts = weak.length > 0 ? Math.round(weak.reduce((s,w)=>(s+(wordStatus[w.word]?.attempts||0)),0)/weak.length) : 0;

  // Özet
  document.getElementById('wk-total').textContent = weak.length;
  document.getElementById('wk-avg-attempts').textContent = avgAttempts;
  document.getElementById('wk-improved').textContent = improved;
  document.getElementById('wk-count-label').textContent = weak.length + ' kelime';

  // Liste
  const listEl = document.getElementById('weakWordsList');
  if(weak.length === 0){
    listEl.innerHTML = '<div style="text-align:center;padding:24px;color:var(--muted)"><div style="font-size:32px">🎉</div><div style="margin-top:8px">Zayıf noktanız yok!</div></div>';
    return;
  }

  listEl.innerHTML = weak.slice(0,20).map(w=>{
    const st = wordStatus[w.word];
    const pct = st.attempts > 0 ? Math.round((st.correct||0)/st.attempts*100) : 0;
    const srs = spacedRepetition[w.word];
    const srsLabels = ['🌱','📘','📗','📙','⭐','🌟','🏆'];
    const lvl = srs?.level||0;
    const barColor = pct < 30 ? 'var(--red)' : pct < 60 ? 'var(--orange)' : 'var(--green)';
    return `<div style="background:var(--bg2);border-radius:12px;padding:12px;border-left:3px solid ${barColor}">
      <div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:6px">
        <div>
          <span style="font-weight:800;font-size:15px;color:var(--text)">${w.word}</span>
          <span style="font-size:12px;color:var(--muted);margin-left:6px">${w.tr}</span>
        </div>
        <span style="font-size:18px">${srsLabels[lvl]||'🌱'}</span>
      </div>
      <div style="display:flex;align-items:center;gap:8px">
        <div style="flex:1;height:5px;background:var(--bg3);border-radius:3px">
          <div style="height:100%;width:${pct}%;background:${barColor};border-radius:3px"></div>
        </div>
        <span style="font-size:11px;font-weight:700;color:${barColor};min-width:32px">${pct}%</span>
        <span style="font-size:10px;color:var(--muted)">${st.attempts} deneme</span>
      </div>
      <div style="display:flex;gap:6px;margin-top:8px">
        <button onclick="_explainWordImpl('${w.word}','weaknessAIResult')" style="flex:1;padding:6px;background:var(--bg3);border:none;border-radius:8px;font-size:11px;font-weight:700;cursor:pointer;color:var(--text)">🤖 Açıkla</button>
        <button onclick="addToSRSQueue('${w.word}')" style="flex:1;padding:6px;background:var(--bg3);border:none;border-radius:8px;font-size:11px;font-weight:700;cursor:pointer;color:var(--text)">🔄 Tekrar</button>
      </div>
    </div>`;
  }).join('');
}

async function generateWeaknessAnalysis(){
  const weak = getWeakWords().slice(0,10);
  if(weak.length === 0){ showToast('🎉 Zayıf nokta yok!',''); return; }
  
  const resultEl = document.getElementById('weaknessAIResult');
  resultEl.innerHTML = '<div style="color:var(--muted)">🤖 Analiz yapılıyor...</div>';

  const wordList = weak.map(w=>{
    const st = wordStatus[w.word];
    const pct = st.attempts > 0 ? Math.round((st.correct||0)/st.attempts*100) : 0;
    return w.word + ' (' + pct + '% başarı, ' + st.attempts + ' deneme)';
  }).join(', ');

  const result = await callGroqAPI(
    'Sen bir İngilizce öğretmenisin. Türkçe yanıt ver.',
    'Öğrencinin zayıf olduğu kelimeler: ' + wordList + '\n\n' +
    'Bu kelimeleri analiz et ve şunları yap:\n' +
    '1. Bu kelimelerde ortak bir pattern var mı? (kelime türü, zorluk nedeni)\n' +
    '2. Her kelime için 1 cümlelik hafıza ipucu (mnemonic) öner\n' +
    '3. Bu kelimeleri öğrenmek için 3 pratik öneri\n' +
    'Kısa ve net tut, maksimum 200 kelime.'
  );

  if(result && result !== '__RATE_LIMIT__'){
    resultEl.innerHTML = result.replace(/\n/g,'<br>');
  } else {
    resultEl.innerHTML = '<div style="color:var(--muted)">Analiz alınamadı, tekrar dene.</div>';
  }
}

function addToSRSQueue(word){
  if(!spacedRepetition[word]){
    spacedRepetition[word] = { level:0, nextReview: Date.now(), correctStreak:0 };
  } else {
    spacedRepetition[word].nextReview = Date.now(); // Hemen tekrar
  }
  saveProgress();
  showToast('🔄 Tekrar listesine eklendi', word);
  updateReviewCount();
}

function practiceWeakWordsQuiz(){
  const weak = getWeakWords().slice(0,15);
  if(weak.length < 2){ showToast('⚠️ Yeterli zayıf kelime yok','En az 2 kelime gerekli'); return; }
  // Quiz ekranını bu kelimelerle başlat
  words = weak;
  idx = 0;
  showScreen('sc-quiz');
  showToast('🎯 Zayıf kelime quizi başladı!', weak.length + ' kelime');
}

function practiceWeakWordsFlip(){
  const weak = getWeakWords().slice(0,20);
  if(weak.length === 0){ showToast('🎉 Zayıf nokta yok!',''); return; }
  // SRS ekranını bu kelimelerle başlat
  srsQueue = [...weak].sort(()=>Math.random()-.5);
  srsQueueIdx = 0; srsCorrect = 0; srsWrong = 0;
  showScreen('sc-srs');
  document.getElementById('srsSummaryCard').style.display='none';
  document.getElementById('srsFinishCard').style.display='none';
  document.getElementById('srsSessionCard').style.display='';
  renderSRSCard();
  showToast('🔄 Zayıf kelime pratiği','');
}

// ══════════════════════════════════════════════════════════
// 📄 PDF / TXT YÜKLEME SİSTEMİ
// ══════════════════════════════════════════════════════════

function initPDFBooks(){
  renderPDFBookList().catch(console.error);
  // Drop zone stil
  const dz = document.getElementById('pdfDropZone');
  if(dz){
    dz.addEventListener('dragover', e=>{ e.preventDefault(); dz.style.borderColor='var(--blue)'; });
    dz.addEventListener('dragleave', ()=>{ dz.style.borderColor='var(--border)'; });
    dz.addEventListener('drop', e=>{
      e.preventDefault(); dz.style.borderColor='var(--border)';
      const file = e.dataTransfer?.files?.[0];
      if(file) processPDFFile(file);
    });
  }
}

async function handlePDFUpload(event){
  const file = event.target.files?.[0];
  if(!file) return;
  await processPDFFile(file);
  event.target.value = ''; // reset input
}

async function processPDFFile(file){
  const ext = file.name.split('.').pop().toLowerCase();
  const maxSize = 20 * 1024 * 1024; // 20MB
  if(file.size > maxSize){ showToast('❌ Dosya çok büyük', 'Maks 20MB'); return; }

  showPDFProgress(true, 'Dosya okunuyor...', 5);

  try {
    let text = '';
    if(ext === 'txt'){
      text = await readTxtFile(file);
      showPDFProgress(true, 'Metin işleniyor...', 80);
    } else if(ext === 'pdf'){
      text = await extractPDFText(file);
    } else {
      showToast('❌ Desteklenmiyor', 'PDF veya TXT yükleyin');
      showPDFProgress(false);
      return;
    }

    if(!text || text.trim().length < 100){
      showToast('❌ Metin çıkarılamadı', 'PDF taranmış görsel olabilir');
      showPDFProgress(false);
      return;
    }

    // Kaydet
    const bookId = 'pdf_' + Date.now();
    const meta = { title: file.name.replace(/\.(pdf|txt|epub)$/i,''), author: 'Yüklenen Dosya', level: 'intermediate', isPDF: true, size: text.length, date: Date.now() };

    // Meta: localStorage + WMStore'a kaydet
    const metaStr = JSON.stringify(meta);
    localStorage.setItem('book_meta_'+bookId, metaStr);
    WMStore.set('book_meta_'+bookId, metaStr).catch(()=>{});
    
    // Metin: WMStore'a kaydet (IDB + klasör)
    try{ await WMStore.setBook(bookId, meta.title, text); }catch(e){ console.warn('Kitap kayıt hatası:',e); }

    showPDFProgress(true, '✅ Hazır!', 100);
    setTimeout(()=>{ showPDFProgress(false); renderPDFBookList().catch(console.error); }, 800);
    showToast('✅ Kitap yüklendi!', meta.title);

  } catch(e){
    console.error('PDF error:', e);
    showToast('❌ Hata', 'Dosya işlenemedi: '+e.message);
    showPDFProgress(false);
  }
}

function readTxtFile(file){
  return new Promise((resolve, reject)=>{
    const reader = new FileReader();
    reader.onload = e => resolve(e.target.result);
    reader.onerror = reject;
    reader.readAsText(file, 'UTF-8');
  });
}

async function extractPDFText(file){
  if(typeof pdfjsLib === 'undefined'){
    throw new Error('PDF.js yüklenemedi');
  }
  const arrayBuffer = await file.arrayBuffer();
  showPDFProgress(true, 'PDF yükleniyor...', 20);

  const pdf = await pdfjsLib.getDocument({data: arrayBuffer}).promise;
  const totalPages = pdf.numPages;
  let fullText = '';

  for(let p=1; p<=Math.min(totalPages, 100); p++){
    showPDFProgress(true, `Sayfa ${p}/${Math.min(totalPages,100)} işleniyor...`, Math.round(20 + (p/Math.min(totalPages,100))*70));
    const page = await pdf.getPage(p);
    const content = await page.getTextContent();
    const pageText = content.items.map(item=>item.str).join(' ');
    fullText += pageText + '\n\n';
  }

  if(totalPages > 100) fullText += '\n\n[... Dosya çok büyük, ilk 100 sayfa gösteriliyor ...]';
  return fullText;
}

function showPDFProgress(show, status='', pct=0){
  const el = document.getElementById('pdfUploadProgress');
  if(!el) return;
  el.style.display = show ? '' : 'none';
  if(show){
    document.getElementById('pdfUploadStatus').textContent = status;
    document.getElementById('pdfUploadBar').style.width = pct+'%';
  }
}

async function renderPDFBookList(){
  const el = document.getElementById('pdfBookList');
  if(!el) return;
  const books = [];
  // IDB + localStorage'dan tüm book_meta_ anahtarlarını tara
  const _allMeta = {};
  for(let k in localStorage){ if(k.startsWith('book_meta_')) _allMeta[k] = localStorage.getItem(k); }
  try { const _idb = await WMStore.getByPrefix('book_meta_'); Object.assign(_allMeta, _idb); } catch(e) {}
  for(const k in _allMeta){
    if(k.startsWith('book_meta_pdf_') || k.startsWith('book_meta_')){
      try{
        const meta = JSON.parse(_allMeta[k]);
        if(meta && meta.isPDF) books.push({id: k.replace('book_meta_',''), ...meta});
      }catch(e){}
    }
  }
  books.sort((a,b)=>b.date-a.date);

  if(books.length===0){
    el.innerHTML = '<div style="font-size:12px;color:var(--muted);text-align:center;padding:8px">Henüz PDF yüklenmedi</div>';
    return;
  }

  el.innerHTML = books.map(b => {
    const kb = Math.round(b.size/1024);
    const date = new Date(b.date).toLocaleDateString('tr-TR');
    return `<div style="display:flex;align-items:center;gap:10px;padding:10px;background:var(--bg2);border-radius:12px;cursor:pointer" onclick="openPDFBook('${b.id}')">
      <div style="font-size:24px">📄</div>
      <div style="flex:1;min-width:0">
        <div style="font-size:13px;font-weight:700;color:var(--text);white-space:nowrap;overflow:hidden;text-overflow:ellipsis">${b.title}</div>
        <div style="font-size:11px;color:var(--muted)">${kb}KB · ${date}</div>
      </div>
      <button onclick="event.stopPropagation();deletePDFBook('${b.id}')" style="background:none;border:none;font-size:18px;cursor:pointer;color:var(--muted)">🗑️</button>
    </div>`;
  }).join('');
}

async function openPDFBook(bookId){
  // Meta: localStorage → WMStore sırasıyla dene
  const metaRaw = localStorage.getItem('book_meta_'+bookId)
    || await WMStore.get('book_meta_'+bookId).catch(()=>null);
  if(!metaRaw){ showToast('❌ Kitap bulunamadı',''); return; }
  const meta = JSON.parse(metaRaw);

  showToast('⏳ Açılıyor...', meta.title);

  // Metin: WMStore.getBook (IDB → klasör → localStorage sırasıyla)
  const text = await WMStore.getBook(bookId).catch(()=>null);

  if(!text || text.trim().length < 50){
    showToast('❌ Metin bulunamadı', 'Dosyayı tekrar yükleyin');
    return;
  }

  // currentBook set et ve reader'a aç
  currentBook = {id: bookId, title: meta.title, author: meta.author||'', level: meta.level||'intermediate', emoji:'📄'};
  showScreen('sc-reader');
  document.getElementById('readerTitle').textContent = '📄 ' + meta.title;
  document.getElementById('readerBookInfo').innerHTML = `<b style="color:var(--text)">${meta.title}</b>`;

  // Chunk'lara böl
  const paragraphs = text.split(/\n\s*\n/).filter(p=>p.trim().length>20);
  const CHUNK_SIZE = 15;
  readerChunks = [];
  for(let i=0; i<paragraphs.length; i+=CHUNK_SIZE){
    readerChunks.push(paragraphs.slice(i,i+CHUNK_SIZE).join('\n\n'));
  }
  if(readerChunks.length === 0) readerChunks = [text]; // Tek blok

  const saved = localStorage.getItem('reader_progress_'+bookId)
    || await WMStore.get('reader_progress_'+bookId).catch(()=>null);
  readerChunkIdx = saved ? (JSON.parse(saved).chunk||0) : 0;
  renderReaderChunk();
}

async function deletePDFBook(bookId){
  await WMStore.deleteBook(bookId);
  localStorage.removeItem('book_meta_'+bookId);
  await WMStore.remove('book_meta_'+bookId);
  localStorage.removeItem('reader_progress_'+bookId);
  await WMStore.remove('reader_progress_'+bookId);
  await renderPDFBookList();
  showToast('🗑️ Silindi','');
}

// ══════════════════════════════════════════════════════════
// 🔔 HATIRLATMA SİSTEMİ
// ══════════════════════════════════════════════════════════

function initReminder(){
  loadReminderSettings();
  updateNotifStatus();
  scheduleReminder();
  // SRS kontrolü her 5 dakikada bir
  setInterval(checkSRSReminder, 5 * 60 * 1000);
}

function updateNotifStatus(){
  const el = document.getElementById('notifStatus');
  const btn = document.getElementById('notifPermBtn');
  if(!el) return;
  if(!('Notification' in window)){
    el.innerHTML = '<span style="color:var(--red)">❌ Tarayıcınız bildirimleri desteklemiyor</span>';
    if(btn) btn.style.display = 'none';
    return;
  }
  // Her zaman güncel izin durumunu oku
  const perm = Notification.permission;
  if(perm === 'granted'){
    el.innerHTML = '<span style="color:var(--green)">✅ Bildirim izni verildi</span>';
    if(btn) btn.style.display = 'none';
  } else if(perm === 'denied'){
    el.innerHTML = '<span style="color:var(--red)">❌ İzin reddedildi — tarayıcı site ayarlarından açın</span>';
    if(btn) btn.style.display = 'none';
  } else {
    el.innerHTML = '<span style="color:var(--orange)">⏳ Bildirim izni verilmedi</span>';
    if(btn) btn.style.display = '';
  }
}

async function requestNotifPermission(){
  if(!('Notification' in window)){
    showToast('❌ Desteklenmiyor', 'Tarayıcınız bildirim desteklemiyor');
    return false;
  }
  if(Notification.permission === 'granted') return true;
  const permission = await Notification.requestPermission();
  updateNotifStatus();
  if(permission === 'granted'){
    showToast('✅ Bildirimler Aktif!', 'Artık hatırlatmalar alacaksınız');
    loadReminderSettings();
    updateToggleUI();
    scheduleReminder();
    const btn = document.getElementById('notifPermBtn');
    if(btn) btn.style.display = 'none';
    return true;
  } else {
    showToast('⚠️ Bildirim Engellendi', 'Ayarlardan izin verebilirsiniz');
    return false;
  }
}

function saveReminderSettings(){
  const settings = {
    dailyActive: document.getElementById('dailyReminderToggle')?.checked || false,
    time: document.getElementById('reminderTime')?.value || '09:00',
    msg: document.getElementById('reminderMsg')?.value || '📚 Bugün kelime çalışma zamanı!',
    srsActive: document.getElementById('srsReminderToggle')?.checked || false,
    savedAt: Date.now()
  };
  localStorage.setItem('reminderSettings', JSON.stringify(settings));
  updateToggleUI();
  scheduleReminder();

  // Toggle açıkken izin yoksa kullanıcıyı uyar
  const needsPermission = (settings.dailyActive || settings.srsActive) &&
                          ('Notification' in window) &&
                          Notification.permission !== 'granted';
  if (needsPermission) {
    showToast('⚠️ Bildirim izni yok', 'Ayar kaydedildi ama bildirim gelmez — yukarıdaki "Bildirim İznini Ver" butonuna basın');
  } else {
    showToast('💾 Kaydedildi', 'Hatırlatma ayarları güncellendi');
  }
}

function loadReminderSettings(){
  try {
    const raw = localStorage.getItem('reminderSettings');
    if(!raw) return;
    const s = JSON.parse(raw);
    const toggle = document.getElementById('dailyReminderToggle');
    const timeEl = document.getElementById('reminderTime');
    const msgEl = document.getElementById('reminderMsg');
    const srsToggle = document.getElementById('srsReminderToggle');
    if(toggle) toggle.checked = s.dailyActive || false;
    if(timeEl) timeEl.value = s.time || '09:00';
    if(msgEl) msgEl.value = s.msg || '📚 Bugün kelime çalışma zamanı!';
    if(srsToggle) srsToggle.checked = s.srsActive || false;
    updateToggleUI();
  } catch(e){}
}

function updateToggleUI(){
  // CSS :checked ile hallediyor — JS sadece checked state'i ayarlar
  const raw = localStorage.getItem('reminderSettings');
  if(!raw) return;
  const s = JSON.parse(raw);
  const toggle = document.getElementById('dailyReminderToggle');
  if(toggle) toggle.checked = !!s.dailyActive;
  const srsToggle = document.getElementById('srsReminderToggle');
  if(srsToggle) srsToggle.checked = !!s.srsActive;
}

// ====================== DÜZELTİLMİŞ GÜNLÜK BİLDİRİM ======================
let reminderTimer = null;

function scheduleReminder() {
  if (reminderTimer) {
    clearInterval(reminderTimer);
    reminderTimer = null;
  }

  const raw = localStorage.getItem('reminderSettings');
  if (!raw) return;
  
  const settings = JSON.parse(raw);
  if (!settings.dailyActive || Notification.permission !== 'granted') return;

  const [targetHour, targetMinute] = (settings.time || '09:00').split(':').map(Number);

  // Sonraki bildirim zamanını göster
  const target = new Date();
  target.setHours(targetHour, targetMinute, 0, 0);
  if(target <= new Date()) target.setDate(target.getDate() + 1);
  const nextInfo = document.getElementById('reminderNextInfo');
  if(nextInfo) nextInfo.textContent = '⏰ Sonraki: ' + target.toLocaleString('tr-TR');

  function checkAndSendReminder() {
    const now = new Date();
    const currentHour = now.getHours();
    const currentMinute = now.getMinutes();
    const todayKey = `reminder_sent_${now.getFullYear()}_${now.getMonth()+1}_${now.getDate()}`;

    if (localStorage.getItem(todayKey)) return;

    const isTargetTime = (currentHour === targetHour && currentMinute === targetMinute);
    const justMissed = (currentHour === targetHour && currentMinute > targetMinute && currentMinute <= targetMinute + 10);

    if (isTargetTime || justMissed) {
      localStorage.setItem(todayKey, 'true');

      const message = {
        type: 'SHOW_NOTIFICATION',
        title: '📚 Günlük Kelime Zamanı',
        body: settings.msg || 'Bugün kelime çalışma zamanı! 🌱',
        tag: 'daily-reminder'
      };

      if (false && navigator.serviceWorker && navigator.serviceWorker.controller) {
        navigator.serviceWorker.controller.postMessage(message);
      } else {
        new Notification(message.title, {
          body: message.body,
          icon: 'https://cdn-icons-png.flaticon.com/512/5968/5968890.png',
          tag: message.tag
        });
      }
      console.log('📢 Günlük bildirim gönderildi:', new Date().toLocaleTimeString());
    }
  }

  reminderTimer = setInterval(checkAndSendReminder, 30 * 1000);
  setTimeout(checkAndSendReminder, 1000);

  document.addEventListener('visibilitychange', ()=>{
    if(document.visibilityState === 'visible') checkAndSendReminder();
  });
}


function checkSRSReminder(){
  try {
    const raw = localStorage.getItem('reminderSettings');
    if(!raw) return;
    const s = JSON.parse(raw);
    if(!s.srsActive) return;
    if(Notification.permission !== 'granted') return;
    const due = getDueWords();
    if(due.length === 0) return;
    // Aynı gün tekrar bildirim gönderme
    const lastKey = 'srsNotifDate';
    const lastDate = localStorage.getItem(lastKey);
    const today = new Date().toDateString();
    if(lastDate === today) return;
    localStorage.setItem(lastKey, today);
    fireNotification(
      '🔄 Tekrar Zamanı!',
      `${due.length} kelime tekrar seni bekliyor`,
      '🧠'
    );
  } catch(e){}
}

async function fireNotification(title, body){
  if(Notification.permission !== 'granted') return;
  try {
    // Service Worker devre dışı, doğrudan Notification API kullan
    new Notification(title, {
      body: body || '',
      icon: 'https://cdn-icons-png.flaticon.com/512/5968/5968890.png',
      badge: 'https://cdn-icons-png.flaticon.com/512/5968/5968890.png',
      tag: 'word-mode',
      renotify: true
    });
  } catch(e){
    console.error('Notification error:', e);
  }
}

async function sendTestNotification(){
  if(Notification.permission !== 'granted'){
    await requestNotifPermission();
    return;
  }
  fireNotification('🧪 Test Bildirimi', 'PWA bildirim sistemi çalışıyor!');
  showToast('📨 Test gönderildi!', 'Bildirimi görüyor musun?');
}

// sc-reminder açılınca yükle
function openReminderScreen(){
  showScreen('sc-reminder');
  loadReminderSettings();
  updateNotifStatus();
  scheduleReminder();
}


// ══════════════════════════════════════════════════════════
// GLOBAL KELIME ALGILAMA FONKSİYONLARI
// ══════════════════════════════════════════════════════════

// sm-word zaten kendi sistemi var, onları atla
function isSmWord(el){
  return el && (el.classList.contains('sm-word') || el.closest('.sm-word'));
}

// Tıklanabilir metin mi?
function getWord(el){
  // clickable-word span
  if(el.classList&&el.classList.contains('clickable-word')) return el.textContent.trim();
  // modal-clickable-word (modal içindeki wrap'li kelimeler)
  if(el.classList&&el.classList.contains('modal-clickable-word')) return el.dataset.word||el.textContent.trim();
  // whl-word (podcast)
  if(el.classList&&el.classList.contains('whl-word')) return el.dataset.word||el.textContent.trim();
  // song-word
  if(el.classList&&el.classList.contains('song-word')) return el.textContent.trim();
  // wi-word, wc-word, wc-sent içindeki hl span
  if(el.classList&&(el.classList.contains('wc-word')||el.classList.contains('wi-word')||el.classList.contains('hl'))) return el.textContent.trim();
  // quiz seçenekleri
  if(el.classList&&el.classList.contains('quiz-option')) return el.textContent.trim();
  // en-word (yeşil vurgulu kelimeler)
  if(el.classList&&el.classList.contains('en-word')) return el.dataset.word||el.textContent.trim();
  
  // KISITLAMA KALDIRILDI: HER YERDE HER KELİME TIKLANABİLİR
  // Modal içi dahil tüm text node'ları
  const txt=(el.textContent||'').trim();
  // Sadece 2+ harf içeren kelimeler (noktalama/sayı temizlenecek)
  if(txt&&txt.length>=2) {
    // Kelimedeki harfleri al
    const cleaned = txt.replace(/[^a-zA-Z]/g,'');
    if(cleaned.length>=2) return cleaned;
  }
  return null;
}

// Mouse/Touch pozisyonundan kelimeyi bul (BUTONLAR DAHİL)
function getWordAtPosition(x, y) {
  // document.caretRangeFromPoint (Chrome/Safari)
  // document.caretPositionFromPoint (Firefox)
  let range = null;
  
  if (document.caretRangeFromPoint) {
    range = document.caretRangeFromPoint(x, y);
  } else if (document.caretPositionFromPoint) {
    const position = document.caretPositionFromPoint(x, y);
    if (position) {
      range = document.createRange();
      range.setStart(position.offsetNode, position.offset);
      range.setEnd(position.offsetNode, position.offset);
    }
  }
  
  if (!range || !range.startContainer) return null;
  
  const textNode = range.startContainer;
  if (textNode.nodeType !== Node.TEXT_NODE) return null;
  
  const text = textNode.textContent;
  const offset = range.startOffset;
  
  // Offset etrafındaki kelimeyi bul
  let start = offset;
  let end = offset;
  
  // Geriye git (kelime başlangıcı)
  while (start > 0 && /[a-zA-Z]/.test(text[start - 1])) {
    start--;
  }
  
  // İleriye git (kelime sonu)
  while (end < text.length && /[a-zA-Z]/.test(text[end])) {
    end++;
  }
  
  const word = text.substring(start, end).trim();
  
  // 2+ harf kontrolü
  if (word.length >= 2 && /[a-zA-Z]{2,}/.test(word)) {
    return word;
  }
  
  return null;
}

// ══════════════════════════════════════════════════════════
// GLOBAL LONG PRESS — Tüm ekranlarda kelimeye uzun bas → Groq
// ══════════════════════════════════════════════════════════
(function(){
  let _lpTimer=null;
  let _lpFired=false;
  const LONG_MS=600;

  // TOUCH EVENTS (Mobile)
  document.addEventListener('touchstart', function(e){
    if(_lpTimer) clearTimeout(_lpTimer);
    _lpFired=false;
    const target=e.target;
    
    // Modal içindeyse long press yapma (scroll etsin)
    if(target.closest('#wordExplanationModal')) return;
    
    if(isSmWord(target)) return; // sm-word kendi sistemi
    
    // Touch pozisyonuna göre kelimeyi al
    const touch = e.touches[0];
    const wordAtPos = getWordAtPosition(touch.clientX, touch.clientY);
    
    if(!wordAtPos) {
      // Pozisyondan bulamazsa, eski yöntemi dene
      const word=getWord(target);
      if(!word) return;
      const clean=word.replace(/[^a-zA-Z]/g,'').toLowerCase();
      if(!clean||clean.length<2) return;
      _lpTimer=setTimeout(()=>{
        _lpFired=true;
        navigator.vibrate&&navigator.vibrate(50);
        _explainWordImpl(clean,'chatMessages');
      },LONG_MS);
      return;
    }
    
    const clean=wordAtPos.replace(/[^a-zA-Z]/g,'').toLowerCase();
    if(!clean||clean.length<2) return;
    _lpTimer=setTimeout(()=>{
      _lpFired=true;
      navigator.vibrate&&navigator.vibrate(50);
      _explainWordImpl(clean,'chatMessages');
    },LONG_MS);
  },{passive:true});

  document.addEventListener('touchend', function(){
    clearTimeout(_lpTimer);
  },{passive:true});

  document.addEventListener('touchmove', function(){
    clearTimeout(_lpTimer);
  },{passive:true});
  
  // MOUSE EVENTS (Desktop)
  document.addEventListener('mousedown', function(e){
    if(_lpTimer) clearTimeout(_lpTimer);
    _lpFired=false;
    const target=e.target;
    
    // Modal içindeyse long press yapma (scroll etsin)
    if(target.closest('#wordExplanationModal')) return;
    
    if(isSmWord(target)) return;
    
    // Mouse pozisyonuna göre kelimeyi al
    const wordAtPos = getWordAtPosition(e.clientX, e.clientY);
    
    if(!wordAtPos) {
      // Pozisyondan bulamazsa, eski yöntemi dene
      const word=getWord(target);
      if(!word) return;
      const clean=word.replace(/[^a-zA-Z]/g,'').toLowerCase();
      if(!clean||clean.length<2) return;
      _lpTimer=setTimeout(()=>{
        _lpFired=true;
        _explainWordImpl(clean,'chatMessages');
      },LONG_MS);
      return;
    }
    
    const clean=wordAtPos.replace(/[^a-zA-Z]/g,'').toLowerCase();
    if(!clean||clean.length<2) return;
    _lpTimer=setTimeout(()=>{
      _lpFired=true;
      _explainWordImpl(clean,'chatMessages');
    },LONG_MS);
  },{passive:true});

  document.addEventListener('mouseup', function(){
    clearTimeout(_lpTimer);
  },{passive:true});

  document.addEventListener('mousemove', function(){
    clearTimeout(_lpTimer);
  },{passive:true});
})();

// ══════════════════════════════════════════════════════════
// ÖĞRENİLEN KELİMELER SİSTEMİ
// ══════════════════════════════════════════════════════════

function loadLearnedWords(){
  try {
    console.log('📂 KELİMELER YÜKLENİYOR...');
    
    const stored = localStorage.getItem('learnedWords');
    console.log('📂 localStorage\'dan okunan:', stored ? (stored.length + ' karakter') : 'BOŞ');
    
    if(stored){
      try {
        learnedWords = JSON.parse(stored);
        console.log('✅ YÜKLEME BAŞARILI:', learnedWords.length, 'kelime yüklendi');
        console.log('📚 Yüklenen kelimeler:', learnedWords.map(w => w.word).slice(0, 10).join(', '), '...');
        
        // 🔄 SYNC: learnedWords'teki kelimeleri words array'inde learned=true yap
        syncLearnedWordsWithMainArray();
        
      } catch(parseError){
        console.error('❌ JSON PARSE HATASI:', parseError);
        console.error('Bozuk veri:', stored.substring(0, 100));
        learnedWords = [];
      }
    } else {
      console.log('ℹ️ localStorage\'da learnedWords bulunamadı - YENİ BAŞLANGIÇ');
      learnedWords = [];
    }
    
    // localStorage'daki tüm anahtarları göster
    console.log('🗂️ localStorage anahtarları:', Object.keys(localStorage));
    
  } catch(e) {
    console.error('❌ GENEL YÜKLEME HATASI:', e);
    learnedWords = [];
  }
}

// 🔄 learnedWords ile words array'ini senkronize et
function syncLearnedWordsWithMainArray() {
  if (!Array.isArray(words) || !words.length) {
    return;
  }
  if(typeof words === 'undefined' || !Array.isArray(words)) {
    console.log('ℹ️ words array henüz yüklenmemiş, sync atlanıyor');
    return;
  }
  
  if(!learnedWords || learnedWords.length === 0) {
    console.log('ℹ️ learnedWords boş, sync gerekmiyor');
    return;
  }
  
  console.log('🔄 SYNC BAŞLATILIYOR - learnedWords:', learnedWords.length, 'words:', words.length);
  
  let syncCount = 0;
  
  // learnedSet'i temizle ve yeniden oluştur
  if(typeof learnedSet !== 'undefined') {
    learnedSet.clear();
  }
  
  learnedWords.forEach(learned => {
    // learnedSet'e ekle
    if(typeof learnedSet !== 'undefined') {
      learnedSet.add(learned.word);
    }
    
    // words array'inde bul ve learned=true yap
    const wordIndex = words.findIndex(w => w.word && learned.word && w.word.toLowerCase() === learned.word.toLowerCase());
    if(wordIndex !== -1) {
      if(!words[wordIndex].learned) {
        words[wordIndex].learned = true;
        syncCount++;
      }
    }
  });
  
  if(syncCount > 0) {
    console.log('✅ SYNC TAMAMLANDI:', syncCount, 'kelime güncellendi');
    console.log('✅ learnedSet size:', typeof learnedSet !== 'undefined' ? learnedSet.size : 'tanımsız');
    
    // words array'ini kaydet
    try {
      localStorage.setItem('words', JSON.stringify(words));
      console.log('💾 words array kaydedildi');
    } catch(e) {
      console.warn('⚠️ words array kaydedilemedi:', e.message);
    }
  } else {
    console.log('✅ SYNC: Tüm kelimeler zaten senkron');
    console.log('✅ learnedSet size:', typeof learnedSet !== 'undefined' ? learnedSet.size : 'tanımsız');
  }
}

function saveLearnedWords(){
  try {
    const data = JSON.stringify(learnedWords);
    localStorage.setItem('learnedWords', data);
    console.log('💾 KAYIT YAPILDI - learnedWords:', learnedWords.length, 'kelime');
    console.log('💾 localStorage.learnedWords boyut:', (data.length / 1024).toFixed(2), 'KB');
    
    // Doğrulama - kaydedilen veri gerçekten orada mı?
    const verification = localStorage.getItem('learnedWords');
    if(verification) {
      const parsed = JSON.parse(verification);
      console.log('✅ DOĞRULAMA BAŞARILI:', parsed.length, 'kelime localStorage\'da');
    } else {
      console.error('❌ DOĞRULAMA HATASI: Veri kaydedildi ama okunamadı!');
    }
    
  } catch(e) {
    console.error('❌ KAYIT HATASI:', e);
    console.error('Hata detayı:', e.message);
    
    // Quota hatası kontrolü
    if (e.name === 'QuotaExceededError') {
      alert('⚠️ Depolama alanı doldu! Lütfen eski verileri temizleyin.');
    }
  }
}

function addLearnedWord(word, translation, level = 'learning'){
  console.log('➕ KELİME EKLENİYOR:', word, '(', translation, ') - Seviye:', level);
  
  const existing = learnedWords.find(w => w.word.toLowerCase() === word.toLowerCase());
  if(existing){
    console.log('🔄 KELİME ZATEN VAR - GÜNCELLENİYOR:', word);
    existing.lastReviewed = new Date().toISOString();
    existing.reviewCount = (existing.reviewCount || 0) + 1;
    existing.level = level;
  } else {
    console.log('✨ YENİ KELİME EKLENİYOR:', word);
    learnedWords.push({
      word: word,
      translation: translation,
      level: level,
      addedDate: new Date().toISOString(),
      lastReviewed: new Date().toISOString(),
      reviewCount: 1
    });
  }
  
  // 🔄 SYNC 1: learnedSet'e ekle (liste istatistikleri için)
  if(typeof learnedSet !== 'undefined') {
    learnedSet.add(word);
    console.log('✅ learnedSet güncellendi, size:', learnedSet.size);
  }
  
  // 🔄 SYNC 2: Ana words array'inde de learned=true yap
  if(typeof words !== 'undefined' && Array.isArray(words)) {
    const wordIndex = words.findIndex(w => w.word && w.word.toLowerCase() === word.toLowerCase());
    if(wordIndex !== -1) {
      words[wordIndex].learned = true;
      console.log('✅ SYNC: words[' + wordIndex + '].learned = true');
      
      // words array'ini localStorage'a kaydet
      try {
        localStorage.setItem('words', JSON.stringify(words));
        console.log('💾 words array güncellendi');
      } catch(e) {
        console.warn('⚠️ words array kaydedilemedi:', e.message);
      }
    } else {
      console.log('ℹ️ Kelime words array\'inde bulunamadı:', word);
    }
  }
  
  console.log('📊 Toplam kelime sayısı:', learnedWords.length);
  saveLearnedWords();
  
  // 🔄 SYNC 3: Eğer liste açıksa hemen güncelle
  if(document.getElementById('sc-list') && document.getElementById('sc-list').style.display !== 'none') {
    showList(); // İstatistikleri güncelle
    renderWordList(); // Kelime kartlarını yeniden render et
    console.log('✅ Liste görünümü güncellendi');
  }
  
  console.log('✅ KELİME EKLEME TAMAMLANDI:', word);
}

function removeLearnedWord(word){
  learnedWords = learnedWords.filter(w => w.word.toLowerCase() !== word.toLowerCase());
  
  // 🔄 SYNC 1: learnedSet'ten çıkar
  if(typeof learnedSet !== 'undefined') {
    learnedSet.delete(word);
    console.log('✅ learnedSet güncellendi, size:', learnedSet.size);
  }
  
  // 🔄 SYNC 2: Ana words array'inde learned=false yap
  if(typeof words !== 'undefined' && Array.isArray(words)) {
    const wordIndex = words.findIndex(w => w.word && w.word.toLowerCase() === word.toLowerCase());
    if(wordIndex !== -1) {
      words[wordIndex].learned = false;
      console.log('✅ SYNC: words[' + wordIndex + '].learned = false');
      
      // words array'ini localStorage'a kaydet
      try {
        localStorage.setItem('words', JSON.stringify(words));
        console.log('💾 words array güncellendi');
      } catch(e) {
        console.warn('⚠️ words array kaydedilemedi:', e.message);
      }
    }
  }
  
  saveLearnedWords();
  renderLearnedWordsScreen();
  
  // 🔄 SYNC 3: Eğer liste açıksa hemen güncelle
  if(document.getElementById('sc-list') && document.getElementById('sc-list').style.display !== 'none') {
    showList(); // İstatistikleri güncelle
    renderWordList(); // Kelime kartlarını yeniden render et
  }
  
  showToast('🗑️ Kelime silindi');
}

function updateWordLevel(word, newLevel){
  const found = learnedWords.find(w => w.word.toLowerCase() === word.toLowerCase());
  if(found){
    found.level = newLevel;
    found.lastReviewed = new Date().toISOString();
    saveLearnedWords();
    renderLearnedWordsScreen();
    showToast('✅ Seviye güncellendi');
  }
}

function filterLearnedWords(type, event){
  currentLearnedFilter = type;
  document.querySelectorAll('.filter-btn').forEach(btn => btn.classList.remove('active'));
  if(event) event.target.classList.add('active');
  renderLearnedWordsScreen();
}

function renderLearnedWordsScreen(){
  const container = document.getElementById('learnedWordsList');
  const countEl = document.getElementById('learnedTotalCount');
  
  let filtered = learnedWords;
  if(currentLearnedFilter === 'mastered'){
    filtered = learnedWords.filter(w => w.level === 'mastered');
  } else if(currentLearnedFilter === 'learning'){
    filtered = learnedWords.filter(w => w.level === 'learning');
  }
  
  countEl.textContent = learnedWords.length;
  
  if(filtered.length === 0){
    container.innerHTML = '<div class="card"><p style="text-align:center;padding:40px;color:var(--muted)">Henüz kelime eklenmemiş</p></div>';
    return;
  }
  
  filtered.sort((a, b) => new Date(b.lastReviewed) - new Date(a.lastReviewed));
  
  container.innerHTML = filtered.map(w => `
    <div class="card" style="margin-bottom:10px;cursor:pointer" onclick="explainWord('${w.word.replace(/'/g, "\\'")}', 'chatMessages')">
      <div style="display:flex;justify-content:space-between;align-items:start;margin-bottom:10px">
        <div style="flex:1">
          <div style="font-size:22px;font-weight:900;color:var(--green);margin-bottom:4px">${w.word}</div>
          <div style="font-size:14px;color:var(--sub);font-style:italic">${w.translation || ''}</div>
        </div>
        <div style="display:flex;gap:6px;flex-shrink:0" onclick="event.stopPropagation()">
          ${w.level === 'learning' ? 
            `<button onclick="updateWordLevel('${w.word}', 'mastered')" style="padding:6px 12px;background:#166534;color:#4ade80;border:none;border-radius:8px;font-size:11px;font-weight:800;cursor:pointer;font-family:'Nunito',sans-serif">✓ Ustalaştım</button>` :
            `<button onclick="updateWordLevel('${w.word}', 'learning')" style="padding:6px 12px;background:#1e3a5f;color:#93c5fd;border:none;border-radius:8px;font-size:11px;font-weight:800;cursor:pointer;font-family:'Nunito',sans-serif">↩ Tekrar</button>`
          }
          <button onclick="removeLearnedWord('${w.word}')" style="padding:6px 12px;background:#7f1d1d;color:#fca5a5;border:none;border-radius:8px;font-size:11px;font-weight:800;cursor:pointer;font-family:'Nunito',sans-serif">🗑️</button>
        </div>
      </div>
      <div style="display:flex;gap:16px;font-size:11px;color:var(--muted)">
        <span>📅 ${new Date(w.addedDate).toLocaleDateString('tr-TR')}</span>
        <span>🔄 ${w.reviewCount || 1}× tekrar</span>
        <span>${w.level === 'mastered' ? '⭐ Ustalaşıldı' : '📖 Öğreniliyor'}</span>
      </div>
    </div>
  `).join('');
}

function showAllLearnedWordsModal(){
  const allWords = [...learnedWords].sort((a, b) => a.word.localeCompare(b.word));
  
  const modal = document.createElement('div');
  modal.className = 'modal-overlay';
  modal.style.cssText = 'position:fixed;inset:0;background:rgba(0,0,0,.85);z-index:10000;display:flex;align-items:center;justify-content:center;backdrop-filter:blur(4px)';
  
  modal.innerHTML = `
    <div style="background:var(--card);border-radius:20px;width:90%;max-width:450px;max-height:80vh;overflow:hidden;border:1px solid var(--border);box-shadow:0 20px 60px rgba(0,0,0,.6)">
      <div style="padding:20px;border-bottom:1px solid var(--border);display:flex;justify-content:space-between;align-items:center">
        <h3 style="font-size:20px;color:var(--purple);margin:0">📋 Tüm Kelimeler (${allWords.length})</h3>
        <button onclick="this.closest('.modal-overlay').remove()" 
          style="background:none;border:none;font-size:28px;color:var(--muted);cursor:pointer;padding:0;line-height:1">×</button>
      </div>
      <div style="max-height:60vh;overflow-y:auto;padding:16px">
        ${allWords.length === 0 ? 
          '<div style="text-align:center;padding:40px;color:var(--muted)">Henüz kelime eklenmemiş</div>' :
          allWords.map(w => `
            <div style="display:flex;justify-content:space-between;padding:12px;background:var(--bg2); border-radius:10px;margin-bottom:8px;border:1px solid var(--border);cursor:pointer"
              onclick="modal.remove();explainWord('${w.word.replace(/'/g, "\\'")}', 'chatMessages')">
              <div style="flex:1">
                <div style="font-size:16px;font-weight:800;color:var(--text)">${w.word}</div>
                <div style="font-size:13px;color:var(--muted);margin-top:2px">${w.translation || ''}</div>
              </div>
              <div style="display:flex;align-items:center">
                <span style="font-size:11px;padding:4px 10px;background:${w.level === 'mastered' ? '#166534' : '#1e3a5f'}; color:${w.level === 'mastered' ? '#4ade80' : '#93c5fd'};border-radius:6px;font-weight:700">
                  ${w.level === 'mastered' ? '⭐' : '📖'}
                </span>
              </div>
            </div>
          `).join('')
        }
      </div>
      <div style="padding:16px;border-top:1px solid var(--border)">
        <button class="btn btn-blue" onclick="exportLearnedWordsToExcel()" style="width:100%">
          📥 Excel Olarak İndir
        </button>
      </div>
    </div>
  `;
  
  document.body.appendChild(modal);
  modal.addEventListener('click', (e)=>{
    if(e.target === modal) modal.remove();
  });
}

function exportLearnedWordsToExcel(){
  if(learnedWords.length === 0){
    showToast('⚠️ Henüz kelime yok');
    return;
  }
  
  const data = learnedWords.map(w => ({
    'Kelime': w.word,
    'Çeviri': w.translation || '',
    'Seviye': w.level === 'mastered' ? 'Ustalaşıldı' : 'Öğreniliyor',
    'Eklenme Tarihi': new Date(w.addedDate).toLocaleDateString('tr-TR'),
    'Tekrar Sayısı': w.reviewCount || 1
  }));
  
  if(typeof XLSX !== 'undefined'){
    const ws = XLSX.utils.json_to_sheet(data);
    const wb = XLSX.utils.book_new();
    XLSX.utils.book_append_sheet(wb, ws, "Kelimeler");
    XLSX.writeFile(wb, `kelimelerim_${new Date().toLocaleDateString('tr-TR').replace(/\./g, '_')}.xlsx`);
    showToast('✅ İndirildi!', 'Excel dosyası hazırlandı');
  } else {
    showToast('⚠️ Excel kütüphanesi yüklenemedi');
  }
}

