/* SENTENCE MINING v1 */
(function(){
  'use strict';

  const STOP = new Set(("a an the and or but if then because as at by for from in into on onto of off over under with without to too very is are was were be been being am do does did done have has had having i you he she it we they me him her us them my your his its our their this that these those there here not no yes can could should would will shall may might must just so than also more most some any each every all both either neither about after before between during through across again against ago up down out now new old get got make made go went gone come came see saw seen know knew known think thought say said tell told take took taken").split(/\s+/));

  function esc(s){
    return String(s ?? '').replace(/[&<>'"]/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[c]));
  }

  function norm(w){
    return String(w || '').toLowerCase().replace(/^[^a-z]+|[^a-z]+$/g,'').replace(/[’']/g,'');
  }

  function lemmatize(w){
    w = norm(w);
    const candidates = [w];
    if(w.endsWith("ies") && w.length>4) candidates.push(w.slice(0,-3)+"y");
    if(w.endsWith("ing") && w.length>5) {
      candidates.push(w.slice(0,-3));
      candidates.push(w.slice(0,-3)+"e");
    }
    if(w.endsWith("ed") && w.length>4) {
      candidates.push(w.slice(0,-2));
      candidates.push(w.slice(0,-1));
    }
    if(w.endsWith("s") && w.length>3) candidates.push(w.slice(0,-1));
    return [...new Set(candidates)];
  }

  function getMap(){
    return window.WM_SOZLUK_MEANING_MAP || window.sozlukMeaningMap || {};
  }

  function findEntry(word){
    const map = getMap();
    for(const c of lemmatize(word)){
      if(map[c]) return {key:c, entry:map[c]};
    }

    const pools = [
      window.broadDictionaryRows,
      window.myDictionaryRows,
      (typeof broadDictionaryRows !== 'undefined' ? broadDictionaryRows : null),
      (typeof myDictionaryRows !== 'undefined' ? myDictionaryRows : null)
    ];
    for(const arr of pools){
      if(Array.isArray(arr)){
        for(const c of lemmatize(word)){
          const r = arr.find(x => String(x.word || x.Kelime || '').toLowerCase() === c);
          if(r) return {
            key:c,
            entry:{
              word:r.word || r.Kelime || c,
              pron:r.türkçe_okunuş || r.turkce_okunus || '',
              meanings:[r.anlam1,r.anlam2,r.anlam3,r.meaning,r.tr].filter(Boolean),
              level:r.seviye || r.level || '',
              zipf:r.zipf || ''
            }
          };
        }
      }
    }
    return null;
  }

  function getKnownSet(){
    const keys = ['learnedWords','knownWords','wm_learned_words'];
    const set = new Set();
    keys.forEach(k=>{
      try{
        const v = JSON.parse(localStorage.getItem(k) || '[]');
        if(Array.isArray(v)) v.forEach(x => set.add(String(x.word || x.Kelime || x).toLowerCase()));
      }catch(e){}
    });
    return set;
  }

  window.smngAnalyze = function(){
    const text = document.getElementById('smngInput')?.value || '';
    const out = document.getElementById('smngResults');
    const stats = document.getElementById('smngStats');
    if(!text.trim()){
      out.innerHTML = '<div class="smng-empty">Önce metin yapıştır.</div>';
      return;
    }

    const words = text.match(/[A-Za-z][A-Za-z'’-]*/g) || [];
    const freq = {};
    words.map(norm).filter(w => w.length>1 && !STOP.has(w)).forEach(w => freq[w] = (freq[w]||0)+1);

    const known = getKnownSet();
    const results = Object.entries(freq).map(([word,count])=>{
      const f = findEntry(word);
      return {
        word,
        count,
        dictKey:f?.key || word,
        found:!!f,
        entry:f?.entry || null,
        known: known.has(word) || known.has(f?.key || '')
      };
    })
    .filter(x => !x.known)
    .sort((a,b)=> (b.found-a.found) || b.count-a.count || a.word.localeCompare(b.word))
    .slice(0,300);

    window.SMNG_LAST_RESULTS = results;

    const found = results.filter(x=>x.found).length;
    stats.style.display = 'grid';
    stats.innerHTML = `
      <div class="smng-stat"><b>${words.length}</b><span>TOPLAM KELİME</span></div>
      <div class="smng-stat"><b>${Object.keys(freq).length}</b><span>FARKLI KELİME</span></div>
      <div class="smng-stat"><b>${results.length}</b><span>ADAY KELİME</span></div>
      <div class="smng-stat"><b>${found}</b><span>SÖZLÜKTE BULUNAN</span></div>
    `;

    if(!results.length){
      out.innerHTML = '<div class="smng-empty">Çıkarılacak yeni kelime bulunamadı.</div>';
      return;
    }

    out.innerHTML = '<div class="smng-list">' + results.map((r,i)=>{
      const e = r.entry || {};
      const meanings = (e.meanings || [e.anlam1,e.anlam2,e.anlam3,e.tr,e.meaning]).filter(Boolean).slice(0,3);
      const m = meanings.length ? meanings.join(' • ') : (r.found ? 'Anlam alanı boş' : 'Sözlükte bulunamadı');
      const pron = e.pron || e.türkçe_okunuş || '';
      return `
        <div class="smng-word" data-word="${esc(r.dictKey)}">
          <div class="smng-word-body">
            <div class="smng-word-title">${i+1}. ${esc(r.dictKey)}</div>
            <div class="smng-word-meaning">${esc(m)}</div>
            <div class="smng-word-meta">
              <span class="smng-chip">${r.count} kez geçti</span>
              ${pron ? `<span class="smng-chip">Okunuş: ${esc(pron)}</span>` : ''}
              ${e.level ? `<span class="smng-chip">CEFR: ${esc(e.level)}</span>` : ''}
              ${e.zipf ? `<span class="smng-chip">Zipf: ${esc(e.zipf)}</span>` : ''}
              ${!r.found ? `<span class="smng-chip" style="background:#422006;color:#fb923c">sözlükte yok</span>` : ''}
            </div>
          </div>
          <div class="smng-actions">
            <button class="smng-mini smng-green" onclick="smngAddToStudy('${encodeURIComponent(r.dictKey)}')">Ekle</button>
            <button class="smng-mini smng-orange" onclick="smngOpenContext('${encodeURIComponent(r.dictKey)}')">Açıkla</button>
          </div>
        </div>
      `;
    }).join('') + '</div>';
  };

  function readArr(key){
    try{
      const v = JSON.parse(localStorage.getItem(key) || '[]');
      return Array.isArray(v) ? v : [];
    }catch(e){ return []; }
  }
  function writeArr(key, arr){
    try{ localStorage.setItem(key, JSON.stringify(arr)); return true; }
    catch(e){ console.warn('storage write failed', key, e); return false; }
  }

  window.smngAddToStudy = function(encodedWord){
    const word = decodeURIComponent(encodedWord || '').trim();
    if(!word) return;
    const f = findEntry(word);
    const e = f?.entry || {};
    const arr = readArr('studyWords');
    if(!arr.some(x => String(x.word || x.Kelime || x).toLowerCase() === word.toLowerCase())){
      arr.push({
        word,
        Kelime: word,
        meanings: e.meanings || [e.anlam1,e.anlam2,e.anlam3].filter(Boolean),
        turkishPronunciation: e.pron || e.türkçe_okunuş || '',
        source: 'sentence-mining',
        addedAt: new Date().toISOString()
      });
      writeArr('studyWords', arr);
    }
    alert(word + ' çalışılacaklara eklendi.');
  };

  window.smngAddAllToStudy = function(){
    const list = (window.SMNG_LAST_RESULTS || []).filter(x=>x.found).slice(0,100);
    if(!list.length){ alert('Önce analiz yap veya sözlükte bulunan kelime yok.'); return; }
    let added = 0;
    list.forEach(x=>{
      const before = readArr('studyWords').length;
      window.smngAddToStudy(encodeURIComponent(x.dictKey));
      const after = readArr('studyWords').length;
      if(after>before) added++;
    });
    alert(added + ' kelime eklendi.');
  };

  window.smngOpenContext = function(encodedWord){
    const word = decodeURIComponent(encodedWord || '');
    const inp = document.getElementById('ctxWordInput');
    if(inp) inp.value = word;
    if(typeof showScreen === 'function') showScreen('sc-context-teacher');
    if(typeof renderContextTeacher === 'function') renderContextTeacher();
  };

  window.smngLoadSample = function(){
    const t = `When people learn a new language, they often recognize many words but cannot use them naturally in conversation. Sentence mining helps learners collect useful phrases from real texts and review them later.`;
    const el = document.getElementById('smngInput');
    if(el) el.value = t;
    window.smngAnalyze();
  };

  window.smngClear = function(){
    const el = document.getElementById('smngInput');
    const out = document.getElementById('smngResults');
    const stats = document.getElementById('smngStats');
    if(el) el.value = '';
    if(out) out.innerHTML = '<div class="smng-empty">Henüz analiz yapılmadı.</div>';
    if(stats) stats.style.display = 'none';
    window.SMNG_LAST_RESULTS = [];
  };

  window.openSentenceMining = function(){
    if(typeof showScreen === 'function') showScreen('sentence-mining');
  };

  function injectSentenceMiningButton(){
    if(document.getElementById('btnSentenceMiningInjected')) return;
    const btn = document.createElement('button');
    btn.id = 'btnSentenceMiningInjected';
    btn.className = 'btn btn-purple';
    btn.style.marginTop = '8px';
    btn.innerHTML = '⛏️ Sentence Mining';
    btn.onclick = window.openSentenceMining;

    const candidates = Array.from(document.querySelectorAll('.feature-category,.card,div'));
    const tools = candidates.find(el => /Araçlar/i.test(el.textContent || '') && el.offsetParent !== null);
    if(tools){
      const target = tools.querySelector('.feature-content > div') || tools;
      target.appendChild(btn);
    } else {
      const wordScreen = document.getElementById('wordScreen') || document.getElementById('screen-word') || document.querySelector('.screen.active') || document.body;
      wordScreen.appendChild(btn);
    }
  }

  document.addEventListener('DOMContentLoaded', ()=>setTimeout(injectSentenceMiningButton, 700));
  setTimeout(injectSentenceMiningButton, 1500);
})();


