(function(){'use strict';const VC={target:null,user:null,rec:null,chunks:[],stream:null,audioCtx:null,startTime:0};function $(id){return document.getElementById(id)}
window.vcOpenOverlay=function(){let ov=$('voiceCompareOverlay');if(ov)ov.classList.add('active');vcDrawEmpty('vcTargetWave','Hedef');vcDrawEmpty('vcUserWave','Kayıt')};
window.vcCloseOverlay=function(){let ov=$('voiceCompareOverlay');if(ov)ov.classList.remove('active');try{if(VC.stream)VC.stream.getTracks().forEach(t=>t.stop())}catch(e){}};
function getText(){return ($('vcText')?.value||'').trim()||'water'}
function makeSyntheticTarget(text){const len=Math.max(1,text.length);const duration=Math.min(4.5,Math.max(.75,.13*len+(text.split(/\s+/).length*.25)));const n=320;let data=[],seed=0;for(let i=0;i<text.length;i++)seed+=text.charCodeAt(i);for(let i=0;i<n;i++){let t=i/n,env=Math.sin(Math.PI*t);let v=env*(Math.sin((10+seed%7)*Math.PI*t)*.55+Math.sin((27+seed%11)*Math.PI*t)*.25);data.push(v)}return metricsFromWave(data,duration)}
function metricsFromWave(wave,duration){const abs=wave.map(x=>Math.abs(x));const avg=abs.reduce((a,b)=>a+b,0)/Math.max(1,abs.length);let peaks=[];for(let i=1;i<abs.length-1;i++){if(abs[i]>abs[i-1]&&abs[i]>abs[i+1]&&abs[i]>avg*1.25)peaks.push(i)}const zcr=wave.slice(1).reduce((n,x,i)=>n+((x>=0)!=(wave[i]>=0)?1:0),0)/Math.max(1,wave.length-1);return{wave,duration,energy:avg,peaks:peaks.length,zcr}}
function resample(arr,n){if(!arr||!arr.length)return Array(n).fill(0);let out=[];for(let i=0;i<n;i++)out.push(arr[Math.floor(i*arr.length/n)]||0);return out}
function drawWave(canvasId,wave){let c=$(canvasId);if(!c)return;let ctx=c.getContext('2d'),w=c.width,h=c.height;ctx.clearRect(0,0,w,h);ctx.fillStyle='#070b16';ctx.fillRect(0,0,w,h);ctx.strokeStyle='#1f2a44';ctx.lineWidth=1;for(let x=0;x<w;x+=40){ctx.beginPath();ctx.moveTo(x,0);ctx.lineTo(x,h);ctx.stroke()}ctx.beginPath();ctx.moveTo(0,h/2);ctx.lineTo(w,h/2);ctx.stroke();let data=resample(wave,w);let grad=ctx.createLinearGradient(0,0,w,0);grad.addColorStop(0,'#3b82f6');grad.addColorStop(.5,'#a78bfa');grad.addColorStop(1,'#22c55e');ctx.strokeStyle=grad;ctx.lineWidth=2;ctx.beginPath();data.forEach((v,i)=>{let y=h/2-v*(h*.42);if(i===0)ctx.moveTo(i,y);else ctx.lineTo(i,y)});ctx.stroke();ctx.globalAlpha=.25;ctx.fillStyle=grad;data.forEach((v,i)=>{let amp=Math.abs(v)*(h*.38);ctx.fillRect(i,h/2-amp,1,amp*2)});ctx.globalAlpha=1}
window.vcDrawEmpty=function(canvasId,label){let c=$(canvasId);if(!c)return;let ctx=c.getContext('2d');ctx.fillStyle='#070b16';ctx.fillRect(0,0,c.width,c.height);ctx.fillStyle='#64748b';ctx.font='16px Arial';ctx.textAlign='center';ctx.fillText(label||'Ses dalgası',c.width/2,c.height/2)};
window.vcSpeakTarget=function(){let text=getText();VC.target=makeSyntheticTarget(text);drawWave('vcTargetWave',VC.target.wave);$('vcTargetMeta').textContent=`Hedef referans hazır • tahmini süre: ${VC.target.duration.toFixed(2)} sn`;try{speechSynthesis.cancel();let u=new SpeechSynthesisUtterance(text);u.lang='en-US';u.rate=.82;u.pitch=1;speechSynthesis.speak(u)}catch(e){}};
window.vcToggleRecord=async function(){let btn=$('vcRecordBtn');if(VC.rec&&VC.rec.state==='recording'){VC.rec.stop();btn.innerHTML='🎤 Kaydet';btn.className='vc-btn vc-red';return}try{VC.stream=await navigator.mediaDevices.getUserMedia({audio:true});VC.audioCtx=new (window.AudioContext||window.webkitAudioContext)();VC.chunks=[];VC.rec=new MediaRecorder(VC.stream);VC.startTime=performance.now();VC.rec.ondataavailable=e=>{if(e.data&&e.data.size)VC.chunks.push(e.data)};VC.rec.onstop=async()=>{let duration=(performance.now()-VC.startTime)/1000;let blob=new Blob(VC.chunks,{type:'audio/webm'});let buf=await blob.arrayBuffer();let wave=[];try{let audioBuffer=await VC.audioCtx.decodeAudioData(buf.slice(0));let ch=audioBuffer.getChannelData(0),n=640;for(let i=0;i<n;i++){let start=Math.floor(i*ch.length/n),end=Math.floor((i+1)*ch.length/n),sum=0,count=0;for(let j=start;j<end;j++){sum+=ch[j];count++}wave.push(count?sum/count:0)}}catch(e){wave=Array.from({length:640},(_,i)=>Math.sin(i/12)*Math.random()*.25)}VC.user=metricsFromWave(wave,duration);drawWave('vcUserWave',VC.user.wave);$('vcUserMeta').textContent=`Kayıt hazır • süre: ${duration.toFixed(2)} sn`;try{VC.stream.getTracks().forEach(t=>t.stop())}catch(e){}};VC.rec.start();btn.innerHTML='<span class="vc-rec-dot"></span> Kaydı Durdur';btn.className='vc-btn vc-green';$('vcUserMeta').textContent='Kayıt alınıyor...'}catch(e){alert('Mikrofon izni alınamadı: '+(e.message||e))}};
function scoreDuration(t,u){let diff=Math.abs(t.duration-u.duration)/Math.max(t.duration,u.duration,.1);return Math.max(0,Math.round(100-diff*115))}
function scoreEnergy(t,u){let diff=Math.abs(t.energy-u.energy)/Math.max(t.energy,u.energy,.01);return Math.max(0,Math.round(100-diff*100))}
function scoreRhythm(t,u){let pdiff=Math.abs(t.peaks-u.peaks)/Math.max(t.peaks,u.peaks,1);let zdiff=Math.abs(t.zcr-u.zcr)/Math.max(t.zcr,u.zcr,.01);return Math.max(0,Math.round(100-(pdiff*.65+zdiff*.35)*100))}
function setBar(id,val){let b=$(id);if(b)b.style.width=Math.max(0,Math.min(100,val))+'%'}function setText(id,val){let e=$(id);if(e)e.textContent=val+'%'}
window.vcCompareNow=function(){if(!VC.target)vcSpeakTarget();if(!VC.user){$('vcFeedback').innerHTML='Önce kendi sesini kaydetmelisin.';return}let rhythm=scoreRhythm(VC.target,VC.user),duration=scoreDuration(VC.target,VC.user),energy=scoreEnergy(VC.target,VC.user),overall=Math.round(rhythm*.4+duration*.35+energy*.25);$('vcStats').innerHTML=`<div class="vc-stat"><b>${rhythm}%</b><span>RİTİM</span></div><div class="vc-stat"><b>${duration}%</b><span>SÜRE</span></div><div class="vc-stat"><b>${energy}%</b><span>ENERJİ</span></div><div class="vc-stat"><b>${overall}%</b><span>GENEL</span></div>`;setBar('vcBarRhythm',rhythm);setBar('vcBarDuration',duration);setBar('vcBarEnergy',energy);setText('vcValRhythm',rhythm);setText('vcValDuration',duration);setText('vcValEnergy',energy);let tips=[];if(duration<70)tips.push(VC.user.duration<VC.target.duration?'Kelimeyi biraz hızlı söyledin; sesleri daha uzun tut.':'Kelimeyi hedefe göre uzun söyledin; daha kısa ve net söyle.');if(energy<70)tips.push('Ses enerjin hedefle farklı. Daha dengeli ve net bir sesle tekrar dene.');if(rhythm<70)tips.push('Ritim farklı. Hedefi dinleyip vurguyu aynı yerde yapmaya çalış.');if(!tips.length)tips.push('Güzel! Süre, enerji ve ritim hedefe oldukça yakın.');$('vcFeedback').innerHTML=`<b style="color:#86efac">Genel uyum: ${overall}%</b><br>${tips.map(t=>'• '+t).join('<br>')}`;try{let hist=JSON.parse(localStorage.getItem('voiceCompareHistory')||'[]');if(Array.isArray(hist)){hist.unshift({text:getText(),rhythm,duration,energy,overall,date:new Date().toISOString()});localStorage.setItem('voiceCompareHistory',JSON.stringify(hist.slice(0,100)))}}catch(e){}};
window.vcReset=function(){VC.target=null;VC.user=null;vcDrawEmpty('vcTargetWave','Hedef');vcDrawEmpty('vcUserWave','Kayıt');$('vcTargetMeta').textContent='Henüz hedef ses üretilmedi.';$('vcUserMeta').textContent='Henüz kayıt yok.';$('vcStats').innerHTML='<div class="vc-stat"><b>-</b><span>RİTİM</span></div><div class="vc-stat"><b>-</b><span>SÜRE</span></div><div class="vc-stat"><b>-</b><span>ENERJİ</span></div><div class="vc-stat"><b>-</b><span>GENEL</span></div>';['vcBarRhythm','vcBarDuration','vcBarEnergy'].forEach(id=>setBar(id,0));['vcValRhythm','vcValDuration','vcValEnergy'].forEach(id=>{let e=$(id);if(e)e.textContent='-'});$('vcFeedback').textContent='Karşılaştırma yapmak için hedefi dinle ve kendi sesini kaydet.'};
document.addEventListener('DOMContentLoaded',()=>setTimeout(()=>{vcDrawEmpty('vcTargetWave','Hedef');vcDrawEmpty('vcUserWave','Kayıt')},500));
})();


