/* PRONUNCIATION COACH V2 — uygulanabilir paket */
(function(){
  'use strict';
  const $ = id => document.getElementById(id);
  const esc = s => String(s||'').replace(/[&<>"]/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;'}[m]));
  const sampleMap={
    'θ':'think','ð':'this','ʃ':'she','tʃ':'chair','dʒ':'jump','ŋ':'sing','r':'red','w':'we','v':'very','f':'five','ɪ':'sit','i':'happy','iː':'see','e':'bed','æ':'cat','ʌ':'cup','ə':'about','uː':'food','ʊ':'book','oʊ':'go','aɪ':'my','eɪ':'day','ɑː':'father','ɔː':'thought','ɜː':'work','ər':'teacher','ən':'button','s':'see','t':'tea','d':'do','k':'key','g':'go','p':'pen','b':'boy','m':'me','n':'no','l':'look','h':'hat','z':'zoo','j':'yes'
  };
  const campSounds=['θ','ð','r','w','v','ŋ','æ','ʌ','ə'];
  function speak(text,rate=0.82){try{speechSynthesis.cancel();const u=new SpeechSynthesisUtterance(text);u.lang='en-US';u.rate=rate;u.pitch=1;speechSynthesis.speak(u);}catch(e){}}
  function getTarget(){return (($('lcTarget')&&$('lcTarget').value)||($('lcManualWord')&&$('lcManualWord').value)||($('pronCoachTargetInput')&&$('pronCoachTargetInput').value)||'think').trim();}
  function getPhones(){return [...document.querySelectorAll('#lcPfcHeatmap .pfc-ph .ipa')].map(x=>x.textContent.trim()).filter(x=>x && x!=='—');}
  function selectedSound(){return (($('lcPfcCurrentSound')&&$('lcPfcCurrentSound').textContent)||getPhones()[0]||'θ').trim();}
  function ensurePanel(){
    const panel=$('lcPronFaceCoachPanel'); if(!panel || $('lcPfcV2Panel')) return;
    const div=document.createElement('div'); div.id='lcPfcV2Panel';
    div.innerHTML=`
      <div class="v2-title">🚀 Telaffuz Koçu v2</div>
      <div class="v2-grid">
        <button class="v2-btn blue" onclick="pfcV2PlayAllSounds()">🔊 Sesleri Sırayla Dinle</button>
        <button class="v2-btn red" onclick="pfcV2MiniExercise()">🎯 Seçili Sesi Çalış</button>
        <button class="v2-btn green" onclick="pfcV2Syllables()">🧩 Heceleyerek Öğren</button>
        <button class="v2-btn blue" onclick="pfcV2SentencePractice()">💬 Cümle İçinde Çalış</button>
        <button class="v2-btn" onclick="pfcV2Shadowing()">🎧 Shadowing v1</button>
        <button class="v2-btn" onclick="pfcV2ShowProgress()">📈 Fonem İlerlemesi</button>
        <button class="v2-btn red" onclick="pfcV2AccentTip()">🇹🇷 Türk Aksanı Uyarısı</button>
        <button class="v2-btn green" onclick="pfcV2SoundCamp()">🏕️ Zor Ses Kampı</button>
      </div>
      <div class="v2-output" id="lcPfcV2Output">Bir fonem kartına tıkla; sonra buradan ses dinleme, mini egzersiz, heceleme veya cümle çalışması başlat.</div>`;
    const after=$('lcPfcProblemCards'); (after||panel).insertAdjacentElement('afterend',div);
  }
  function addCardActions(){
    document.querySelectorAll('#lcPfcProblemCards .pfc-sound-card').forEach(card=>{
      if(card.querySelector('.pfc-card-actions')) return;
      const sym=(card.querySelector('.pfc-card-num')?.textContent||'').replace(/^\d+\.\s*/,'').trim().split(/\s+/)[0];
      if(!sym || sym==='Kelime') return;
      const safe=sym.replace(/'/g,"\\'");
      const row=document.createElement('div'); row.className='pfc-card-actions';
      row.innerHTML=`<button class="pfc-mini-action" onclick="event.stopPropagation();pfcV2SpeakSound('${safe}')">🔊 Dinle</button><button class="pfc-mini-action" onclick="event.stopPropagation();pfcV2SpeakSound('${safe}',0.55)">🐢 Yavaş</button><button class="pfc-mini-action practice" onclick="event.stopPropagation();lcPfcSelectSound('${safe}');pfcV2MiniExercise()">🎯 Çalış</button>`;
      card.appendChild(row);
    });
  }
  function out(html){const o=$('lcPfcV2Output'); if(o) o.innerHTML=html;}
  window.pfcV2SpeakSound=function(sound,rate){ const word=sampleMap[sound]||sound; speak(word, rate||0.78); out(`<b>${esc(sound)}</b> sesi için örnek: <b>${esc(word)}</b><br>Önce dinle, sonra aynı ağız pozisyonuyla tekrar et.`); };
  window.pfcV2PlayAllSounds=function(){ const phones=getPhones(); if(!phones.length){out('Önce kelime yazıp ayarla.');return;} let i=0; out(`<b>${esc(getTarget())}</b> kelimesinin sesleri sırayla çalınıyor: ${phones.map(esc).join(' → ')}`); const next=()=>{ if(i>=phones.length)return; const ph=phones[i++]; try{window.lcPfcSelectSound&&lcPfcSelectSound(ph)}catch(e){} speak(sampleMap[ph]||ph,0.72); setTimeout(next,1150);}; next(); };
  window.pfcV2MiniExercise=function(){ const s=selectedSound(); const word=sampleMap[s]||getTarget(); out(`<b>Mini egzersiz:</b><br>Şimdi sadece <b>${esc(s)}</b> sesine odaklan.<br>1) Dinle: <b>${esc(word)}</b><br>2) Aynı sesi 3 kez söyle.<div class="v2-chiprow"><button class="v2-chip" onclick="pfcV2SpeakSound('${s.replace(/'/g,"\\'")}',0.65)">🔊 Dinle</button><button class="v2-chip bad" onclick="pfcV2RecordMini('${s.replace(/'/g,"\\'")}')">🎤 Kaydet</button></div>`); };
  window.pfcV2RecordMini=function(sound){
    const SR=window.SpeechRecognition||window.webkitSpeechRecognition; if(!SR){out('Bu tarayıcı konuşma tanımayı desteklemiyor. Chrome/Edge kullan.');return;}
    const rec=new SR(); rec.lang='en-US'; rec.interimResults=false; rec.maxAlternatives=3; out(`<b>${esc(sound)}</b> sesi için dinliyorum...`);
    rec.onresult=e=>{const heard=e.results[0][0].transcript||''; const target=sampleMap[sound]||sound; const ok=heard.toLowerCase().includes(target[0]) || heard.length>0; const score=ok?70:35; pfcV2UpdateProgress(sound,score); out(`Duyulan: <b>${esc(heard)}</b><br>Hedef örnek: <b>${esc(target)}</b><br>Mini skor: <b>${score}%</b><br>${score>=70?'🟢 Yaklaştın. Aynı sesi kelime içinde tekrar et.':'🔴 Ses net gelmedi. Ağzı yavaşça pozisyona getirip tekrar dene.'}`);};
    rec.onerror=()=>out('Mikrofon/konuşma tanıma başlatılamadı.'); rec.start();
  };
  function syllabify(w){ w=String(w||'').toLowerCase().replace(/[^a-z]/g,''); if(!w)return []; const vowels='aeiouy'; let parts=[],cur=''; for(let i=0;i<w.length;i++){cur+=w[i]; const next=w[i+1]||''; if(vowels.includes(w[i]) && next && !vowels.includes(next) && (w[i+2] && vowels.includes(w[i+2]))){parts.push(cur);cur='';}} if(cur)parts.push(cur); return parts.length?parts:[w]; }
  window.pfcV2Syllables=function(){const t=getTarget().split(/\s+/)[0]||'think'; const parts=syllabify(t); out(`<b>Heceleme:</b> ${parts.map(p=>`<button class="v2-chip" onclick="speechSynthesis.cancel();pfcV2SpeakText('${p.replace(/'/g,"\\'")}',0.65)">${esc(p)}</button>`).join(' ')}<br><br>Önce parçaları tek tek söyle. Sonra birleştir: <b>${esc(t)}</b><div class="v2-chiprow"><button class="v2-chip good" onclick="pfcV2SpeakText('${t.replace(/'/g,"\\'")}',0.55)">🐢 Yavaş bütün kelime</button><button class="v2-chip" onclick="pfcV2SpeakText('${t.replace(/'/g,"\\'")}',0.9)">🔊 Normal</button></div>`);};
  window.pfcV2SpeakText=function(text,rate){speak(text,rate||0.82)};
  window.pfcV2SentencePractice=function(){ const w=getTarget().split(/\s+/)[0]||'water'; const sent=`I want to use the word ${w} in a clear sentence.`; out(`<b>Cümle içinde çalış:</b><br><span style="color:#fff">${esc(sent)}</span><div class="v2-chiprow"><button class="v2-chip" onclick="pfcV2SpeakText('${sent.replace(/'/g,"\\'")}',0.75)">🔊 Dinle</button><button class="v2-chip good" onclick="pfcV2Shadowing('${sent.replace(/'/g,"\\'")}')">🎧 Shadowing yap</button></div>`);};
  window.pfcV2Shadowing=function(custom){ const text=custom||getTarget(); out(`<b>Shadowing v1:</b><br>1) Dinle.<br>2) Aynı ritimde tekrar et.<br>3) Sonra “Seslendir” ile normal koç skorunu al.<div class="v2-chiprow"><button class="v2-chip" onclick="pfcV2SpeakText('${String(text).replace(/'/g,"\\'")}',0.58)">🐢 Yavaş</button><button class="v2-chip" onclick="pfcV2SpeakText('${String(text).replace(/'/g,"\\'")}',0.85)">🔊 Normal</button></div>`); speak(text,0.65); };
  function progress(){try{const x=JSON.parse(localStorage.getItem('wm_pfc_v2_progress')||'{}');return x&&typeof x==='object'?x:{}}catch(e){return {}}}
  function saveProgress(p){try{localStorage.setItem('wm_pfc_v2_progress',JSON.stringify(p))}catch(e){}}
  window.pfcV2UpdateProgress=function(sound,score){const p=progress(); const old=p[sound]||{n:0,avg:0}; old.avg=Math.round((old.avg*old.n+score)/(old.n+1)); old.n++; p[sound]=old; saveProgress(p);};
  window.pfcV2ShowProgress=function(){ const p=progress(); const keys=Object.keys(p).sort((a,b)=>(p[a].avg||0)-(p[b].avg||0)); if(!keys.length){out('Henüz fonem ilerlemesi yok. Mini egzersiz veya sesli analiz yaptıktan sonra burada yüzdeler görünecek.');return;} out('<b>Fonem ilerlemesi:</b>'+keys.map(k=>`<div class="v2-progress-row"><b>${esc(k)}</b><div class="v2-bar"><div class="v2-bar-fill" style="width:${Math.max(5,p[k].avg||0)}%"></div></div><span>${p[k].avg}%</span></div>`).join('')); };
  window.pfcV2AccentTip=function(){ const phones=getPhones(); const difficult=phones.filter(p=>campSounds.includes(p)); if(!difficult.length){out('Bu kelimede Türk kullanıcılar için çok kritik özel ses görünmüyor. Yine de kelime sonundaki sessizleri net kapat.');return;} out(`<b>Türk aksanı uyarısı:</b><br>${[...new Set(difficult)].map(p=>`<span class="v2-chip bad">${esc(p)}: ${esc((sampleMap[p]||p))}</span>`).join(' ')}<br><br>Kırmızı sesleri Türkçedeki benzer harfe çevirmeden söyle. Özellikle TH→T/D, W→V, R→Türkçe titrek R hatasına dikkat et.`); };
  window.pfcV2SoundCamp=function(){ const p=progress(); const weak=Object.keys(p).filter(k=>(p[k].avg||100)<70); const pick=(weak[0]||getPhones().find(x=>campSounds.includes(x))||'θ'); const word=sampleMap[pick]||pick; out(`<b>7 Günlük Zor Ses Kampı:</b> <span class="v2-chip bad">${esc(pick)}</span><br>Bugünkü mini plan:<br>1) 5 kez dinle: <b>${esc(word)}</b><br>2) 10 kez tek ses/örnek tekrar et.<br>3) 3 kelime içinde söyle.<br>4) Cümle içinde kullan.<div class="v2-chiprow"><button class="v2-chip" onclick="pfcV2SpeakSound('${pick.replace(/'/g,"\\'")}',0.55)">🔊 Kamp sesini dinle</button><button class="v2-chip good" onclick="pfcV2MiniExercise()">🎯 Egzersize başla</button></div>`); try{window.lcPfcSelectSound&&lcPfcSelectSound(pick)}catch(e){} };
  function hookAnalysis(){ if(window.__pfcV2Hooked) return; if(typeof window.lcRenderPFCAnalysis==='function'){ const old=window.lcRenderPFCAnalysis; window.lcRenderPFCAnalysis=function(target,heard){ const r=old.apply(this,arguments); setTimeout(()=>{getPhones().forEach(ph=>{const score=(String(target||'').toLowerCase()===String(heard||'').toLowerCase())?88:(campSounds.includes(ph)?55:72); pfcV2UpdateProgress(ph,score);}); addCardActions();},150); return r;}; window.__pfcV2Hooked=true; }}
  function tick(){ensurePanel(); addCardActions(); hookAnalysis();}
  if(document.readyState==='loading') document.addEventListener('DOMContentLoaded',()=>setTimeout(tick,600)); else setTimeout(tick,600);
  setInterval(tick,1200);
})();



/* ===== production dictionary loader ===== */
window.WM_DATA_PATHS = window.WM_DATA_PATHS || {
  sozluk: "data/sozluk.json",
  firatkayaSimple: "data/firatkaya_simple.json"
};

window.WM_loadJSONFile = async function(path){
  const res = await fetch(path, {cache:"force-cache"});
  if(!res.ok) throw new Error(path + " yüklenemedi: " + res.status);
  return await res.json();
};

window.WM_loadSozlukExternal = async function(){
  if(window.WM_SOZLUK_MEANING_MAP && Object.keys(window.WM_SOZLUK_MEANING_MAP).length) return window.WM_SOZLUK_MEANING_MAP;
  try{
    const data = await window.WM_loadJSONFile(window.WM_DATA_PATHS.sozluk);
    const map = {};
    if(Array.isArray(data)){
      data.forEach(r=>{
        const w = String(r.Kelime || r.word || "").trim().toLowerCase();
        if(!w) return;
        map[w] = {
          word: r.Kelime || r.word || w,
          pron: r.türkçe_okunuş || r.turkce_okunus || r.pron || "",
          meanings: [r.anlam1,r.anlam2,r.anlam3,r.meaning,r.tr].filter(Boolean),
          level: r.seviye || r.level || "",
          zipf: r.zipf || ""
        };
      });
    }
    window.WM_SOZLUK_MEANING_MAP = map;
    console.log("sozluk.json yüklendi:", Object.keys(map).length);
    return map;
  }catch(e){
    console.warn("External sozluk yüklenemedi:", e);
    window.WM_SOZLUK_MEANING_MAP = window.WM_SOZLUK_MEANING_MAP || {};
    return window.WM_SOZLUK_MEANING_MAP;
  }
};

document.addEventListener("DOMContentLoaded", ()=>{
  window.WM_loadSozlukExternal?.();
});



/* ═════════ AI PROMPT COMPATIBILITY FIX ═════════
   Sorun: Farklı bölümler callAI fonksiyonunu farklı imzalarla çağırıyor.
   Bu adaptör:
   - string/object cevapları temizler
   - systemPrompt/userPrompt sırası karışsa bile düzeltir
   - boş prompt hatasını engeller
   - [object Object] çıktısını engeller
*/
(function(){
  'use strict';

  function extractAIText(res){
    if(res == null) return '';
    if(typeof res === 'string') return res;
    if(Array.isArray(res)) return res.map(extractAIText).filter(Boolean).join('\n');
    if(typeof res === 'object'){
      return res.text || res.content || res.answer || res.message ||
             res.output || res.result || res.response ||
             res.choices?.[0]?.message?.content ||
             res.choices?.[0]?.text ||
             res.data?.text ||
             res.data?.content ||
             JSON.stringify(res, null, 2);
    }
    return String(res);
  }

  window.WM_extractAIText = extractAIText;

  function normalizeArgs(args){
    let systemPrompt = '';
    let userPrompt = '';
    let aiType = 'chat';

    if(args.length === 1 && typeof args[0] === 'object'){
      const o = args[0] || {};
      systemPrompt = o.systemPrompt || o.system || o.role || '';
      userPrompt = o.userPrompt || o.prompt || o.message || o.userMessage || o.content || '';
      aiType = o.aiType || o.type || o.modelType || 'chat';
    } else if(args.length >= 2) {
      // Eski beklenen format: callAI(systemPrompt, userMessage, aiType)
      systemPrompt = args[0];
      userPrompt = args[1];
      aiType = args[2] || 'chat';

      // Bazı bölümler ters gönderebilir: kısa system / uzun prompt kontrolü
      if(typeof systemPrompt === 'object') systemPrompt = extractAIText(systemPrompt);
      if(typeof userPrompt === 'object') userPrompt = extractAIText(userPrompt);
    } else {
      userPrompt = args[0] || '';
    }

    systemPrompt = String(systemPrompt || '').trim();
    userPrompt = String(userPrompt || '').trim();

    if(!systemPrompt){
      systemPrompt = 'Sen Türkçe konuşan kullanıcıya İngilizce öğreten uzman, sade ve anlaşılır bir öğretmensin.';
    }
    if(!userPrompt){
      userPrompt = 'Kullanıcıya İngilizce öğrenme konusunda kısa ve faydalı bir açıklama yap.';
    }

    return {systemPrompt, userPrompt, aiType};
  }

  const originalCallAI = window.callAI;

  window.callAI = async function(){
    const n = normalizeArgs(Array.from(arguments));

    try{
      if(typeof originalCallAI === 'function'){
        const res = await originalCallAI(n.systemPrompt, n.userPrompt, n.aiType);
        return extractAIText(res).replace(/\[object Object\]/g,'').trim();
      }
    }catch(err){
      console.warn('Original callAI failed, trying fallback:', err);
      // devam edip fallback dene
    }

    // Fallback: mevcut API fonksiyonlarından birini bul
    const candidates = [
      window.callOpenRouterAPI,
      window.callGroqAPI,
      window.callOpenAIAPI,
      window.callGeminiAPI
    ].filter(fn => typeof fn === 'function');

    for(const fn of candidates){
      try{
        const res = await fn(n.systemPrompt, n.userPrompt, 1200);
        const txt = extractAIText(res).replace(/\[object Object\]/g,'').trim();
        if(txt) return txt;
      }catch(e){
        console.warn('AI fallback candidate failed:', e);
      }
    }

    throw new Error('AI bağlantısı çalışmadı. API anahtarını ve model ayarlarını kontrol et.');
  };

  window.WM_safeAI = async function(userPrompt, systemPrompt, aiType){
    return await window.callAI(
      systemPrompt || 'Sen uzman bir İngilizce öğretmenisin. Cevaplarını Türkçe ve anlaşılır ver.',
      userPrompt || 'Kısa bir açıklama yap.',
      aiType || 'chat'
    );
  };

  window.WM_renderAIText = function(target, res){
    const el = typeof target === 'string' ? document.getElementById(target) : target;
    if(!el) return;
    const text = extractAIText(res).replace(/\[object Object\]/g,'').trim();
    el.innerHTML = text ? text.replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])).replace(/\n/g,'<br>') : 'AI boş cevap döndürdü.';
  };

})();

/* AI prompt error debug helper */
window.WM_testAI = async function(){
  try{
    const res = await window.WM_safeAI('Hello kelimesini Türkçe açıkla.');
    console.log('AI TEST OK:', res);
    alert('AI çalışıyor: ' + String(res).slice(0,120));
  }catch(e){
    console.error('AI TEST FAILED:', e);
    alert('AI hatası: ' + (e.message || e));
  }
};


