// === WM CORE LEARNED BUTTON FIX V2 ===
// Gerçek "Öğrendim" işlemini dış yama scriptlerinden bağımsız çalıştırır.
// Bu fonksiyon app.js içinde tanımlandığı için words/idx/learnedSet gibi ana state'e doğrudan erişir.
window.WM_coreMarkLearned = function WM_coreMarkLearned(){
  try{
    const item = words[idx];
    if(!item || !item.word) return false;

    const word = item.word;
    const listNameBefore = (typeof getActiveListName === 'function') ? getActiveListName() : 'Ana Liste';

    learnedSet.add(word);
    item.learned = true;
    item.isLearned = true;
    item.status = 'learned';
    item.lastReviewed = Date.now();

    if(!wordStatus[word]) wordStatus[word] = {attempts:1, correct:1, pronScore:null};
    wordStatus[word].attempts = Math.max(1, wordStatus[word].attempts || 0);
    wordStatus[word].correct = Math.max(1, wordStatus[word].correct || 0);

    try { recordLearningTime(word); } catch(e) {}
    try { updateSRS(word, true); } catch(e) {}
    try { incrementTodayLearned(); } catch(e) {}

    // Ana ilerlemeyi ve aktif listeye özel ilerlemeyi birlikte kaydet.
    try { saveProgress(); } catch(e) {}
    try { saveCurrentListProgress(); } catch(e) {}

    // LearnedWords deposuna nesne olarak da yaz; ama allWords listesini ezme.
    try{
      const raw = localStorage.getItem('learnedWords');
      let arr = raw ? JSON.parse(raw) : [];
      if(!Array.isArray(arr)) arr = [];
      const exists = arr.some(x => String((typeof x === 'string' ? x : (x && x.word)) || '').toLowerCase() === String(word).toLowerCase());
      if(!exists){
        arr.push(Object.assign({}, item, {word: word, learned: true, date: Date.now(), source: 'learned-button'}));
        localStorage.setItem('learnedWords', JSON.stringify(arr.slice(-1000)));
      }
    }catch(e){}

    try { renderWordList(); } catch(e) {}

    // Sonraki öğrenilmemiş kelimeye geç.
    let nextIndex = words.findIndex((w, i) => i > idx && w && w.word && !learnedSet.has(w.word));
    if(nextIndex === -1) nextIndex = words.findIndex(w => w && w.word && !learnedSet.has(w.word));

    if(nextIndex !== -1){
      idx = nextIndex;
      renderLearn();
    }else{
      renderLearn();
      try { showToast('🎉 Liste tamamlandı', listNameBefore + ' listesindeki tüm kelimeler öğrenildi'); } catch(e) {}
    }

    try { setActiveListTitle(listNameBefore); } catch(e) {}
    return false;
  }catch(err){
    console.error('[WM_coreMarkLearned] hata:', err);
    return false;
  }
};

/* =====================================================================
   WORD MODE — %100 CÜMLE TABANLI ÖĞRENME / SRS KATMANI v5
   Bu blok eski kelime merkezli öğrenme kararlarını devre dışı bırakır.
   word alanı sadece hedef kelime/etiket olarak kalır; öğrenme, renk,
   tekrar, filtre ve liste durumu cümle anahtarıyla tutulur.
   ===================================================================== */
(function(){
  if(window.__WM_SENTENCE_ONLY_V5__) return;
  window.__WM_SENTENCE_ONLY_V5__ = true;

  const KEY = 'wm_sentence_status_v5';
  const ONE_DAY = 24*60*60*1000;
  const INTERVALS = [1,3,7,14,30,90,180];
  const LEVELS = [
    {label:'⚪ Yeni', cls:'wm-sent-new', color:'#64748b'},
    {label:'🟡 Tanıdık', cls:'wm-sent-l1', color:'#eab308'},
    {label:'🟠 Pekişiyor', cls:'wm-sent-l2', color:'#f97316'},
    {label:'🔵 Anlıyorum', cls:'wm-sent-l3', color:'#3b82f6'},
    {label:'🟢 Kullanabiliyorum', cls:'wm-sent-l4', color:'#22c55e'},
    {label:'💚 Güçlü', cls:'wm-sent-l5', color:'#16a34a'},
    {label:'💎 Otomatikleşti', cls:'wm-sent-l6', color:'#06b6d4'}
  ];

  function load(){ try{return JSON.parse(localStorage.getItem(KEY)||'{}')||{};}catch(e){return{};} }
  function save(obj){ try{localStorage.setItem(KEY, JSON.stringify(obj));}catch(e){console.warn('sentenceStatus kaydedilemedi',e);} }
  function esc(s){return String(s??'').replace(/[&<>'"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[c]));}
  function normalizeSentence(s){ return String(s||'').toLowerCase().replace(/\s+/g,' ').replace(/[“”]/g,'"').replace(/[’]/g,"'").trim(); }
  function sentenceKey(item){
    const sent = normalizeSentence(item && item.sentence);
    if(sent) return 'sent:' + sent;
    // Cümlesiz eski kayıtlar için mecburi geçiş anahtarı. Öğrenme yine "cümle kartı" olarak yürür.
    return 'sent:__no_sentence__:' + normalizeSentence(item && (item.word || item.tr || ''));
  }
  function getStatus(item){
    const data = load();
    const key = sentenceKey(item);
    return data[key] || null;
  }
  function putStatus(item, patch){
    const data = load();
    const key = sentenceKey(item);
    const old = data[key] || { key, sentence:item?.sentence||'', word:item?.word||'', createdAt:Date.now(), srsLevel:0, correctStreak:0, wrong:0, realLifeUsed:0 };
    data[key] = Object.assign(old, patch, { key, sentence:item?.sentence||old.sentence||'', word:item?.word||old.word||'', updatedAt:Date.now() });
    save(data);
    window.sentenceStatus = data;
    return data[key];
  }
  function fmt(ts){ if(!ts) return '—'; try{return new Date(ts).toLocaleString('tr-TR',{day:'2-digit',month:'short',year:'numeric',hour:'2-digit',minute:'2-digit'});}catch(e){return '—';} }
  function fmtShort(ts){ if(!ts) return '—'; try{return new Date(ts).toLocaleDateString('tr-TR',{day:'2-digit',month:'short'});}catch(e){return '—';} }
  function dueText(st){
    if(!st || !st.learned) return 'Henüz çalışılmadı';
    const diff = (st.nextReview||0) - Date.now();
    if(diff <= 0) return '🔴 Tekrar bekliyor';
    const d = Math.ceil(diff/ONE_DAY);
    if(d === 1) return '⏰ Yarın';
    return '⏰ ' + d + ' gün sonra';
  }
  function levelInfo(st){
    if(!st || !st.learned) return LEVELS[0];
    return LEVELS[Math.min(Number(st.srsLevel||1), LEVELS.length-1)] || LEVELS[0];
  }
  function isLearnedSentence(item){ const st=getStatus(item); return !!(st && st.learned); }
  function isFailedSentence(item){ const st=getStatus(item); return !!(st && st.wrong>0 && !st.learned); }
  function isDueSentence(item){ const st=getStatus(item); return !!(st && st.learned && st.nextReview && st.nextReview <= Date.now()); }
  function sentenceStats(){
    const arr = Array.isArray(allWords) ? allWords : [];
    const learned = arr.filter(isLearnedSentence).length;
    const failed = arr.filter(isFailedSentence).length;
    const unseen = arr.filter(w=>!getStatus(w)).length;
    const due = arr.filter(isDueSentence).length;
    return {total:arr.length, learned, failed, unseen, due};
  }
  function cardStyle(st){
    const inf=levelInfo(st);
    if(st && st.learned && st.nextReview <= Date.now()) return 'border:2px solid #ef4444;background:linear-gradient(135deg,rgba(239,68,68,.16),rgba(127,29,29,.10));';
    if(!st || !st.learned) return 'border:1.5px solid var(--border);background:var(--bg2);';
    const c=inf.color;
    return `border:2px solid ${c};background:linear-gradient(135deg,${c}24,rgba(15,23,42,.06));`;
  }
  function statusPanel(item){
    const st=getStatus(item); const inf=levelInfo(st);
    if(!st || !st.learned){
      return `<div class="wm-sentence-status" style="${cardStyle(st)}padding:10px;border-radius:14px;margin:10px 0;display:grid;gap:4px">
        <div style="font-size:12px;font-weight:900;color:#e2e8f0">⚪ Cümle henüz çalışılmadı</div>
        <div style="font-size:11px;color:var(--muted)">Öğrendim'e basınca bu cümle SRS-1 olarak kaydedilecek.</div>
      </div>`;
    }
    return `<div class="wm-sentence-status" style="${cardStyle(st)}padding:10px;border-radius:14px;margin:10px 0;display:grid;gap:5px">
      <div style="display:flex;justify-content:space-between;gap:8px;align-items:center;flex-wrap:wrap">
        <span style="font-size:12px;font-weight:900;color:var(--text)">${inf.label} · SRS-${st.srsLevel||1}</span>
        <span style="font-size:11px;font-weight:900;color:${(st.nextReview||0)<=Date.now()?'#f87171':'var(--muted)'}">${dueText(st)}</span>
      </div>
      <div style="font-size:11px;color:var(--muted);line-height:1.55">📅 Öğrenildi: ${fmt(st.learnedAt)}<br>🔄 Son tekrar: ${fmt(st.lastReview)}<br>⏰ Sonraki tekrar: ${fmt(st.nextReview)}${st.realLifeUsed?`<br>🏆 Gerçek kullanım: ${st.realLifeUsed} kez`:''}</div>
    </div>`;
  }
  function injectSentenceCSS(){
    if(document.getElementById('wmSentenceOnlyCss')) return;
    const s=document.createElement('style'); s.id='wmSentenceOnlyCss';
    s.textContent = `
      .wi.wm-sent-due{box-shadow:0 0 0 2px rgba(239,68,68,.55) inset!important;}
      .wi.wm-sent-learned{box-shadow:0 0 0 2px rgba(34,197,94,.45) inset!important;}
      .wm-sent-mini{display:inline-flex;align-items:center;gap:4px;padding:3px 8px;border-radius:999px;font-size:11px;font-weight:900;white-space:nowrap}
      .wm-sent-real-btn{width:100%;margin-top:8px;padding:9px 10px;border:none;border-radius:12px;background:linear-gradient(135deg,#f59e0b,#f97316);color:#fff;font-weight:900;cursor:pointer;font-family:'Nunito',sans-serif}
      .wm-risk-panel{margin:10px 0 12px;padding:12px;border:1.5px solid rgba(239,68,68,.35);border-radius:16px;background:rgba(239,68,68,.08)}
      .wm-risk-item{padding:8px;border-radius:10px;background:var(--bg3);margin-top:6px;font-size:12px;line-height:1.45;cursor:pointer}
    `;
    document.head.appendChild(s);
  }
  injectSentenceCSS();

  window.WMSentenceCore = { load, save, sentenceKey, getStatus, putStatus, isLearnedSentence, isDueSentence, dueText, levelInfo, fmt, fmtShort, sentenceStats };
  window.sentenceStatus = load();

  // Kelime tabanlı updateSRS yerine cümle tabanlı SRS.
  updateSRS = function(anyWord, isCorrect){
    const arr = Array.isArray(words) ? words : [];
    let item = arr[idx] || (Array.isArray(allWords) ? allWords.find(w=>w && w.word===anyWord) : null);
    if(!item) return null;
    const now = Date.now();
    let st = getStatus(item) || {};
    const prevLevel = Number(st.srsLevel || 0);
    let nextLevel;
    if(isCorrect){ nextLevel = Math.min(prevLevel + 1, LEVELS.length-1); }
    else { nextLevel = Math.max(prevLevel - 1, 0); }
    const days = INTERVALS[Math.max(0,nextLevel-1)] || 1;
    return putStatus(item, {
      learned: !!isCorrect || !!st.learned,
      learnedAt: st.learnedAt || (isCorrect ? now : null),
      lastReview: now,
      nextReview: now + days*ONE_DAY,
      srsLevel: nextLevel,
      correctStreak: isCorrect ? (Number(st.correctStreak||0)+1) : 0,
      wrong: isCorrect ? Number(st.wrong||0) : Number(st.wrong||0)+1
    });
  };

  // Öğrendim artık yalnızca cümleyi kaydeder. learnedSet/wordStatus ilerleme kararı için kullanılmaz.
  markLearned = function(){
    const item = words && words[idx];
    if(!item) return false;
    const now = Date.now();
    const old = getStatus(item) || {};
    putStatus(item, {
      learned:true,
      learnedAt: old.learnedAt || now,
      lastReview: now,
      nextReview: now + ONE_DAY,
      srsLevel: Math.max(1, Number(old.srsLevel||0)),
      correctStreak: Math.max(1, Number(old.correctStreak||0))
    });
    try{ showToast('✅ Cümle öğrenildi', item.sentence || item.word || ''); }catch(e){}
    try{ saveProgress(); }catch(e){}
    try{ saveCurrentListProgress(); }catch(e){}
    try{ renderWordList(); }catch(e){}
    const nextIndex = (words||[]).findIndex((w,i)=>i>idx && w && !isLearnedSentence(w));
    if(nextIndex !== -1) idx = nextIndex;
    renderLearn();
    return false;
  };

  window.markSentenceRealUsed = function(){
    const item = words && words[idx]; if(!item) return;
    const st = getStatus(item) || {};
    putStatus(item, { realLifeUsed: Number(st.realLifeUsed||0)+1, lastRealUse:Date.now(), learned: st.learned || true, learnedAt: st.learnedAt || Date.now() });
    try{ showToast('🏆 Gerçek kullanım kaydedildi', item.sentence || item.word || ''); }catch(e){}
    renderLearn();
  };

  // Ana kart render: kelime gösterilir ama durum cümleye aittir.
  renderLearn = async function(){
    phase='learn'; try{stopSpeech();}catch(e){}
    const item=words && words[idx];
    if(!item) return;
    try{ updateScoreBar(); }catch(e){}
    const pf=document.getElementById('progFill'); if(pf) pf.style.width=((idx/(words.length||1))*100)+'%';
    const sb=document.getElementById('streakBadge'); if(sb){ if(streak>=2){sb.style.display='';sb.textContent='🔥 '+streak;} else sb.style.display='none'; }
    const ph=item.phonetic?`<div class="wc-phonetic">${esc(item.phonetic)}</div>`:'';
    let sentHTML='';
    if(item.sentence){ sentHTML=`<div class="wc-sent">${mkSentColored(item.sentence,item.highlights,item.colors)}</div>`; if(item.sentenceTr) sentHTML+=`<div class="wc-sent-tr">${esc(item.sentenceTr)}</div>`; }
    const st=getStatus(item);
    const listName = (typeof getActiveListName==='function') ? getActiveListName() : 'Aktif Liste';
    const wc=document.getElementById('wordCard');
    if(wc){
      wc.innerHTML = `
        <div class="wc-label">${esc(listName)}${item.rowNum?`<span style="opacity:.5;font-size:10px;margin-left:8px">#${item.rowNum}</span>`:''}</div>
        ${statusPanel(item)}
        <div class="wc-word" style="cursor:pointer;transition:all .2s" onclick="explainWord('${String(item.word||'').replace(/'/g,"\\'")}','wordCard')">${esc(item.word||'')}</div>
        ${ph}
        <div class="wc-tr">${esc(item.tr||item.translation||'')}</div>
        ${sentHTML || '<div class="wc-sent" style="opacity:.8">Bu kayıtta cümle yok. Cümle tabanlı sistem için Excel’de sentence alanı doldurulmalı.</div>'}
        <button class="wm-sent-real-btn" onclick="markSentenceRealUsed()">🏆 Bu cümleyi gerçek hayatta kullandım</button>
        <div class="sent-img-wrap" id="sentImgWrap" style="margin-top:12px"><img class="sent-img" id="sentImg" alt=""><div class="img-credit" id="imgCredit"></div></div>
        <div style="display:grid;grid-template-columns:auto 1fr auto;gap:8px;align-items:center;margin-top:12px;padding:10px;background:var(--bg3);border:1.5px solid var(--border);border-radius:14px">
          <button onclick="prevWord()" style="padding:10px 14px;background:linear-gradient(135deg,#3b82f6,#2563eb);border:none;border-radius:10px;color:#fff;font-size:16px;font-weight:800;cursor:pointer;min-width:48px">◀</button>
          <div style="display:grid;grid-template-columns:1fr 1fr;gap:6px">
            <button onclick="speakWord()" style="padding:10px 8px;background:linear-gradient(135deg,#22c55e,#16a34a);border:none;border-radius:10px;color:#fff;font-size:12px;font-weight:800;cursor:pointer;font-family:'Nunito',sans-serif">🔊 Hedef Kelime</button>
            <button onclick="speakSentence()" style="padding:10px 8px;background:linear-gradient(135deg,#8b5cf6,#7c3aed);border:none;border-radius:10px;color:#fff;font-size:12px;font-weight:800;cursor:pointer;font-family:'Nunito',sans-serif">🔊 Cümle</button>
          </div>
          <button onclick="navNextWord()" style="padding:10px 14px;background:linear-gradient(135deg,#3b82f6,#2563eb);border:none;border-radius:10px;color:#fff;font-size:16px;font-weight:800;cursor:pointer;min-width:48px">▶</button>
        </div>`;
      wc.setAttribute('style',(wc.getAttribute('style')||'')+';'+cardStyle(st));
    }
    const bl=document.getElementById('btnLearned');
    if(bl){ if(isLearnedSentence(item)){bl.textContent='✓ Cümle Öğrenildi'; bl.classList.add('done');} else {bl.textContent='✅ Cümleyi Öğrendim'; bl.classList.remove('done');} }
    const bs=document.getElementById('btnSpkSent'); if(bs) bs.style.display=item.sentence?'':'none';
    const bt=document.getElementById('btnSpkTr'); if(bt) bt.style.display=(item.sentenceTr||item.tr)?'':'none';
    const pt=document.getElementById('pronunTarget'); if(pt) pt.innerHTML=item.sentence?mkSentColored(item.sentence,item.highlights,item.colors):`<strong>${esc(item.word||'')}</strong>`;
    const pp=document.getElementById('pronunPanel'); if(pp) pp.style.display='none';
    try{ resetPronun(); }catch(e){}
    ['quizArea','aiFeedback'].forEach(id=>{const el=document.getElementById(id); if(el) el.style.display='none';});
    const bn=document.getElementById('btnNext'); if(bn) bn.style.display='none';
    const counter=document.getElementById('wordCounter'); if(counter) counter.textContent=(idx+1)+' / '+(words.length||0)+' cümle';
    try{ loadSentenceImage(item.sentence||'', item.word||''); }catch(e){}
    try{ animCard('fadeIn'); }catch(e){}
    try{ updateReviewCount(); }catch(e){}
  };

  nextWord = function(){
    idx++;
    while(idx<words.length && isLearnedSentence(words[idx])) idx++;
    if(idx>=words.length) showDone(); else {phase='learn'; renderLearn();}
    try{updateWordCounter();}catch(e){}
  };

  getFilteredWords = function(){
    const arr=Array.isArray(allWords)?allWords:[];
    switch(currentFilter){
      case 'learned': return arr.filter(isLearnedSentence);
      case 'failed': return arr.filter(isFailedSentence);
      case 'unseen': return arr.filter(w=>!getStatus(w));
      case 'review': return arr.filter(isDueSentence);
      default: return arr;
    }
  };

  showList = function(){
    const currentScreen = document.querySelector('.screen.active')?.id || 'sc-word';
    try{ localStorage.setItem('listReturnScreen', currentScreen); }catch(e){}
    showScreen('sc-list');
    const s=sentenceStats();
    const ls=document.getElementById('listStats');
    if(ls) ls.innerHTML=`
      <div class="list-stat"><div class="sn" style="color:var(--green)">${s.learned}</div><div class="sl">✅ Cümle Öğrenildi</div></div>
      <div class="list-stat"><div class="sn" style="color:#ef4444">${s.due}</div><div class="sl">🔴 Tekrar</div></div>
      <div class="list-stat"><div class="sn" style="color:var(--muted)">${s.unseen}</div><div class="sl">⬜ Yeni Cümle</div></div>`;
    renderWordList();
  };

  renderWordList = function(){
    const listEl=document.getElementById('wordListEl'); if(!listEl) return;
    let filteredWords=getFilteredWords();
    if(currentSearchQuery){ filteredWords=filteredWords.filter(w=>(w.sentence||'').toLowerCase().includes(currentSearchQuery)); }
    const totalHeight=filteredWords.length*ITEM_HEIGHT;
    listEl.style.position='relative'; listEl.style.height=`${Math.min(totalHeight,600)}px`; listEl.style.overflowY='auto';
    let contentWrapper=listEl.querySelector('.virtual-content');
    if(!contentWrapper){ contentWrapper=document.createElement('div'); contentWrapper.className='virtual-content'; contentWrapper.style.position='relative'; listEl.innerHTML=''; listEl.appendChild(contentWrapper); listEl.addEventListener('scroll',()=>{virtualScrollData.scrollTop=listEl.scrollTop; updateVisibleItems();}); }
    contentWrapper.style.height=`${totalHeight}px`;
    virtualScrollData.filteredWords=filteredWords;
    virtualScrollData.visibleStart=-1; virtualScrollData.visibleEnd=-1;
    updateVisibleItems();
  };

  updateVisibleItems = function(){
    const listEl=document.getElementById('wordListEl'); const contentWrapper=listEl?.querySelector('.virtual-content'); if(!contentWrapper) return;
    const wordList=virtualScrollData.filteredWords||allWords||[];
    const scrollTop=virtualScrollData.scrollTop||listEl.scrollTop||0;
    const containerHeight=listEl.clientHeight||600;
    const start=Math.floor(scrollTop/ITEM_HEIGHT); const end=Math.ceil((scrollTop+containerHeight)/ITEM_HEIGHT)+BUFFER_SIZE;
    const visibleStart=Math.max(0,start-BUFFER_SIZE); const visibleEnd=Math.min(wordList.length,end);
    if(visibleStart===virtualScrollData.visibleStart && visibleEnd===virtualScrollData.visibleEnd) return;
    virtualScrollData.visibleStart=visibleStart; virtualScrollData.visibleEnd=visibleEnd;
    const fragment=document.createDocumentFragment();
    for(let i=visibleStart;i<visibleEnd;i++){
      const w=wordList[i]; if(!w) continue;
      const st=getStatus(w); const learned=!!(st&&st.learned); const due=isDueSentence(w); const inf=levelInfo(st);
      const itemDiv=document.createElement('div');
      itemDiv.className=`wi ${learned?'learned wm-sent-learned':'unseen'} ${due?'wm-sent-due':''}`;
      itemDiv.style.cssText=`position:absolute;top:${i*ITEM_HEIGHT}px;width:100%;height:${ITEM_HEIGHT}px;${cardStyle(st)}`;
      const badgeBg = due ? '#ef4444' : inf.color;
      const sentenceHTML=w.sentence?`<div style="font-size:14px;font-weight:800;color:var(--text);margin-top:4px;line-height:1.35">${esc(w.sentence.length>95?w.sentence.slice(0,95)+'...':w.sentence)}</div>`:'<div style="font-size:13px;color:var(--muted);margin-top:4px">Cümle yok</div>';
      const trHTML=w.sentenceTr?`<div style="font-size:12px;color:var(--muted);margin-top:2px;line-height:1.35">${esc(w.sentenceTr.length>90?w.sentenceTr.slice(0,90)+'...':w.sentenceTr)}</div>`:'';
      itemDiv.innerHTML=`
        <div class="wi-ico">${learned?'✅':due?'🔴':'⬜'}</div>
        <div class="wi-body" onclick="goToWord(${i}, virtualScrollData.filteredWords || allWords)" style="flex:1;cursor:pointer;min-width:0">
          <div class="wi-word">${esc(w.word||'')}<span style="opacity:.55;font-size:11px;margin-left:6px">hedef kelime</span></div>
          ${sentenceHTML}${trHTML}
        </div>
        <div class="wi-badges" style="display:flex;flex-direction:column;gap:4px;align-items:flex-end;min-width:112px">
          <span class="wm-sent-mini" style="background:${badgeBg};color:#fff">${due?'🔴 Tekrar':(learned?inf.label:'⚪ Yeni')}</span>
          <span class="wm-sent-mini" style="background:var(--bg3);color:var(--muted)">${dueText(st)}</span>
          ${st&&st.realLifeUsed?`<span class="wm-sent-mini" style="background:#f59e0b;color:#fff">🏆 ${st.realLifeUsed}</span>`:''}
        </div>
        <button onclick="deleteWord('${String(w.word||'').replace(/'/g,"\\'")}', event)" style="background:var(--red);color:#fff;border:none;border-radius:8px;padding:8px 10px;font-size:16px;cursor:pointer;margin-left:8px">🗑️</button>`;
      fragment.appendChild(itemDiv);
    }
    contentWrapper.innerHTML=''; contentWrapper.appendChild(fragment);
  };

  // Günlük risk paneli: ana kelime ekranında üstte görünür.
  function renderRiskPanel(){
    const main=document.getElementById('mainCard'); if(!main || document.getElementById('wmRiskPanel')) return;
    const due=(Array.isArray(allWords)?allWords:[]).filter(isDueSentence).slice(0,10);
    if(!due.length) return;
    const div=document.createElement('div'); div.id='wmRiskPanel'; div.className='wm-risk-panel';
    div.innerHTML=`<div style="font-weight:900;color:#fca5a5;font-size:13px">⚠️ Bugün unutma riski yüksek cümleler</div>${due.map((w,k)=>`<div class="wm-risk-item" onclick="goToWord(${(allWords||[]).indexOf(w)}, allWords);showScreen('sc-word')"><b>${k+1}.</b> ${esc(w.sentence||w.word||'')}</div>`).join('')}`;
    main.parentNode.insertBefore(div, main);
  }
  const oldShowScreen = typeof showScreen === 'function' ? showScreen : null;
  if(oldShowScreen){
    showScreen = function(id){ const r=oldShowScreen.apply(this, arguments); if(id==='sc-word') setTimeout(renderRiskPanel,100); return r; };
  }
  setTimeout(()=>{ try{ if(document.getElementById('sc-word')?.classList.contains('active')) renderRiskPanel(); }catch(e){} },500);

  console.log('✅ %100 cümle tabanlı öğrenme/SRS katmanı aktif');
})();

/* =====================================================================
   WORD MODE — CÜMLE TABANLI "ÖĞRENMEYE BAŞLADIM" KATMANI v6
   - "Öğrendim" mantığı iptal edildi.
   - Ana eylem: Öğrenmeye Başladım.
   - Liste kartları kaydırma bitince de durum/gerçek kullanım bilgisini gösterir.
   ===================================================================== */
(function(){
  if(window.__WM_SENTENCE_STARTED_V6__) return;
  window.__WM_SENTENCE_STARTED_V6__ = true;

  const ONE_DAY = 24*60*60*1000;
  const HEIGHT = 148;
  const LEVELS = [
    {label:'⚪ Yeni', color:'#64748b'},
    {label:'🟡 Başlandı', color:'#eab308'},
    {label:'🟠 Pekişiyor', color:'#f97316'},
    {label:'🔵 Anlıyorum', color:'#3b82f6'},
    {label:'🟢 Kullanabiliyorum', color:'#22c55e'},
    {label:'💚 Güçlü', color:'#16a34a'},
    {label:'💎 Otomatikleşti', color:'#06b6d4'}
  ];
  function core(){ return window.WMSentenceCore || null; }
  function esc(s){return String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));}
  function item(){ return (Array.isArray(window.words) ? window.words[window.idx] : null) || null; }
  function get(w){ const c=core(); return c && w ? c.getStatus(w) : null; }
  function put(w,p){ const c=core(); return c && w ? c.putStatus(w,p) : null; }
  function fmt(ts){ if(!ts) return '—'; try{return new Date(ts).toLocaleString('tr-TR',{day:'2-digit',month:'short',year:'numeric',hour:'2-digit',minute:'2-digit'});}catch(e){return '—';} }
  function isStarted(w){ const s=get(w); return !!(s && (s.learningStarted || s.startedAt || s.learned || s.realLifeUsed)); }
  function isDue(w){ const s=get(w); return !!(s && isStarted(w) && s.nextReview && s.nextReview <= Date.now()); }
  function inf(s){ const n=Math.max(0,Math.min(Number(s?.srsLevel||0),LEVELS.length-1)); return LEVELS[n] || LEVELS[0]; }
  function dueText(s){
    if(!s || !isStarted({sentence:s.sentence, word:s.word})) return '⚪ Yeni cümle';
    if(!s.nextReview) return '⏰ Tekrar planlanmadı';
    const diff=s.nextReview-Date.now();
    if(diff<=0) return '🔴 Tekrar bekliyor';
    const d=Math.ceil(diff/ONE_DAY);
    return d===1?'⏰ Yarın':'⏰ '+d+' gün sonra';
  }
  function cardStyle(s){
    if(isDue({sentence:s?.sentence, word:s?.word})) return 'border:2px solid #ef4444;background:linear-gradient(135deg,rgba(239,68,68,.18),rgba(127,29,29,.10));';
    if(!s || !isStarted({sentence:s.sentence, word:s.word})) return 'border:1.5px solid var(--border);background:var(--bg2);';
    const c=inf(s).color;
    return `border:2px solid ${c};background:linear-gradient(135deg,${c}26,rgba(15,23,42,.08));`;
  }
  function statusHTML(w){
    const s=get(w); const i=inf(s);
    if(!isStarted(w)){
      return `<div class="wm-sentence-status" style="border:1.5px solid var(--border);background:var(--bg2);padding:10px;border-radius:14px;margin:10px 0;display:grid;gap:4px">
        <div style="font-size:12px;font-weight:900;color:#e2e8f0">⚪ Yeni cümle</div>
        <div style="font-size:11px;color:var(--muted)">🚀 Öğrenmeye Başladım düğmesine basınca bu cümle SRS-1 olarak çalışmaya alınır.</div>
      </div>`;
    }
    return `<div class="wm-sentence-status" style="${cardStyle(s)}padding:10px;border-radius:14px;margin:10px 0;display:grid;gap:5px">
      <div style="display:flex;justify-content:space-between;gap:8px;align-items:center;flex-wrap:wrap">
        <span style="font-size:12px;font-weight:900;color:var(--text)">${s.learned?'✅ Öğrenildi':'🚀 Öğrenmeye Başlandı'} · ${i.label} · SRS-${s.srsLevel||1}</span>
        <span style="font-size:11px;font-weight:900;color:${isDue(w)?'#f87171':'var(--muted)'}">${dueText(s)}</span>
      </div>
      <div style="font-size:11px;color:var(--muted);line-height:1.55">🚀 Başlama: ${fmt(s.startedAt||s.learnedAt)}<br>🔄 Son tekrar: ${fmt(s.lastReview)}<br>⏰ Sonraki tekrar: ${fmt(s.nextReview)}${s.realLifeUsed?`<br>🏆 Gerçek kullanım: ${s.realLifeUsed} kez`:''}</div>
    </div>`;
  }

  function ensureCss(){
    if(document.getElementById('wmSentenceStartedV6Css')) return;
    const st=document.createElement('style'); st.id='wmSentenceStartedV6Css';
    st.textContent=`
      #wmFixedLearnedBar{border-color:rgba(245,158,11,.55)!important;background:rgba(245,158,11,.10)!important;}
      #wmFixedLearnedBar .wm-fixed-status{font-size:12px!important;font-weight:900!important;color:var(--muted,#94a3b8)!important;}
      #wmFixedLearnedBtn{background:linear-gradient(135deg,#f59e0b,#f97316)!important;border-color:rgba(251,146,60,.9)!important;min-width:154px!important;}
      #wmFixedLearnedBtn::after{content:"🚀 Öğrenmeye Başladım"!important;font-size:13px!important;}
      #wmFixedLearnedBtn.done{background:rgba(245,158,11,.18)!important;color:#fbbf24!important;box-shadow:none!important;}
      #wmFixedLearnedBtn.done::after{content:"🚀 Çalışmaya Alındı"!important;}
      .wm-sent-mini{display:inline-flex!important;align-items:center!important;justify-content:center!important;gap:4px!important;padding:3px 8px!important;border-radius:999px!important;font-size:10.5px!important;font-weight:900!important;white-space:nowrap!important;line-height:1.2!important;}
      .wi .wi-badges{position:relative!important;z-index:4!important;opacity:1!important;visibility:visible!important;display:flex!important;}
      .wi{overflow:visible!important;min-height:${HEIGHT-8}px!important;}
      #wordListEl{padding-bottom:90px!important;}
    `;
    document.head.appendChild(st);
  }
  ensureCss();

  window.beginSentenceLearning = function(){
    const w=item(); if(!w) return false;
    const old=get(w)||{}; const now=Date.now();
    put(w,{
      learningStarted:true,
      startedAt:old.startedAt||old.learnedAt||now,
      learned:false,
      lastReview:now,
      nextReview:now+ONE_DAY,
      srsLevel:Math.max(1,Number(old.srsLevel||0)),
      correctStreak:Math.max(1,Number(old.correctStreak||0))
    });
    try{showToast('🚀 Çalışmaya alındı', w.sentence||w.word||'');}catch(e){}
    try{saveProgress();}catch(e){}
    try{saveCurrentListProgress();}catch(e){}
    try{renderWordList();}catch(e){}
    try{renderLearn();}catch(e){}
    return false;
  };

  // Eski markLearned artık öğrenme başlatır; kesin öğrenildi yapmaz.
  window.markLearned = window.beginSentenceLearning;

  const oldReal = window.markSentenceRealUsed;
  window.markSentenceRealUsed = function(){
    const w=item(); if(!w) return false;
    const old=get(w)||{}; const now=Date.now();
    const nextLevel=Math.min(Math.max(Number(old.srsLevel||1)+1,2),6);
    put(w,{
      learningStarted:true,
      startedAt:old.startedAt||old.learnedAt||now,
      realLifeUsed:Number(old.realLifeUsed||0)+1,
      lastRealUse:now,
      lastReview:now,
      nextReview:now+([1,3,7,14,30,90,180][Math.max(0,nextLevel-1)]||3)*ONE_DAY,
      srsLevel:nextLevel,
      learned: nextLevel>=4 || !!old.learned
    });
    try{showToast('🏆 Gerçek kullanım kaydedildi', w.sentence||w.word||'');}catch(e){}
    try{renderWordList();}catch(e){}
    try{renderLearn();}catch(e){}
    return false;
  };

  function patchMainCard(){
    const w=item(); if(!w) return;
    const panel=document.querySelector('#wordCard .wm-sentence-status');
    if(panel){ panel.outerHTML=statusHTML(w); }
    const wc=document.getElementById('wordCard'); if(wc){ const s=get(w); wc.style.cssText += ';'+cardStyle(s); }
    const fixedStatus=document.querySelector('#wmFixedLearnedBar .wm-fixed-status');
    if(fixedStatus){ fixedStatus.textContent = isStarted(w) ? 'Bu cümle çalışmaya alınmış. İstersen gerçek kullanım ile seviyesini yükselt.' : 'Bu cümleyi çalışmaya almak için başlat.'; }
    const b=document.getElementById('wmFixedLearnedBtn');
    if(b){ b.classList.toggle('done', isStarted(w)); b.setAttribute('aria-label','Öğrenmeye Başladım'); }
    const old=document.getElementById('btnLearned');
    if(old){ old.textContent = isStarted(w)?'🚀 Çalışmaya Alındı':'🚀 Öğrenmeye Başladım'; old.onclick=function(ev){ if(ev){ev.preventDefault();ev.stopPropagation();} return window.beginSentenceLearning(); }; }
  }

  const oldRender=window.renderLearn;
  if(typeof oldRender==='function'){
    window.renderLearn = async function(){
      const r=await oldRender.apply(this,arguments);
      setTimeout(patchMainCard,0);
      return r;
    };
  }

  // Final fixed button script WM_coreMarkLearned çağırmasın diye aynı fonksiyonu da yönlendir.
  window.WM_coreMarkLearned = window.beginSentenceLearning;

  window.getFilteredWords = function(){
    const arr=Array.isArray(window.allWords)?window.allWords:[];
    switch(window.currentFilter){
      case 'learned': return arr.filter(isStarted);
      case 'failed': return arr.filter(w=>{const s=get(w); return !!(s&&s.wrong>0&&!isStarted(w));});
      case 'unseen': return arr.filter(w=>!isStarted(w));
      case 'review': return arr.filter(isDue);
      default: return arr;
    }
  };

  window.renderWordList = function(){
    const listEl=document.getElementById('wordListEl'); if(!listEl) return;
    let filteredWords=window.getFilteredWords();
    if(window.currentSearchQuery){ const q=String(window.currentSearchQuery).toLowerCase(); filteredWords=filteredWords.filter(w=>(w.sentence||w.word||'').toLowerCase().includes(q)); }
    const totalHeight=filteredWords.length*HEIGHT;
    listEl.style.position='relative'; listEl.style.height=`${Math.min(totalHeight,620)}px`; listEl.style.overflowY='auto';
    let contentWrapper=listEl.querySelector('.virtual-content');
    if(!contentWrapper){
      contentWrapper=document.createElement('div'); contentWrapper.className='virtual-content'; contentWrapper.style.position='relative'; listEl.innerHTML=''; listEl.appendChild(contentWrapper);
      listEl.addEventListener('scroll',()=>{ if(window.virtualScrollData) window.virtualScrollData.scrollTop=listEl.scrollTop; window.updateVisibleItems(); });
    }
    contentWrapper.style.height=`${totalHeight}px`;
    window.virtualScrollData = window.virtualScrollData || {};
    virtualScrollData.filteredWords=filteredWords; virtualScrollData.visibleStart=-1; virtualScrollData.visibleEnd=-1; virtualScrollData.scrollTop=listEl.scrollTop||0;
    window.updateVisibleItems();
  };

  window.updateVisibleItems = function(){
    const listEl=document.getElementById('wordListEl'); const contentWrapper=listEl?.querySelector('.virtual-content'); if(!contentWrapper) return;
    const wordList=(window.virtualScrollData&&virtualScrollData.filteredWords)||window.allWords||[];
    const scrollTop=(window.virtualScrollData&&virtualScrollData.scrollTop)||listEl.scrollTop||0;
    const containerHeight=listEl.clientHeight||620;
    const start=Math.floor(scrollTop/HEIGHT); const end=Math.ceil((scrollTop+containerHeight)/HEIGHT)+6;
    const visibleStart=Math.max(0,start-6); const visibleEnd=Math.min(wordList.length,end);
    if(window.virtualScrollData){virtualScrollData.visibleStart=visibleStart; virtualScrollData.visibleEnd=visibleEnd;}
    const fragment=document.createDocumentFragment();
    for(let i=visibleStart;i<visibleEnd;i++){
      const w=wordList[i]; if(!w) continue;
      const s=get(w); const started=isStarted(w); const due=isDue(w); const ii=inf(s);
      const div=document.createElement('div');
      div.className=`wi ${started?'learned wm-sent-learned':'unseen'} ${due?'wm-sent-due':''}`;
      div.style.cssText=`position:absolute;top:${i*HEIGHT}px;left:0;right:0;width:100%;height:${HEIGHT-8}px;box-sizing:border-box;display:flex;align-items:flex-start;gap:10px;padding:10px 12px;border-radius:14px;overflow:visible;${cardStyle(s)}`;
      const badgeBg=due?'#ef4444':(started?ii.color:'#64748b');
      const sentence=w.sentence?esc(w.sentence.length>105?w.sentence.slice(0,105)+'...':w.sentence):'Cümle yok';
      const tr=w.sentenceTr?`<div style="font-size:12px;color:var(--muted);margin-top:3px;line-height:1.35">${esc(w.sentenceTr.length>90?w.sentenceTr.slice(0,90)+'...':w.sentenceTr)}</div>`:'';
      const meta=started?`<div style="font-size:10.5px;color:var(--muted);margin-top:5px;line-height:1.35">🚀 ${fmt(s.startedAt||s.learnedAt)} · 🔄 ${fmt(s.lastReview)} · ⏰ ${fmt(s.nextReview)}</div>`:'<div style="font-size:10.5px;color:var(--muted);margin-top:5px">Henüz çalışmaya alınmadı</div>';
      div.innerHTML=`
        <div class="wi-ico" style="font-size:22px;line-height:1.2;margin-top:2px">${started?'🚀':due?'🔴':'⬜'}</div>
        <div class="wi-body" onclick="goToWord(${i}, virtualScrollData.filteredWords || allWords)" style="flex:1;cursor:pointer;min-width:0;overflow:hidden">
          <div class="wi-word" style="font-weight:900;color:${started?ii.color:'var(--text)'}">${esc(w.word||'')}<span style="opacity:.55;font-size:11px;margin-left:6px">hedef kelime</span></div>
          <div style="font-size:14px;font-weight:800;color:var(--text);margin-top:4px;line-height:1.35">${sentence}</div>${tr}${meta}
        </div>
        <div class="wi-badges" style="display:flex;flex-direction:column;gap:4px;align-items:flex-end;min-width:122px;z-index:5;visibility:visible;opacity:1">
          <span class="wm-sent-mini" style="background:${badgeBg};color:#fff">${due?'🔴 Tekrar':(started?(s.learned?'✅ Öğrenildi':'🚀 Başladı'):'⚪ Yeni')}</span>
          <span class="wm-sent-mini" style="background:var(--bg3);color:var(--muted)">${dueText(s)}</span>
          <span class="wm-sent-mini" style="background:${ii.color};color:#fff">SRS-${s?.srsLevel||0}</span>
          ${s&&s.realLifeUsed?`<span class="wm-sent-mini" style="background:#f59e0b;color:#fff">🏆 ${s.realLifeUsed} kez</span>`:''}
        </div>
        <button onclick="deleteWord('${String(w.word||'').replace(/'/g,"\\'")}', event)" style="background:var(--red);color:#fff;border:none;border-radius:8px;padding:8px 10px;font-size:16px;cursor:pointer;margin-left:4px;min-width:40px">🗑️</button>`;
      fragment.appendChild(div);
    }
    contentWrapper.innerHTML=''; contentWrapper.appendChild(fragment);
  };

  const oldShowList=window.showList;
  window.showList=function(){
    if(typeof showScreen==='function') showScreen('sc-list');
    const arr=Array.isArray(window.allWords)?window.allWords:[];
    const started=arr.filter(isStarted).length, due=arr.filter(isDue).length, fresh=arr.length-started;
    const ls=document.getElementById('listStats');
    if(ls) ls.innerHTML=`
      <div class="list-stat"><div class="sn" style="color:#f59e0b">${started}</div><div class="sl">🚀 Başlanan Cümle</div></div>
      <div class="list-stat"><div class="sn" style="color:#ef4444">${due}</div><div class="sl">🔴 Tekrar</div></div>
      <div class="list-stat"><div class="sn" style="color:var(--muted)">${fresh}</div><div class="sl">⬜ Yeni</div></div>`;
    window.renderWordList();
  };

  // Mutation sonrası sabit düğmeyi tekrar yamala.
  const mo=new MutationObserver(()=>setTimeout(patchMainCard,0));
  mo.observe(document.documentElement,{childList:true,subtree:true});
  setTimeout(()=>{try{patchMainCard();}catch(e){}},300);
  console.log('✅ v6 Öğrenmeye Başladım + kalıcı liste rozetleri aktif');
})();


/* =====================================================================
   WORD MODE — AKTİF LİSTE SEÇİMİ KALICI YÜKLEME FIX v7
   - Liste seçildiğinde gerçekten o listenin cümleleri yüklenir.
   - v5/v6 cümle katmanı window.allWords/window.words yerine ana state ile senkronize edilir.
   - Liste ekranı rozetleri kaydırma durunca kaybolmasın diye tekrar sabitlenir.
   ===================================================================== */
(function(){
  if(window.__WM_LIST_SWITCH_FIX_V7__) return;
  window.__WM_LIST_SWITCH_FIX_V7__ = true;

  function syncWindowState(){
    try{ window.allWords = allWords; }catch(e){}
    try{ window.words = words; }catch(e){}
    try{ window.idx = idx; }catch(e){}
  }
  function getLists(){
    try{
      if(typeof multiLists !== 'undefined' && Array.isArray(multiLists)) return multiLists;
    }catch(e){}
    try{return JSON.parse(localStorage.getItem('multiLists')||'[]')||[];}catch(e){return[];}
  }
  function getListWords(id, list){
    let data = null;
    try{ if(list && Array.isArray(list.words)) data = list.words; }catch(e){}
    if(!data){ try{ data = loadMultiListWords(String(id)); }catch(e){} }
    if(!data){ try{ data = JSON.parse(localStorage.getItem('multiList_words_'+id)||'null'); }catch(e){} }
    if(!Array.isArray(data)) data = [];
    return data;
  }
  function saveActiveProgress(){
    try{
      const aid = (typeof activeListId !== 'undefined') ? activeListId : localStorage.getItem('activeListId');
      if(!aid) return;
      const progress = {
        wordStatus: (typeof wordStatus !== 'undefined' ? wordStatus : {}),
        learnedSet: (typeof learnedSet !== 'undefined' ? [...learnedSet] : []),
        spacedRepetition: (typeof spacedRepetition !== 'undefined' ? spacedRepetition : {}),
        sentenceStatus: JSON.parse(localStorage.getItem('wm_sentence_status_v1')||'{}'),
        idx: (typeof idx !== 'undefined' ? idx : 0),
        score: (typeof score !== 'undefined' ? score : 100),
        streak: (typeof streak !== 'undefined' ? streak : 0),
        correctCount: (typeof correctCount !== 'undefined' ? correctCount : 0)
      };
      localStorage.setItem('listProgress_'+aid, JSON.stringify(progress));
    }catch(e){ console.warn('[v7] aktif liste ilerlemesi kaydedilemedi', e); }
  }
  function loadProgress(id){
    try{
      const raw = localStorage.getItem('listProgress_'+id);
      if(!raw) return;
      const p = JSON.parse(raw);
      if(typeof wordStatus !== 'undefined') wordStatus = p.wordStatus || {};
      if(typeof learnedSet !== 'undefined') learnedSet = new Set(p.learnedSet || []);
      if(typeof spacedRepetition !== 'undefined') spacedRepetition = p.spacedRepetition || {};
      if(p.sentenceStatus) localStorage.setItem('wm_sentence_status_v1', JSON.stringify(p.sentenceStatus));
      if(typeof idx !== 'undefined') idx = Number(p.idx||0);
      if(typeof score !== 'undefined') score = p.score ?? 100;
      if(typeof streak !== 'undefined') streak = p.streak ?? 0;
      if(typeof correctCount !== 'undefined') correctCount = p.correctCount ?? 0;
    }catch(e){ console.warn('[v7] liste ilerlemesi yüklenemedi', e); }
  }
  function setTitle(name){
    try{
      localStorage.setItem('activeListName', name);
      localStorage.setItem('wm.activeListName', name);
      localStorage.setItem('currentListName', name);
      const h=document.getElementById('currentListName'); if(h) h.textContent=name;
      if(typeof setActiveListTitle==='function') setActiveListTitle(name);
    }catch(e){}
  }

  window.switchToList = switchToList = function(id){
    const lists = getLists();
    const list = lists.find(l => String(l.id) === String(id));
    if(!list){ try{showToast('❌ Liste bulunamadı', String(id));}catch(e){} return false; }
    const data = getListWords(id, list);
    if(!data.length){ try{showToast('❌ Liste boş', 'Bu listenin cümle verisi bulunamadı');}catch(e){} return false; }

    saveActiveProgress();

    try{ activeListId = String(list.id); }catch(e){}
    localStorage.setItem('activeListId', String(list.id));
    localStorage.setItem('prevActiveListId', String(list.id));

    try{ allWords = data; words = [...data]; }catch(e){ window.allWords=data; window.words=[...data]; }
    try{ smWords=[...data]; smIdx=0; lmWords=[...data]; lmIdx=0; fcWords=[...data]; fcIdx=0; }catch(e){}
    try{ idx = 0; }catch(e){}
    loadProgress(String(list.id));
    try{ if(idx < 0 || idx >= words.length) idx = 0; }catch(e){}
    syncWindowState();
    setTitle(list.name || 'Liste');

    try{ document.querySelectorAll('div[style*="position:fixed"][style*="z-index:10000"]').forEach(el=>el.remove()); }catch(e){}
    try{ document.getElementById('bottomNav').style.display='flex'; }catch(e){}
    try{ showScreen('sc-word'); }catch(e){}
    try{ renderMultiListUI(); }catch(e){}
    try{ updateScoreBar(); }catch(e){}
    try{ renderLearn(); }catch(e){}
    try{ renderStats(); }catch(e){}
    setTimeout(()=>{ try{syncWindowState(); renderLearn();}catch(e){} },80);
    try{ showToast('✅ Liste yüklendi', `${list.name||'Liste'} — ${data.length} cümle`); }catch(e){}
    return false;
  };

  window._pickMultiList = function(id){
    try{ document.querySelectorAll('div[style*="position:fixed"][style*="z-index:10000"]').forEach(el=>el.remove()); }catch(e){}
    return window.switchToList(id);
  };

  window._pickMainList = function(){
    saveActiveProgress();
    try{ activeListId = null; }catch(e){}
    localStorage.removeItem('activeListId');
    setTitle('Ana Liste');
    try{
      const saved = JSON.parse(localStorage.getItem('learnedWords')||'[]');
      if(Array.isArray(saved) && saved.length){ allWords=saved; words=[...saved]; idx=0; }
    }catch(e){}
    syncWindowState();
    try{ showScreen('sc-word'); renderLearn(); }catch(e){}
    try{ showToast('📖 Ana Liste', 'Ana liste yüklendi'); }catch(e){}
    return false;
  };

  // Liste ekranı kendi hesaplarını window yerine gerçek ana state'ten alsın.
  const oldShowList = window.showList;
  window.showList = showList = function(){
    syncWindowState();
    if(typeof oldShowList === 'function'){
      const r = oldShowList.apply(this, arguments);
      setTimeout(syncWindowState, 0);
      return r;
    }
    try{ showScreen('sc-list'); renderWordList(); }catch(e){}
  };

  // Render sonrası rozet alanlarını tekrar görünür yap.
  function forceBadges(){
    document.querySelectorAll('.wi .wi-badges').forEach(el=>{
      el.style.display='flex'; el.style.visibility='visible'; el.style.opacity='1'; el.style.position='relative'; el.style.zIndex='20';
    });
    document.querySelectorAll('.wi').forEach(el=>{ el.style.overflow='visible'; });
  }
  ['scroll','touchend','mouseup','wheel'].forEach(ev=>document.addEventListener(ev,()=>setTimeout(forceBadges,120),true));
  setInterval(forceBadges,1000);
  syncWindowState();
  console.log('✅ v7 aktif liste yükleme düzeltmesi aktif');
})();
